SELECT 'moj-all-verified-judgments-review-002-chunk-027' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"450d293b-661c-5985-adbd-091f1278a87b","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -طلب نفقة مستقبلية لأوالد -احلكم على األب بدفع نفقة أوالده حسب تقدير قسم اخلبراء -1قولة تعالى ( لينفق ذو سعه من سعته ومن قدر عليه رزقه فلينفق مما آتاه اهلل ) -2ما رواه البخاري من حديث هند بنت عتبه قالت يا رسول اهلل إن أبا سفيان رجل شحيح وليس يعطيني ما يكفيني وولدي إال ما أخذت منه وهو ال يعلم فقال عليه الصاة والسام خذي ما","document_number":"34185311","case_number":"3412973","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باخلبر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/10","year":"1434","subject":"نفقة -طلب نفقة مستقبلية لأوالد -احلكم على األب بدفع نفقة أوالده حسب تقدير قسم اخلبراء -1قولة تعالى ( لينفق ذو سعه من سعته ومن قدر عليه رزقه فلينفق مما آتاه اهلل ) -2ما رواه البخاري من حديث هند بنت عتبه قالت يا رسول اهلل إن أبا سفيان رجل شحيح وليس يعطيني ما يكفيني وولدي إال ما أخذت منه وهو ال يعلم فقال عليه الصاة والسام خذي ما","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/10 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34185311 :‬‬\n                           ‫َر ْق ُم الدعوى‪3412973 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34293469‬تاريخه‪1434/8/10 :‬هـ‬\n\n\n\n        ‫نفقــة‪ -‬طلــب نفقــة مســتقبلية لــأوالد‪ -‬احلكــم علــى األب بدفــع نفقــة‬\n                                                       ‫أوالده حســب تقديــر قســم اخلبــراء‬\n\n\n\n\n        ‫‪ -1‬قولــة تعالــى ( لينفــق ذو ســعه مــن ســعته ومــن قــدر عليــه رزقــه فلينفــق‬\n                                                                           ‫ممــا آتــاه اهلل )‬\n        ‫‪ -2‬مــا رواه البخــاري مــن حديــث هنــد بنــت عتبــه قالــت يــا رســول اهلل‬\n        ‫إن أبــا ســفيان رجــل شــحيح وليــس يعطينــي مــا يكفينــي وولــدي إال‬\n        ‫مــا أخــذت منــه وهــو ال يعلــم فقــال عليــه الصــاة والســام خــذي مــا‬\n                                                          ‫يكفيــك وولــدك باملعــروف)‬\n        ‫‪ -3‬أجمــع العلمــاء علــى وجــوب نفقــة األب علــى أوالده إذا كانــوا بالغــن‬\n        ‫قــال ابــن املنــذر ( أجمــع كل مــن نحفــظ عنــه مــن أهــل العلــم أن علــى‬\n                                     ‫املــرء نفقــة أوالده األطفــال الذيــن ال مــال لهــم )‬\n\n\n\n\n        ‫ادعــت املدعيــة املعــرف بهــا مــن قبــل أخيهــا بــأن املدعــى عليــه تزوجهــا‬\n        ‫ودخــل بهــا الدخــول الشــرعي وأجنبــت منــه خمســة أوالد أربعــة أبنــاء‬\n        ‫وبنتـ ًا وذكــرت أســماءهم وأعمارهــم‪ ،‬وقــد طلقهــا الطلقــة الثانية وترك‬\n        ‫األوالد معهــا طلبــت املدعيــة إلــزام املدعــى عليــه بالنفقــة املســتقبلية علــى‬\n‫‪259‬‬\n\f‫األوالد صــادق املدعــى عليــه علــى مــا جــاء يف الدعــوى وقــرر أنــه ال مانــع‬\n‫لديــه مــن اإلنفــاق علــى األوالد بعــد حتديــد مقدارهــا مــن أهــل اخلبــرة‪-‬‬\n‫مت حتديــد النفقــة مــن قســم اخلبــراء‪ -‬لقولــه تعالــى (لينفــق ذو ســعة مــن‬\n‫ســعته ومــن قــدر عليــه رزقــه فلينفــق ممــا آتــاه اهلل) ولقولــه صلــى اهلل‬\n‫عليــة وســلم لهنــد بنــت عتبــه ( خــذي مــا يكفيــك وولــدك باملعــروف‬\n‫) وملــا نقلــه ابــن املنــذر مــن اإلجمــاع علــى نفقــة األطفــال الذيــن ال مــال‬\n‫لهــم علــى والدهــم لــذا صــدر احلكــم علــى األب املدعــى عليــه بدفــع‬\n‫نفقــة أوالده املذكوريــن حســبما جــاء يف قــرار قســم اخلبــراء‪ -‬قنعــت‬\n‫املدعيــة باحلكــم ولــم يقنــع املدعــى عليــه‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                     ‫االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n‫‪ ...‬القاضــي يف احملكمــة العامــة باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة باخلبــر املكلــف برقــم ‪3412973‬‬\n‫وتاريــخ ‪1434/1/7‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3460473‬وتاريــخ‬\n‫‪1434/1/7‬ه ـ ففــي يــوم اإلثنــن املوافــق ‪1434/2/18‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 8:30‬وفيهــا حضــرت املدعيــة أصالــة ‪...‬ســعودية‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وحضــر حلضورهــا معرف ـ ًا بهــا‬\n‫أخوهــا ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬كمــا حضــر‬\n‫املدعــى عليــه أصالــة ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪...‬فادعــت املدعيــة قائلــة يف دعواهــا‪ :‬لقــد تزوجــت باملدعــى عليــه قبــل‬\n‫قرابــة ثالثــة عشــرة ســنة يف عــام ‪1420‬ه ـ ودخــل بــي الدخــول الشــرعي‬\n\n                                                                                        ‫‪260‬‬\n\f      ‫وأجنبــت منــه ‪...‬املولــود يف ‪1425/12/21‬ه ـ وعمــره ثمــان ســنوات و‪...‬‬\n      ‫املولــود يف ‪1429/10/29‬ه ـ وعمــره خمــس ســنوات و‪ ...‬املولــودة يف‬\n      ‫‪1429/11/26‬ه ـ وعمرهــا أربــع ســنوت و‪ ...‬املولــود يف ‪1431/7/27‬ه ـ‬\n      ‫وعمــره ســنتان و‪ ...‬املولــود يف ‪1433/3/2‬ه ـ وقــد طلقنــي الطلقــة الثانيــة‬\n      ‫يف ‪1433/12/26‬ه ـ واألوالد معــي يف البيــت لــذا أطلــب إلــزام املدعــى‬\n      ‫عليــه بالنفقــة املســتقبلية لــأوالد هــذه دعــواي وبعــرض دعــوى املدعيــة‬\n      ‫علــى املدعــى عليــه أجــاب قائـاً‪ :‬مــا ذكرتــه املدعيــة يف دعواهــا صحيح‬\n      ‫فلقــد تزوجــت باملدعيــة بالتاريــخ املذكــور ودخلت بها الدخول الشــرعي‬\n      ‫وأجنبــت منــي ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪......‬بالتواريــخ املذكــورة وصحيــح بأننــي‬\n      ‫طلقتهــا الطلقــة الثانيــة يف ‪1433/12/26‬ه ـ وال مانــع لــدي مــن اإلنفــاق‬\n      ‫علــى األوالد بعــد حتديــد مقــدار النفقــة مــن أهــل اخلبــرة هكــذا أجــاب‬\n      ‫لــذا رفعــت اجللســة الســاعة ‪ 9.00‬للكتابــة إلــى هيئــة النظــر لتقديــر‬\n      ‫النفقــة املســتقبلية لــأوالد ويف جلســة أخــرى حضــرت املدعيــة أصالــة‬\n      ‫‪...‬برفقــة أخيهــا املعــرف بهــا ‪...‬كمــا حضــر املدعــى عليــه ‪...‬هــذا وقــد‬\n      ‫جــرت الكتابــة إلــى هيئــة النظــر باحملكمــة باخلطــاب رقــم ‪34533461‬‬\n      ‫يف ‪1434/3/24‬ه ـ بخصــوص االجتمــاع بالطرفــن وتقديــر نفقــة األوالد‬\n      ‫فوردنــا جوابهــم باخلطــاب رقــم ‪ 34533461‬يف ‪1434/3/24‬ه ـ مرفق ًا به‬\n      ‫قــرار رقــم ‪ 371‬يف ‪1434/3/34‬ه ـ ونصــه بعــد املقدمــة (عليــه نفيدكــم‬\n      ‫أنــه بعــد االطــاع علــى الراتــب واجللــوس مــع الطرفــن ودراســة حــال األب‬\n      ‫فإننــا نــرى أن تكــون النفقــة الشــهرية ألبنائــه علــى النحــو التالــي نفقــة‬\n      ‫‪550 ...‬ريــال نفقــه ‪450 ...‬ريــال نفقــة ‪500 ...‬ريــال نفقــة ‪400 ...‬ريــال نفقــة‬\n      ‫‪500 ...‬ريــال هــذا مــا نــراه) عضــو هيئــة النظــر ‪ ...‬توقيعــه عضــو هيئــة‬\n                                    ‫النظــر ‪...‬توقيعــه عضــو هيئــة النظــر ‪ ...‬توقيعــه‬\n\n\n‫‪261‬‬\n\f‫ـاء علــى مــا تقــدم مــن‬\n                         ‫وبعــرض القــرار علــى الطرفــن لــم يقنعــا بــه فبنـ ً‬\n‫ـاء علــى قــرار هيئــة النظــر ذي الرقــم ‪ 371‬املــؤرخ‬    ‫الدعــوى واإلجابــة وبنـ ً‬\n‫يف ‪1434/3/23‬ه ـ ولقولــه تعالــى (لينفــق ذو ســعة مــن ســعته ومــن قــدر‬\n‫عليــه رزقــه فلينفــق ممــا آتــاه اهلل) وملــا رواه البخــاري مــن حديــث هنــد‬\n‫بنــت عتبــه (قالــت يــا رســول اهلل إن أبــا ســفيان رجــل شــحيح وليــس‬\n‫يعطينــي مــا يكفينــي وولــدي إال مــا أخــذت منــه وهــو ال يعلــم فقــال عليــه‬\n‫الصــاة والســام خــذي مــا يكفيــك وولــدك باملعــروف) وقــد أجمــع‬\n‫العلمــاء علــى وجــوب نفقــة األب علــى أوالده إذا كانــوا بالغــن قــال ابــن‬\n‫املنــذر (أجمــع كل مــن نحفــظ عنــه العلــم أن علــى املــرء نفقــة أوالده‬\n‫األطفــال الذيــن ال مــال لهــم) لذلــك كلــه فقــد حكمــت بإلــزام املدعــى‬\n‫عليــه بدفــع مبلــغ وقــدره خمســمائة وخمســن ريــال نفقــة ‪...‬وأربعمائــة‬\n‫وخمســن ريــال نفقــة ‪...‬وخمســمائة ريــال نفقــة ‪...‬وأربعمائــة ريــال نفقــة‬\n‫‪...‬وخمســمائة ريــال نفقــة ‪...‬بتاريــخ اخلامــس والعشــرين مــن كل شــهر‬\n‫قمــري وتســلم لوالدتهــم مــا دامــوا يف حضانتهــا وبعــرض احلكــم علــى‬\n‫الطرفــن قــررت املدعيــة القناعــة بــه ولــم يقنــع املدعــى عليــه وقــرر تقــدمي‬\n‫الئحتــه االعتراضيــة فافهــم باملراجعــة بعــد ثالثــة أيــام الســتالم نســخة‬\n‫مــن احلكــم وتقــدمي الئحتــه االعتراضيــة خــال ثالثــن يــوم مــن تاريــخ‬\n‫تســجيل الصــك وأنــه إن لــم يتقــدم بشــيء خــال املــدة املشــار إليهــا فــإن‬\n‫حقــه يف االعتــراض يســقط ويكتســب احلكــم القطعيــة ففهــم ذلــك‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n                                                            ‫حــرر يف ‪1434/4/8‬ه ـ‬\n‫احلمد هلل وحده وبعد ففي يوم اخلميس املوافق ‪1434/8/25‬هـ افتتحت‬\n‫اجللســة الســاعة ‪ 9:45‬هــذا وقــد عــادت املعاملــة من محكمة االســتئناف‬\n\n\n                                                                                        ‫‪262‬‬\n\f      ‫باملنطقــة الشــرقية باخلطــاب رقــم ‪ 341660752‬يف ‪1434/8/15‬ه ـ‬\n      ‫مرفق ـ ًا بهــا قــرار املصادقــة مــن دائــرة األحــوال الشــخصية األولــى‬\n      ‫برقــم ‪ 34293469‬يف ‪1434/8/10‬ه ـ ونصــه بعــد املقدمــة (وبدراســة‬\n      ‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا‬\n      ‫املصادقــة علــى احلكــم) قاضــي االســتئناف د‪ ... .‬ختمــه وتوقيعــه قاضــي‬\n      ‫االســتئناف ‪...‬ختمــه وتوقيعــه رئيــس الدائــرة ‪...‬ختمــه وتوقيعــه وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                                   ‫يف ‪1434/8/25‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة دائ ــرة األحــوال‬\n      ‫الشــخصية األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية‬\n      ‫علــى املعاملــة املقيــدة باحملكمــة برقــم ‪/34/1660752‬ش‪1‬‬\n      ‫وتاريخ‪1434/7/10‬ه ـ الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫مبحافظــة اخلبــر املســاعد برقــم ‪ 34/60473‬وتاريــخ ‪1434/7/2‬ه ـ‬\n      ‫املرفــق بهــا الصــك الصــادر مــن فضيل ــة القاضــي بهــا الشــيخ ‪.../‬املســجل‬\n      ‫برقــم ‪ 34185311‬وتاريخ‪1434/4/10‬ه ـ اخلــاص بدعوى‪.../‬ضــد‪.../‬‬\n      ‫يف قضيــة نفقــة‪ .‬وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم مــع تنبيــه فضيلــة القاضــي‬\n      ‫إلــى التصريــح يف احلكــم بــأن هــذا مشــمول بالنفــاذ املعجــل حســب مــا‬\n      ‫نصــت عليــه التعليمــات ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                          ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/8‬ه ـ‬\n\n\n\n\n‫‪263‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":259,"source_page_end":263,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aad80365242a2c27b562a7156b7c3734c1f6fd7c74ddf3afb03e624a0d731f02","normalized_text_hash":"18030c0c9fd8fe5c447eb4f275223cf1329d3f6bc00a37fee5f257a8f9afe61c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p259-34185311"},{"id":"9d391827-9668-50cd-b16b-3a844bb29b13","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -مطالبة مطلقة بنفقة عدتها -مطالبة أم بنفقة ابنتها املاضية واملستقبلية -مطالبة بزيادة نفقة ماضية لعدم كفايتها -املطالبة مبتعة الطاق -حلف اليمن على نية الرجوع بالنفقة -احلكم بتسليم نفقة ماضية للزوجة -حكم بتسليم نفقة ماضية و مستقبلية لالبنة .","document_number":"34194787","case_number":"33226980","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/22","year":"1434","subject":"نفقة -مطالبة مطلقة بنفقة عدتها -مطالبة أم بنفقة ابنتها املاضية واملستقبلية -مطالبة بزيادة نفقة ماضية لعدم كفايتها -املطالبة مبتعة الطاق -حلف اليمن على نية الرجوع بالنفقة -احلكم بتسليم نفقة ماضية للزوجة -حكم بتسليم نفقة ماضية و مستقبلية لالبنة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/22 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34194787 :‬‬\n                    ‫َر ْق ُم الدعوى‪33226980 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34240512‬تاريخه‪1434/6/13 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬مطالبــة مطلقــة بنفقــة عدتهــا ‪ -‬مطالبــة أم بنفقــة ابنتهــا‬\n‫املاضيــة واملســتقبلية ‪ -‬مطالبــة بزيــادة نفقــة ماضيــة لعــدم كفايتهــا‬\n‫‪ -‬املطالبــة مبتعــة الطــاق ‪ -‬حلــف اليمــن علــى نيــة الرجــوع بالنفقــة‬\n‫‪ -‬احلكــم بتســليم نفقــة ماضيــة للزوجــة ‪ -‬حكــم بتســليم نفقــة ماضيــة‬\n                                                    ‫و مســتقبلية لالبنــة ‪.‬‬\n\n\n\n\n‫‪ -1‬قــال شــيخ اإلســام ابــن تيميــة رحمــه اهلل « إذا كان االبــن يف‬\n‫حضانــة امــه فأنفقــت عليــه تنــوي بذلــك الرجــوع علــى األب فلهــا أن‬\n      ‫ترجــع علــى األب يف أظهــر قولــي العلمــاء» الفتــاوى ‪. 134/29‬‬\n‫‪ -2‬جــاء يف املدونــة قــال مالــك ‪ :‬إمنــا خفــف عنــدي يف املتعــة ولــم يجبــر‬\n‫عليهــا املطلــق يف القضــاء يف رأيــي ألنــى أســمع اهلل يقــول «حقــا علــى‬\n                  ‫املتقــن وحقــا علــى احملســنني» « فلذلــك خفــف ولــم ُي ْقـ َ‬\n‫ـض بهــا» املدونــة‬\n                                                             ‫الكبــرى ‪. 332/5‬‬\n‫‪ -3‬وجــاء يف املغنــى (‪« )142-137/10‬اســتحباب املتعــة للمطلقــة‬\n                                 ‫املدخــول بهــا ســواء ســمى لهــا املهــر أم ال»‬\n\n\n\n\n                                                                                     ‫‪264‬‬\n\f      ‫ادعــى املدعــى وكالــة ضــد املدعــى عليــه وكالــة أن املدعيــة أصالــة‬\n      ‫كانــت زوجــة للمدعــى عليــه أصالــة ورزق منهــا ببنــت واحــدة يف حضانــة‬\n      ‫والدتهــا وقــد قــام املدعــى عليــه بتطليــق املدعيــة يف ‪1433/3/21‬ه ـ‬\n      ‫وطالــب املدعــى وكالــة بنفقــة املدعيــة خــال فتــرة عدتهــا ونفقــة‬\n      ‫شــهرية للبنــت وإلــزام املدعــى عليــه بتســليم املدعيــة متعــة الطــاق‪- .‬‬\n      ‫أجــاب املدعــي عليــه وكالــة باملصادقــة علــى الدعــوى ودفــع بــأن موكله‬\n      ‫قــد ســلم املدعيــة نفقــة عدتهــا ألــف وســتمائة ريــال وكان ملتزمــا بنفقــة‬\n      ‫البنــت خمســمائة ريــال شــهري ًا وأمــا متعــة الطــاق فــا يوافــق عليهــا‪،‬‬\n      ‫أقــر املدعــي وكالــة مبــا وصــل موكلتــه مــن نفقــة عدتهــا ونفقــة البنــت‬\n      ‫ولكنــه طالــب بتقديرهــا وحســم الفــرق‪ ،‬مت تقديــر نفقــة املدعيــة وقــت‬\n      ‫عدتهــا بألــف وســتمائة وســتني ريــا ًال ونفقــة البنــت شــهري ًا ســبعمائة‬\n      ‫ريــال عــن طريــق هيئــة النظــر ليكــون الفــرق مبلغــا قــدرة ثالثــة اآلف‬\n      ‫ومائتــا ريــال‪ ،‬قــرر املدعــى عليــه عــدم القناعــة بالقــرار فيمــا يخــص‬\n      ‫نفقــة البنــت ووافــق علــى نفقــة املدعيــة‪ ،‬وقــرر املدعــي وكالــة القناعــة‬\n      ‫بالقــرار‪ ،‬حضــرت املدعيــة أصالــة وقــررت أنهــا كانــت تنفــق علــى‬\n      ‫البنــت بنيــة الرجــوع علــى املدعــى عليــه وطلــب املدعــى عليــه ميينهــا علــى‬\n      ‫ذلــك وحلفــت‪ ،‬قــرر ناظــر القضيــة لألســباب املرصــودة يف نــص القضيــة‬\n      ‫بإلــزام املدعــى عليــه بدفــع ســتة وســتني ريــا ًال للمدعيــة وهــو ميثــل املبلــغ‬\n      ‫املتبقــي مــن نفقتهــا املقــررة وإلزامــه بتســليم املدعيــة مبلغــا قــدره ثالثــة‬\n      ‫اآلف ومائتــا ريــال وهــو مــا ميثــل املبلــغ املتبقــي مــن نفقــة البنــت املاضيــة‬\n      ‫وإلزامــه بدفــع نفقــة مســتقبلية للبنــت مبلغا قدره ســبعمائة ريال شــهرياً‪،‬‬\n\n‫‪265‬‬\n\f‫ورد دعــوى املدعيــة مبطالبتهــا مبتعــة الطــاق‪ ،‬قــررت املدعيــة القناعــة‬\n‫وقــرر املدعــى عليــه عــدم القناعــة‪ .‬صــدر قــرار محكمــة االســتئناف‬\n                                        ‫بالريــاض باملوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة‬\n‫العامــة مبحافظــة اخلــرج وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة باخلــرج ‪ /‬املكلــف برقــم ‪33226980‬‬\n‫وتاريــخ ‪ 1433/03/30‬ه ـ املقيــدة باحملكمــة برقــم ‪33604946‬‬\n‫وتاريــخ ‪ 1433/03/30‬ه ـ ويف يــوم األحــد املوافــق‪ 1434/01/11‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 11 : 00‬وفيهــا حضــر ‪ .......‬ســعودي اجلنســية‬\n‫ا عــن املدعيــة ‪.......‬‬\n                       ‫مبوجــب الســجل املدنــي رقــم ‪ .......‬بصفتــه وكي ـ ً‬\n‫ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .......‬مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة عــدل محافظــة اخلــرج برقــم ‪ 33286745‬وتاريــخ‬\n‫‪1433/6/8‬ه ـ املخــول لــه حــق املطالبــة واملداعــاة واملخاصمــة وســماع‬\n‫الدعــاوي واإلقــرار واإلنــكار والصلــح والتنــازل واإلســتالم والتســليم‪..‬‬\n‫إلــخ وادعــى علــى احلاضــر معــه ســعودي اجلنســية مبوجــب الســجل‬\n‫ا عــن ســعودي اجلنســية مبوجــب الســجل‬       ‫املدنــي رقــم بصفتــه وكي ـ ً‬\n‫املدنــي مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الدلــم برقــم‬\n‫‪ 3481‬وتاريــخ ‪1433/5/26‬ه ـ املجلــد (‪ )3/2716‬املخــول لــه فيهــا حــق‬\n‫املطالبــة واملرافعــة واملدافعــة واملخاصمــة واإلقــرار واإلنــكار والصلــح‬\n‫ا يف دعــواه ‪ :‬بــأن مــوكل املدعــى عليــه‬   ‫واإلســتالم والتســليم‪..‬إلخ قائ ـ ً‬\n‫كان زوج ـ ًا ملوكلتــي مبوجــب عقــد نــكاح صحيــح وقــد أجنبــت لــه‬\n                                                                                    ‫‪266‬‬\n\f      ‫موكلتــي بنتـ ًا عمرهــا اآلن ســنة وثالثــة أشــهر تقريبـ ًا اســمها‪ ...‬وقــد قــام‬\n      ‫مــوكل املدعــى عليــه بتطليــق موكلتــي يف ‪1433/3/21‬ه ـ مبوجــب‬\n      ‫الصــك الصــادر مــن محكمــة ‪ ...‬برقــم ‪ 3/33‬يف ‪1433/3/26‬ه ـ‬\n      ‫علمـ ًا بــأن ابنــة موكلتــي يف حضانتهــا لــذا فإننــي أطلــب إلــزام مــوكل‬\n      ‫املدعــى عليــه بدفــع نفقــة شــهرية البنتــه كمــا أطلــب إلزامــه بدفــع نفقــة‬\n      ‫موكلتــي خــال فتــرة عدتهــا كمــا أطلــب إلزامــه بدفــع متعــة الطــاق‬\n      ‫هــذه دعــواي وبســؤال املدعــى عليــه وكالــة أجــاب بقولــه ‪ :‬مــا ذكــره‬\n      ‫املدعــي وكالــة مــن أن موكلتــه كانــت زوجــة ملوكلــي مبوجــب عقــد‬\n      ‫نــكاح صحيــح وأنهــا أجنبــت لــه بنت ـ ًا اســمها وعمرهــا ســنة وثالثــة‬\n      ‫أشــهر تقريب ـ ًا فصحيــح وأمــا نفقــة موكلتــه يف فتــرة عدتهــا فقــد قــام‬\n      ‫موكلــي بتحويــل ألــف وســتمائة ريــال ملوكلــة املدعــي وأمــا نفقــة البنــت‬\n      ‫فموكلــي منــذ ســبعة أشــهر وهــو يقــوم بتحويــل خمســمائة ريــال شــهري ًا‬\n      ‫حلســاب موكلــة املدعــي وأمــا متعــة الطــاق فلــن يدفعهــا موكلــي‬\n      ‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــي وكالــة قــال ســأراجع‬\n      ‫موكلتــي وأفيدكــم يف اجللســة القادمــة ويف جلســة أخــرى جــرى ســؤال‬\n      ‫املدعــي وكالــة عمــا ذكــره املدعــى عليــه وكالــة يف اجللســة املاضيــة‬\n      ‫ا ‪ :‬مــا ذكــره املدعــى عليــه مــن أنــه قــام بتحويــل ألــف‬    ‫فأجــاب قائ ـ ً‬\n      ‫وســتمائة ريــال نفقــة ملوكلتــي فصحيــح كمــا أن مــوكل املدعــى عليــه‬\n      ‫قــام بتحويــل أربعــة آالف وســبعمائة ريــال نفقــة البنتــه يف الفتــرة املاضيــة‬\n      ‫لــذا فإننــي أطلــب تقديــر النفقــة ملوكلتــي والبنــة موكلتــي وحســم‬\n      ‫املبلــغ الــذي وصــل ملوكلتــي منــه كمــا أطلــب متعــة الطــاق هكــذا‬\n      ‫قــرر وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال ال مانــع مــن حتديــد‬\n      ‫نفقــة مســتقبلية البنــة موكلــي وأمــا متعــة الطــاق فموكلــي لــن يدفعهــا‬\n\n\n‫‪267‬‬\n\f‫هكــذا قــرر وكنــت قــد كتبــت لهيئــة النظــر لتقديــر النفقــة املاضيــة‬\n‫واملســتقبلية للمدعيــة والبنــة املدعــى عليــه فوردنــا جــواب هيئــة النظــر‬\n‫رقــم ‪ 33/798397‬يف ‪1433/6/25‬ه ـ وجوابهــم رقــم ‪33/286823‬‬\n‫يف ‪1433/8/12‬ه ـ واملتضمــن تقديــر نفقــة املدعيــة بخمســمائة ريــال‬\n‫شــهري ًا للفتــرة مــن ‪1433/3/21‬ه ـ إلــى ‪1433/6/30‬ه ـ وهــي فتــرة عــدة‬\n‫الطــاق ومجمــوع النفقــة يف هــذه املــدة ألــف وســتمائة وســتة وســتون‬\n‫ريــا ًال كمــا مت تقديــر نفقــة البنــت بســبعمائة ريــال شــهري ًا ‪ .‬وبعــرض‬\n‫ذلــك علــى املدعــي وكالــة قنــع بتقديــر هيئــة النظــر كمــا جــرى عــرض‬\n‫ا ‪ :‬أمــا‬‫تقديــر هيئــة النظــر علــى املدعــى عليــه وكالــة فأجــاب قائ ـ ً‬\n‫تقديــر نفقــة املدعيــة فأنــا قانــع بــه وأمــا تقديــر النفقــة للبنــت فأنــا غيــر‬\n‫قانــع بــه وهــو كثيــر وراتــب موكلــي وإلتزاماتــه املاديــة كثيــرة وهيئــة‬\n‫النظــر لــم تقـ ّـدر ذلــك بنــاء علــى االلتزامــات التــي علــى موكلــي وقــد‬\n‫قـ ّـدرت ذلــك بنــاء علــى الراتــب فقــط علمـ ًا بــأن موكلــي قــد تــزوج وعليــه‬\n‫قســط شــهري قــدره ألــف وثالثمائــة وثالثــة وســتون ريــا ًال كمــا أنــه قــد‬\n‫اســتأجر ســكن ًا بعشــرين ألــف ريــال ســنوي ًا كمــا يوجــد عليــه مديونيــة‬\n‫واحــد وأربعــون ألف ـ ًا وخمســمائة ريــال كمــا أن بنــك التســليف يأخــذ‬\n‫منــه قســط ًا قــدره ســبعمائة وخمســن ريــا ًال هكــذا قــرر وبنــاء علــى‬\n‫ذلــك فقــد قــررت إعــادة الكتابــة لهيئــة النظــر لتقديــر نفقــة البنــت بعــد‬\n‫اإلطــاع علــى مــا يذكــره املدعــى عليــه وكالــة ورفعــت اجللســة لذلــك‬\n‫ويف جلســة أخــرى حضــرت املدعيــة أصالــة ســعودية اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم واملعـ ّـرف بهــا مــن قبــل املدعــي وكالــة كمــا حضــر‬\n‫يف هــذه اجللســة املدعــى عليــه ويف هــذه اجللســة جــرى ســؤال املدعيــة هــل‬\n‫كانــت تنــوي الرجــوع علــى املدعــى عليــه أصالــة يف نفقــة الطفلة املاضية‬\n\n\n                                                                                           ‫‪268‬‬\n\f      ‫فأجابــت قائلــة ‪ :‬نعــم كنــت أنــوي الرجــوع علــى املدعــى عليــه يف النفقــة‬\n      ‫هكــذا أجابــت وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال ‪ :‬أطلــب‬\n      ‫ميــن املدعيــة علــى أنهــا كانــت تنــوي الرجــوع علــى موكلــي يف النفقــة‬\n      ‫املاضيــة للطفلــة هكــذا قــرر وبعــرض ذلــك علــى املدعيــة اســتعدت‬\n      ‫بــأداء اليمــن‪ ،‬فجــرى حتذيرهــا مــن مغبــة اليمــن الكاذبــة ‪ ،‬فحلفــت‬\n      ‫قائلــة ‪( :‬واهلل العظيــم إننــي كنــت أنفــق علــى ابنتــي ‪ ...‬ويف نيتــي الرجــوع‬\n      ‫بالنفقــة علــى والدهــا املدعــى عليــه أصالــة واهلل العظيــم ) هكذا حلفت‬\n      ‫ثــم جــرى ســؤال املدعيــة عــن النفقــة املاضيــة التــي قــام بتحويلهــا املدعــى‬\n      ‫عليــه البنتــه (‪ ).....‬فأجابــت قائلــة بأنــه قــام بتحويــل خمســة آالف ومائتــي‬\n      ‫ريــال فقــط الغيــر وأنــا أطلــب الباقــي وقــدره ثالثــة آالف ومائتــي ريــال‬\n      ‫باإلضافــة للنفقــة املســتقبلية الشــهرية للطفلــة هكــذا أجابــت وبعــرض‬\n      ‫ذلــك علــى املدعــى عليــه قــال صحيــح بــأن موكلــي قــام بتحويــل خمســة‬\n      ‫آالف ومائتــي ريــال البنتــه ‪ ...‬ولكــن املتبقــي مــن النفقــة املاضيــة ثمامنائــة‬\n      ‫ريــال فقــط باعتبــار أن النفقــة خمســمائة ريــال شــهري ًا وليســت ســبعمائة‬\n      ‫ريــال شــهري ًا هكــذا قــرر ثــم جــرى اإلطــاع علــى جــواب هيئــة اخلبــراء‬\n      ‫يف احملكمــة رقــم ‪ 34/808920‬وتاريــخ ‪1434/4/7‬ه ـ واملتضمــن‬\n      ‫ـدم‬\n      ‫تقديــر نفقــة الطفلــة مببلــغ ســبعمائة ريــال شــهري ًا فبنــاء علــى مــا تقـ ّ‬\n      ‫ذكــره مــن الدعــوى واإلجابــة وبنــاء علــى مــا ورد يف خطابــات أعضــاء‬\n      ‫هيئــة اخلبــراء املشــار إليهــا آنفـ ًا مــن تقديــر نفقــة املدعيــة أصالــة املاضيــة‬\n      ‫مببلــغ ألــف وســتمائة وســتة وســتون ريــا ًال ومبــا أن املدعــي وكالــة‬\n      ‫واملدعــى عليــه وكالــة قــد اقتنعــا بتقديــر أعضــاء هيئــة اخلبــراء فيمــا‬\n      ‫يتعلــق بالنفقــة املاضيــة للمدعيــة أصالــة ومبــا أن املدعــي وكالــة قــد‬\n      ‫أقــر بتحويــل املدعــى عليــه ملبلــغ ألــف وســتمائة ريــال نفقــة ملوكلتــه وبنــاء‬\n\n\n‫‪269‬‬\n\f‫علــى مــا ورد يف قــرار هيئــة اخلبــراء رقــم ‪ 34/808920‬واملتضمــن تقديــر‬\n‫نفقــة الطفلــة (‪ ).....‬مببلــغ ســبعمائة ريــال شــهري ًا وبنــاء علــى مــا قــرره‬\n‫أهــل العلــم مــن أن الطفــل إذا كان يف حضانــة أمــه فأنفقــت عليــه تنــوي‬\n‫بذلــك الرجــوع علــى األب فلهــا الرجــوع ‪ ،‬قــال شــيخ اإلســام ‪( :‬إذا كان‬\n‫االبــن يف حضانــة أمــه ‪ ،‬فأنفقــت عليــه تنــوي بذلــك الرجــوع علــى األب‬\n‫‪ ،‬فلهــا أن ترجــع علــى األب يف أظهــر قولــي العلمــاء ‪ )..‬الفتــاوى ‪134/29‬‬\n‫‪ ،‬ومبــا أن املدعيــة قــد حلفــت اليمــن املطلوبــة علــى أنهــا كانــت تنفــق‬\n‫علــى الطفلــة بنيــة الرجــوع علــى أبيهــا ‪ ،‬ومبــا أن املدعيــة قــد أقــرت بــأن‬\n‫املدعــى عليــه أصالــة قــد دفــع خمســة آالف ومائتــي ريــال نفقــة البنتــه يف‬\n‫الفتــرة املاضيــة ‪ ،‬ومبــا أن متعــة الطــاق مســتحبة وليســت واجبــة كمــا‬\n‫ذكــر ذلــك أهــل العلــم ‪ ،‬جــاء يف املدونــة ‪ ( :‬قــال مالــك‪ :‬إمنــا خفــف‬\n‫عنــدي يف املتعــة ولــم يجبــر عليهــا املطلــق يف القضــاء يف رأيــي ألنــي‬\n‫أســمع اهلل يقــول ( حقـ ًا علــى املتقــن ) و(حقـ ًا علــى احملســنني ) فلذلــك‬\n‫خففــت‪ ،‬ولــم يقــض بهــا )‪ .‬املدونــة الكبــرى ‪ ، 332/5‬وجــاء يف املغنــي‬\n‫‪( 142-137/10‬اســتحباب املتعــة للمطلقــة املدخــول بهــا ســواء سـ ّـمي‬\n‫لهــا املهــر أم ال ) ولكــون املدعــى عليــه وكالــة قــد رفــض أن يدفــع‬\n‫موكلــه متعــة الطــاق لــكل مــا ســبق فقــد قــررت مــا يلــي ‪ :‬أوال ً ‪ :‬إلــزام‬\n‫مــوكل املدعــى عليــه بدفــع ســتة وســتني ريــا ًال للمدعيــة وهــو مي ّثــل املبلــغ‬\n‫املتبقــي مــن النفقــة املقــررة لهــا مــن قبــل أعضــاء هيئــة اخلبــراء ‪ .‬ثاني ـ ًا ‪:‬‬\n‫إلــزام مــوكل املدعــى عليــه بدفــع ثالثــة آالف ومائتــي ريــال للمدعيــة‬\n‫وهــو مــا مي ّثــل امللــغ املتبقــي مــن النفقــة املاضيــة للطفلــة (‪ . ).....‬ثالث ـ ًا ‪:‬‬\n‫إلــزام مــوكل املدعــى عليــه بدفــع نفقــة مســتقبلية البنتــه ‪ ...‬وقدرهــا‬\n‫ســبعمائة ريــال شــهري ًا ‪ .‬رابع ـ ًا ‪ :‬رد دعــوى املدعيــة فيمــا يتعلــق بطلبهــا‬\n\n\n                                                                                               ‫‪270‬‬\n\f      ‫متعــة الطــاق وأخليــت ســبيل املدعــى عليــه أصالــة جتــاه هــذه املطالبــة ‪.‬‬\n      ‫ومبــا ســبق حكمــت وبعــرض احلكــم علــى الطرفــن قنعــت املدعيــة ولــم‬\n      ‫يقنــع املدعــى عليــه وكالــة وطلــب االســتئناف فأجيــب لطلبــه وجــرى‬\n      ‫تســليمه نســخة مــن احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن يومــا‬\n      ‫مــن تاريــخ اليــوم وبعدهــا يســقط حقــه يف االســتئناف ويكتســب احلكم‬\n      ‫القطعيــة ففهــم ذلــك ختمــت يف الســاعة العاشــرة وعليــه جــرى التوقيــع‬\n                ‫وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/4/22‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n      ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n      ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫باخلــرج املكلــف برقــم ‪ 33604946‬وتاريــخ ‪1434/5/21‬ه ـ املرفــق بهــا‬\n      ‫الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ ).....( /‬املســجل‬\n      ‫برقــم ‪ 34194787‬وتاريــخ ‪1434/4/22‬ه ـ اخلــاص بدعــوى‪ ).....(/‬ضــد‬\n      ‫‪ ).....(/‬يف قضيــة نفقــة أوالد وقــد تضمــن الصــك حكــم فضيلتــه مبــا‬\n      ‫هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n      ‫االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى احلكــم‪،‬‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪271‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":264,"source_page_end":271,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c9e294b29ef751aa6654ea7056bd351577e3a6807de9b4949b0d0f0652a6bbef","normalized_text_hash":"d4725a0440d61576dca54f5960c56d9f79043674a8f192ed90f5c937012eb077","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p264-34194787"},{"id":"dd000c7c-956a-5004-a002-48c50acfa2d8","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة (زوجة -أوالد -حمل) -املطالبة بالنفقة املاضية واملستقبلية -تطبيق املادة 50من نظام املرافعات الشرعية املتعلقة بفسخ الوكالة أثناء الترافع دون موافقه المحكمة وقبل إباغ الطرف اآلخر -حلف الزوجة اليمن بعدم إنفاق الزوج -احلكم على املدعى عليه بدفع النفقة املاضية واملستقبلية -نفقة احلمل جتب للمطلقه البائن .","document_number":"34199029","case_number":"3386021","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف يف الساعة الواحدة من هذا اليوم األربعاء املوافق 1433/8/14ه عقدت اجللسة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/28","year":"1434","subject":"نفقة -نفقة (زوجة -أوالد -حمل) -املطالبة بالنفقة املاضية واملستقبلية -تطبيق املادة 50من نظام املرافعات الشرعية املتعلقة بفسخ الوكالة أثناء الترافع دون موافقه المحكمة وقبل إباغ الطرف اآلخر -حلف الزوجة اليمن بعدم إنفاق الزوج -احلكم على املدعى عليه بدفع النفقة املاضية واملستقبلية -نفقة احلمل جتب للمطلقه البائن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/28 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34199029 :‬‬\n                     ‫َر ْق ُم الدعوى‪3386021 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34248489‬تاريخه‪1434/6/21 :‬هـ‬\n\n\n\n  ‫نفقــة ‪ -‬نفقــة (زوجــة ‪ -‬أوالد ‪ -‬حمــل) ‪ -‬املطالبــة بالنفقــة املاضيــة‬\n  ‫واملســتقبلية‪ -‬تطبيــق املــادة ‪ 50‬مــن نظــام املرافعــات الشــرعية املتعلقــة‬\n  ‫بفســخ الوكالــة أثنــاء الترافــع دون موافقــه احملكمــة وقبــل إبــاغ‬\n  ‫الطــرف اآلخــر‪ -‬حلــف الزوجــة اليمــن بعــدم إنفــاق الــزوج ‪ -‬احلكــم‬\n  ‫علــى املدعــى عليــه بدفــع النفقــة املاضيــة واملســتقبلية ‪ -‬نفقــة احلمــل‬\n                                                    ‫جتــب للمطلقــه البائــن ‪.‬‬\n\n\n\n\n ‫‪ -1‬قولــه تعالــى ( وإن كــن أوالت حمــل فأنفقــوا عليهــن حتــى يضعــن‬\n                                                              ‫حملهــن)‪.‬‬\n                              ‫‪ -2‬قوله تعالى ( لينفق ذو سعه من سعته )‪.‬‬\n         ‫‪ -3‬قوله تعالى ( وعلى املولود له رزقهن وكسوتهن باملعروف)‪.‬‬\n        ‫‪-4‬الالئحة األولى من املادة (‪ )50‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n  ‫ادعــى وكيــل املدعيــة بــأن املدعــى عليــه أصالــة كان زوجــا ملوكلتــه‬\n  ‫ومت فســخ نكاحهــا منــه وأجنبــت منــه ثالثــة أبنــاء األول عمــره خمســة‬\n  ‫أعــوام والثانــي عمــره ثالثــة أعــوام والثالــث عمــره ثالثــة أشــهر‪ -‬طلــب‬\n  ‫املدعــي وكالــة إلــزام املدعــى عليــه أصالــة بدفــع نفقــة موكلتــه‬\n                                                                                    ‫‪272‬‬\n\f      ‫املاضيــة حتــى تاريــخ فســخ النــكاح ‪ -‬ونفقــة األوالد املاضيــة ‪ -‬وأجــرة‬\n      ‫احلمــل‪ -‬ونفقــة األبنــاء الثالثــة املســتقبلية‪ -‬قــرر املدعــى عليــه وكالــة‬\n      ‫ا عنــه‪ -‬بنــاء علــى‬  ‫بأنــه فســخ وكالتــه عــن موكلــه ولــم يعــد وكي ـ ً‬\n      ‫املــادة ‪ 50‬مــن نظــام املرافعــات الشــرعية جــرى ســؤال املدعــي وكالــة‬\n      ‫هــل املدعــى عليــه أصالــة أبلغــه أو أبلــغ موكلتــه بعــزل الوكيــل وقبــول‬\n      ‫انعزالــه وتعيــن أحــد بــدال عنــه وأنــه سيباشــر الدعــوى بنفســه فقــال‬\n      ‫لــم يحصــل شــي مــن ذلــك‪ -‬ألن هــذا االعتــزال مــن الوكيــل مت دون‬\n      ‫موافقــة احملكمــة وقبــل إبــاغ املدعــى فقــد قــرر القاضــي الســير يف‬\n      ‫إجــراءات الدعــوى‪ -‬ورد جــواب مكتــب الصلــح املتضمــن تعــذر الصلــح‬\n      ‫بــن الطرفيــن وتقديــر النفقــة املاضيــة للمدعيــة وأبنائهــا املذكوريــن‬\n      ‫وحتديــد نفقــة مســتقبلية وكذلــك أجــرة احلمــل‪ -‬يف جلســة أخــرى‬\n      ‫حضــرت املدعيــة برفقــة والدهــا ولــم يحضــر املدعــى عليــه وال وكيــل‬\n      ‫عنــه‪ -‬حلفــت املدعيــة اليمــن بعــد تخويفهــا بــاهلل عــز وجــل علــى أن‬\n      ‫املدعــى عليــه لــم ينفــق عليهــا وال علــى أبنائهــا املــدة املاضيــة‪ -‬ورد‬\n      ‫اجلــواب مــرة أخــرى مــن قســم اإلصــاح والتحكيــم املتضمــن أن أجــرة‬\n      ‫احلمــل داخلــة يف نفقــة الزوجــة وليســت مســتقلة‪ -‬بنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى وألن مــا قــرره املدعــى عليــه وكالــة غيــر مقبــول بنــاء علــى‬\n      ‫الالئحــة األولــى مــن املــادة ‪ 50‬مــن نظــام املرافعــات الشــرعية ولقولــة‬\n      ‫تعالــى (وإن كــن أوالت حمــل فأنفقــوا عليهــن حتــى يضعــن حملهــن)‬\n      ‫وقولــه تعالــى (لينفــق ذو ســعة مــن ســعته) وقولــه تعالــى (وعلــى املولــود لــه‬\n      ‫رزقهــن وكســوتهن باملعــروف) لــذا صــدر احلكــم بإلــزام املدعــى عليــه‬\n      ‫بدفــع نفقــة املدعيــة وأوالده املاضيــة واملســتقبلة لــأوالد وصــرف النظــر‬\n      ‫عــن طلــب املدعيــة نفقــة حملهــا لدخولهــا يف تقديــر النفقــة املاضيــة وألن‬\n\n\n‫‪273‬‬\n\f‫نفقــة احلامــل جتــب للمطلقــه البائــن ‪ -‬قنعــت املدعيــة باحلكــم‪ -‬قــرر‬\n‫القاضــي تزويــد املدعــى عليــه بنســخة مــن احلكــم لتقــدمي اعتراضــه‪-‬‬\n                            ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n‫‪ ...‬القاضــي باحملكمــة العامــة بالطائــف يف الســاعة الواحــدة مــن هــذا‬\n‫اليــوم األربعــاء املوافــق ‪1433/8/14‬ه ـ عقــدت اجللســة للنظــر يف دعــوى‬\n‫‪ ...‬ضــد ‪ ...‬بطلــب نفقــة املقيــدة برقــم ‪ 33226351‬يف ‪1433/2/3‬ه ـ‬\n‫واحملالــة لنــا مــن فضيلــة الرئيــس برقــم ‪ 3386021‬يف ‪1433/2/3‬ه ـ‬\n‫ويف هــذه اجللســة حضــر ‪ ...‬مصــري اجلنســية حســب رخصــة اإلقامــة‬\n‫ا عــن ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬      ‫رقــم ‪ ...‬بصفتــه وكيـ ً‬\n‫العــدل الثانيــة بالطائــف برقــم‪ 3142‬يف ‪1433/1/15‬ه ـ والتــي تخولــه‬\n‫إقامــة الدعــوى ضــد املدعــى عليــه واملطالبــة بالطــاق واحلضانــة والنفقــة‬\n‫واملرافعــة واملدافعــة وحضــور اجللســات واإلقــرار والصلــح والتنــازل‬\n‫وادعــى علــى احلاضــر معــه ‪...‬مصــري اجلنســية حســب رخصــة اإلقامــة‬\n‫رقــم ‪...‬بصفتــه وكيــا عــن ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫العــدل الثانيــة بالطائــف برقــم ‪ 57505‬يف ‪1432/11/19‬ه ـ والتــي‬\n‫تخولــه إقامــة وســماع عمــوم الدعــاوي واملطالبــات واملدافعــة واملرافعــة‬\n‫واإلقــرار واإلنــكار والصلــح والتنــازل واالســتالم والتســليم قائــا يف‬\n‫دعــواه إن املدعــى عليــه أصالــة ‪...‬كان زوج ـ ًا ملوكلتــي مبوجــب عقــد‬\n‫نــكاح صحيــح حســب وثيقــة عقــد النــكاح رقــم‪ ...‬يف ‪1427/6/8‬ه ـ‬\n‫الصــادر مــن هــذه احملكمــة وذلــك علــى مهــر قــدره أربعــة عشــر ألــف‬\n\n                                                                                     ‫‪274‬‬\n\f      ‫ريــال أربعــة آالف منهــا مســلمة مقدم ـ ًا والباقــي مؤخــر وقــد دخــل بهــا‬\n      ‫ومت فســخ نكاحهــا منــه اليــوم بعــد أن أجنبــت منــه علــى فــراش الزوجيــة‬\n      ‫ثالثــة أوالد ‪...‬وعمــره خمســة أعــوام و‪...‬وعمــره ثالثــة أعــوام ونصــف‬\n      ‫و‪...‬وعمــره ثالثــة أشــهر ومنــذ ‪1432/5/1‬ه ـ لــم ينفــق علــى موكلتــي‬\n      ‫ا ب‪...‬ووضعتــه يف‬     ‫وال علــى ولديهــا ‪...‬و‪...‬وكانــت يف هــذا التاريــخ حام ـ ً‬\n      ‫‪1433/1/30‬ه ـ لــذا أطلــب ســؤال املدعــى عليــه وكالــة وإلزامــه بدفــع‬\n      ‫نفقــة موكلتــي مــن تاريــخ ‪1432/5/1‬ه ـ وحتــى تاريــخ اليــوم وكذلــك‬\n      ‫نفقــة ولديهــا ‪...‬و‪ ...‬هــذه املــدة وأجــرة حملهــا ب‪...‬مــن ‪1432/5/1‬ه ـ‬\n      ‫وحتــى وضعــه يف ‪1433/1/30‬ه ـ ونفقتــه مــن ‪1433/2/1‬ه ـ وحتــى‬\n      ‫اآلن ونفقــة أوالدهــا الثالثــة املســتقبلية هــذه دعــواي وبعرضهــا علــى‬\n      ‫املدعــى عليــه وكالــة قــال بأننــي فســخت وكالتــي عــن موكلــي ‪...‬‬\n      ‫فلســت وكيــا عنــه هكــذا قــرر وبنــاء علــى املــادة (‪ )50‬مــن نظــام‬\n      ‫املرافعــات ســألت املدعــي وكالــة هــل املدعــى عليــه أصالــة أبلغــك أو‬\n      ‫أبلــغ موكلتــك بعــزل الوكيــل أو قبــول انعزالــه وتعيــن أحــد بــد ًال عنــه‬\n      ‫أو أنــه سيباشــر الدعــوى بنفســه فقــال لــم يحصــل شــيء مــن ذلــك وألن‬\n      ‫هــذا األعتــزال مــن الوكيــل مت بــدون موافقــة احملكمــة وقبــل إبــاغ‬\n      ‫املدعــي فقــد قــررت الســير يف إجــراءات الدعــوى وفقـ ًا للمــادة املذكورة‬\n      ‫والئحتهــا األولــى والنتهــاء وقــت اجللســة رفعــت ثــم عقــدت اجللســة وفيهــا‬\n      ‫حضــر املدعــي وكالــة ‪...‬ولــم يحضــر املدعــى عليــه وال مــن ينــوب عنــه‬\n      ‫ولــم يــرد إلينــا مايفيــد إعتــذاره عــن حضــور هــذه اجللســة وقــد ســبقت‬\n      ‫الكتابــة ملكتــب الصلــح حملاولــة الصلــح أو تقديــر النفقــة فعــادت‬\n      ‫ومعهــا قــرار املكتــب رقــم ‪/260‬ص يف ‪1433/6/18‬ه ـ واملتضمــن‬\n      ‫( ففــي هــذا اليــوم الســبت ‪1433/5/29‬ه ـ حضــرت املدعيــة ‪...‬حتمــل‬\n\n\n‫‪275‬‬\n\f‫رخصــة إقامــة رقــم ‪...‬وحضــر حلضورهــا املدعــى عليــه ‪...‬يحمــل رخصــة‬\n‫إقامــة رقــم ‪...‬ومبحاولــة الصلــح بــن الطرفــن وتقريــب وجهــات النظــر‬\n‫بــن الطرفــن تعــذر الصلــح حيــث اســتعد الــزوج بدفــع نفقــة وقدرهــا‬\n‫ســتمائة ريــال وقــد أفــاد أمــام اللجنــة أنــه يعمــل يف شــركة ‪...‬مشــرف‬\n‫علــى املقاصــف باملــدارس براتــب ثمامنائــة ريــال وادعــت املدعيــة أنــه يعمل‬\n‫يف محــل ‪ ...‬بأســواق ‪...‬حيــث مكثــت املعاملــة لدينــا إلــى هــذا اليــوم‬\n‫األربعــاء ‪1433/6/18‬ه ـ لالستفســار عــن عمــل املدعــى عليــه ولكــن‬\n‫دون جــدوى ‪ .‬عليــه تــرى اللجنــة أن تكــون النفقــة املاضيــة للمدعيــة‬\n‫أربعمائــة ريــال وأمــا النفقــة املاضيــة واملســتقبليه لألبنــاء مائتــن ريــال‬\n‫لــكل ابــن عــن كل شــهر أمــا أجــرة احلمــل ســتمائة ريــال وإذا ثبــت انــه‬\n‫يتقاضــى راتــب ينظــر يف النفقــة مــرة أخــرى) أ‪.‬ه ـ وبعرضــه علــى املدعــي‬\n‫وكالــة قــرر موافقتــه عليــه ثــم عقــدت اجللســة وفيهــا حضــرت املدعيــة‬\n‫أصالــة ‪...‬مصريــة اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪...‬املعــرف بهــا‬\n‫مــن قبــل والدهــا ووكيلهــا احلاضــر ‪...‬ولــم يحضــر املدعــى عليــه وال مــن‬\n‫ينــوب عنــه وقالــت املدعيــة بــأن املدعــى عليــه لــم ينفــق علــي مــن شــهر‬\n‫جمــادى الثانيــة عــام ‪1432‬ه ـ حتــى مت فســخ نكاحــي يف شــهر شــعبان‬\n‫عــام ‪1433‬ه ـ مــدة أربعــة عشــر شــهرا وإجمالــي نفقتــي لهــذه املدة حســب‬\n‫تقديــر مكتــب الصلــح خمســة آالف وســتمائة ريــال كمــا أنــه لــم ينفــق‬\n‫علــى ولــدي منــه ‪...‬و‪...‬مــدة خمســة عشــر شــهرا مــن شــهر جمــادى الثانيــة‬\n‫عــام ‪1432‬ه ـ حتــى اآلن وقــد قــدرت نفقة كل واحــد منهما مبائتي ريال‬\n‫وإجمالــي نفقتهمــا لهــذه املــدة ســتة آالف كمــا أنــه لــم يدفــع لــي أجــرة‬\n‫حملــي بــ‪...‬مــدة ثمانيــة أشــهر مــن شــهر جمــادى الثانيــة عــام ‪1432‬هـ وقد‬\n‫قــدرت بســتمائة ريــال شــهريا وإجمالــي ذلــك أربعــة آالف وثمامنائــة ريــال‬\n\n\n                                                                                     ‫‪276‬‬\n\f      ‫وال نفقتــه بعــد وضعــه مــدة ســبعة أشــهر مــن تاريــخ وضعــه حتــى اآلن وقــد‬\n      ‫قــدرت مبائتــي ريــال وإجمالــي نفقتــه لهــذه املــدة ألــف وأربعمائــة ريــال‬\n      ‫كمــا أطالــب بإلزامــه بدفــع نفقــة أوالده الثالثــة املســتقبله وإجمالــي‬\n      ‫نفقتهــم الشــهرية حســب التقديــر ســتمائة ريــال فســألتها هــل كانــت يف‬\n      ‫فتــرة حملهــا التــي تطالــب بأجرتهــا يف ذمــة املدعــى عليــه وهــل طالبــت‬\n      ‫بنفقتهــا خــال هــذه الفتــرة فقالــت نعــم كنــت يف ذمتــه وطالبــت بنفقتــي‬\n      ‫لهــذه املــدة فأفهمتهــا بــأن عليهــا اليمــن علــى أن املدعــى عليــه لــم ينفــق‬\n      ‫عليهــا وال علــى أبنائهــا منــه مــن شــهر جمــادى الثانيــة عــام ‪1432‬ه ـ‬\n      ‫وحتــى اآلن فاســتعدت بذلــك فأذنــت لهــا بعــد وعضهــا فحلفــت قائلــة‬\n      ‫واهلل العظيــم أن املدعــى عليــه ‪...‬لــم ينفــق علــي وال علــى أبنائــي منــه ‪...‬و‪...‬‬\n      ‫و‪...‬مــن شــهر جمــادى الثانيــة عــام ‪1432‬ه ـ وحتــى اآلن ســوى أربعمائــة‬\n      ‫ريــال هكــذا حلفــت ونظــرا ألن قــرار مكتــب الصلــح املــدون ســابقا لــم‬\n      ‫يوضــح فيــه هــل أجــرة احلمــل احملــددة شــهرية أم أنهــا لكامــل املــدة وهــل‬\n      ‫تدخــل فيهــا نفقــة الزوجــة أم هــي مســتقلة عــن ذلــك وللتحقــق مــن ذلــك‬\n      ‫رفعــت اجللســة ثــم عقــدت اجللســة وفيهــا حضــر املدعــي وكالــة ‪...‬ولــم‬\n      ‫يحضــر املدعــى عليــه ‪...‬ولــم يــرد مــا يفيــد تبلغــه مبوعــد هــذه اجللســة وقــد‬\n      ‫ورد إلينــا خطــاب رئيــس قســم اإلصــاح والتحكيــم رقــم ‪33226351‬‬\n      ‫يف ‪1433/9/23‬ه ـ ويتضمــن ‪( :‬أجــرة احلمــل احملــددة كل شــهر وليســت‬\n      ‫كامــل املــدة وأنهــا داخلــة يف نفقــة الزوجــة وليســت مســتقلة)أهـ وبســؤال‬\n      ‫املدعــي وكالــة هــل لديــه إضافــة قــال ليــس لــدي إضافــة فبنــاء علــى‬\n      ‫ماتقــدم مــن الدعــوى ونظــر ًا إلــى أن مــا قــرره املدعــى عليــه وكالــة غيــر‬\n      ‫مقبــول ملــا ورد يف املــادة (‪ )50‬والئحتهــا األولــى مــن نظــام املرافعــات وملــا‬\n      ‫ورد يف قــرار مكتــب الصلــح املتضمــن تقديــر النفقــة وملوافقــة املدعــي‬\n\n\n‫‪277‬‬\n\f‫وكالــة عليــه وحللــف املدعيــة أصالــة علــى أن املدعــى عليــه لــم ينفــق‬\n‫عليهــا وال علــى أوالدهــا وألن نفقــة احلامــل جتــب للمطلقــة البائــن ملفهــوم‬\n‫ول ِت َح ْمـ ٍـل َف َأ ْنفِ ُقــوا َع َل ْي ِهـ َّـن َح َّتــى َي َض ْعـ َـن‬      ‫كـ َّـن ُأ َ‬‫قولــه ســبحانه { َو ِإنْ ُ‬\n‫َح ْم َل ُهـ َّـن } واملدعيــة أقــرت بــأن فتــرة حملهــا التــي تطلــب بنفقتهــا كانــت‬\n‫يف ذمــة املدعــى عليــه لهــذا ولقولــه ســبحانه { ل ُِي ْنفِ ـ ْـق ُذو َسـ َـع ٍة مِ ــنْ َسـ َـع ِتهِ}‬\n‫ـروف ِ} فقــد‬ ‫هن ِبامل َْعـ ِ‬     ‫ك ْسـ َـو ُت َّ‬    ‫املولــو ِد َل ـ ُه ِر ْزقُ هـ َّـن َو ِ‬\n                                                                                         ‫{وع َلــى ْ‬   ‫وقولــه عزوجــل َ‬\n‫قــررت مايلــي ‪ :‬أوالً‪ :‬إلــزام املدعــى عليــه ‪...‬بدفــع خمســة آالف وســتمائة‬\n‫ريــال نفقــة املدعيــة مــدة أربعــة عشــر شــهر ًا مــن شــهر جمــادى الثانيــة‬\n‫عــام ‪1432‬هــ‪ .‬ثاني ـ ًا ‪ :‬إلــزام املدعــى عليــه ‪...‬بدفــع ثالثــة آالف وســتمائة‬\n‫ريــال نفقــة ولديــه مــن املدعيــة ‪...‬و‪ ...‬مــن تاريــخ ‪1432/5/1‬ه ـ حتــى‬\n‫‪1433/1/30‬ه ـ ‪ .‬ثالث ـ ًا ‪ :‬إلــزام املدعــى عليــه ‪...‬بدفــع تســعة آالف ريــال‬\n‫نفقــة أوالده مــن املدعيــة ‪...‬و‪ ...‬و‪ ...‬مــن تاريــخ ‪1433/2/1‬ه ـ وحتــى‬\n‫‪1434/4/30‬ه ـ رابعـاً‪ :‬إلــزام املدعــى عليــه ‪...‬بدفــع ســتمائة ريــال شــهري ًا‬\n‫ابتــداء مــن تاريــخ ‪1434/5/25‬ه ـ نفقــة أوالده مــن املدعيــة‪ .‬خامس ـ ًا‬\n‫‪ :‬صــرف النظــر عــن طلــب املدعيــة أصالــة نفقــة حملهــا ملــا ذكــر يف‬\n‫أســباب احلكــم وبذلــك كلــه حكمــت وبعرضــه علــى املدعــي وكالــة‬\n‫قنــع بــه وســيتم إبــاغ املدعــى عليــه بنســخة منــه لتقــدمي مــا لديــه خــال‬\n‫ثالثــن يوم ـ ًا مــن تاريــخ اســتالمه لهــا وإذا مضــت املــدة بعــد االســتالم‬\n‫ولــم يتقــدم مبــا لديــه فيســقط حقــه يف االعتــراض ويكتســب احلكــم‬\n‫الصفــة القطعيــة وبــاهلل التوفيــق حــرر يف ‪1434/4/24‬ه ـ وصلــى اهلل‬\n                                ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مبكــة املكرمــة بخطــاب فضيلــة رئيســها رقــم ‪ 33226351‬يف‬\n\n\n                                                                                                                            ‫‪278‬‬\n\f      ‫‪1434/6/28‬ه ـ احملــال لنــا بشــرح فضيلــة الرئيــس رقــم ‪33226351‬‬\n      ‫يف ‪1434/7/4‬ه ـ ومعهــا قــرار الدائــرة الثانيــة لألحــوال الشــخصية رقــم‬\n      ‫‪ 34248489‬يف ‪1434/6/21‬ه ـ وقــد ظهــر القــرار مبــا نصــه (تظهيــرات‬\n      ‫الدائــرة الثانيــة لألحــوال واألوقــاف والوصايــا والقصــار وبيــوت املــال‬\n      ‫مبحكمــة االســتئناف مبكــة املكرمــة احلمــدهلل وحــده وبعــد فقــد‬\n      ‫اطلعنــا علــى هــذا الصــك رقــم ‪ 34199029‬وتاريــخ ‪1434/4/28‬ه ـ‬\n      ‫الصــادر مــن فضيلــة الشــيخ ‪...‬وأصدرنــا القــرار رقــم ‪ 34248489‬وتاريــخ‬\n      ‫‪1434/6/21‬ه ـ املتضمــن املوافقــة علــى احلكــم عضــو ‪...‬توقيعــه وختمــه‬\n      ‫عضــو د‪... .‬توقيعــه وختمــه رئيــس الدائــرة ‪...‬توقيعــه وختمــه) أ‪.‬ه ـ لــذا‬\n      ‫جــرى إحلاقــه وبــاهلل التوفيــق حــرر يف ‪1434/7/8‬ه ـ وصلــى اهلل وســلم‬\n                                ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n      ‫احلمــد هلل والصــاة والســام علــى مــن ال نبي بعــده ‪ ،‬وبعد فقد جرى منا‬\n      ‫نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا‬\n      ‫والقصــار وبيــوت املــال مبحكمــة االســتئناف يف منطقــة مكــة‬\n      ‫املكرمــة االطــاع علــى الصــك الصــادر مــن فضيلــة الشــيخ‪... /‬القاضــي‬\n      ‫باحملكمــة العامــة بالطائــف برقــم ‪ 34199029‬وتاريــخ‪ 1434/4/28‬ه ـ‬\n      ‫املتضمــن دعــوى‪ ... /‬ضــد‪... /‬يف نفقــة وبدراســة الصــك وصــورة ضبطــه‬\n      ‫تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                         ‫وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪279‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":272,"source_page_end":279,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"72000e4ad83e40870693fc9272cee22c6d9a6faef412c6a71b28bfd35c0dc4f7","normalized_text_hash":"2963d5bb2e8968130130d55e92355fc61cd0fba82ec30684c6fe7106ff319770","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p272-34199029"},{"id":"52f116b8-d3e6-5f5c-a692-1427f38af51b","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقه -نفقة األم املاضية و املستقبلية -تقدير النفقة عن طريق قسم اخلبراء -إلزام األوالد بالنفقة -إلزامهم بإحضار خادمة وسائق لوالدتهم.","document_number":"34209196","case_number":"3313659","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/7","year":"1434","subject":"نفقه -نفقة األم املاضية و املستقبلية -تقدير النفقة عن طريق قسم اخلبراء -إلزام األوالد بالنفقة -إلزامهم بإحضار خادمة وسائق لوالدتهم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/5/7 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34209196 :‬‬\n                    ‫َر ْق ُم الدعوى‪3313659 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 34362541‬تاريخه‪1434/11/19 :‬هـ‬\n\n\n\n‫نفقــه ‪ -‬نفقــة األم املاضيــة و املســتقبلية ‪ -‬تقديــر النفقــة عــن طريــق‬\n‫قســم اخلبــراء ‪ -‬إلــزام األوالد بالنفقــة ‪ -‬إلزامهــم بإحضــار خادمــة‬\n                                                     ‫وســائق لوالدتهــم‪.‬‬\n\n\n\n\n                                        ‫‪ -1‬قوله تعالى « وبالوالدين إحساناً»‬\n                              ‫‪ -2‬قوله صلى اهلل عليه وسلم « أمك وأباك»‬\n‫‪ -3‬قــال بــن املنــذر (اجمــع أهــل العلــم إن نفقــة الوالديــن الفقيريــن الذيــن‬\n                             ‫ال كســب لهمــا وال مــال واجبــة يف مــال الولــد)‬\n‫‪ -4‬قــال صاحــب الــروض املربــع ( جتــب النفقــة كاملــة إذا كان املنفــق‬\n‫عليــه ال ميلــك شــيئا أو تتمتهــا إذا كان ال ميلــك البعــض ألبويــه وإن علــوا)‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة (األم) ضــد ابنيهــا موظفــن بطلــب إلزامهمــا بنفقتهــا‬\n‫حيــث أنهــا غيــر متزوجــة ومحتاجــة وقــررت انهمــا ال ينفقــان عليهــا منــذ‬\n‫خمــس ســنوات وطالبــت بالنفقــة املاضيــة وتقديــر نفقــه مســتقبلية ‪ -‬لــم‬\n‫يحضــر املدعــى عليهمــا وتبلــغ احدهمــا ولــم يتبلــغ اآلخــر وقــرر ناظــر‬\n‫القضيــة الســير يف القضيــة ومت إحالــة األوراق ملكتــب الصلــح‪ ،‬مت‬\n\n                                                                                       ‫‪280‬‬\n\f      ‫تقديــر نفقــه لــأم بثالثــة آالف ريــال علــى كل ولــد مــن أوالدهــا الثالثــة‬\n      ‫وتأمــن خادمــة‪ ،‬قــررت األم أن احــد أبنائهــا غيــر موظــف وطالبــت‬\n      ‫إلــزام املدعــى عليهمــا فقــط وإلزامهمــا أيضـ ًا بتأمــن ســائق‪ ،‬قــرر ناظــر‬\n      ‫القضيــة لألســباب املرصــودة إلــزام املدعــى عليهمــا بدفــع نفقــة شــهرية‬\n      ‫لــأم قدرهــا ألف ـ ًا ريــال مناصفــة ال تشــمل إيجــار الســكن وإلزامهمــا‬\n      ‫بإحضــار ســائق وخادمــة لوالدتهمــا واحلكــم يف حــق املدعــى عليــه‬\n      ‫املتبلــغ حضوريـ ًا واألخــر غيابيـاً‪ ،‬مت بعــث نســخه مــن احلكــم للمدعــى‬\n      ‫عليهمــا حســب املتبــع‪ ،‬صــدر قــرار محكمــة االســتئناف مبنطقــة مكــة‬\n                                                ‫املكرمــة باملوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالطائــف برقــم ‪ 33131659‬وتاريــخ ‪ 1433/02/21‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 3333322‬وتاريــخ ‪ 1433/01/04‬ه ـ يف يــوم األحــد‬\n      ‫املوافــق‪ 1433/06/22‬ه ـ وفيهــا حضــرت ســعودية اجلنســية مبوجــب‬\n      ‫ســجلها املدنــي رقــم وأمــا املدعــى عليهــم فلــم يحضــروا ولــم يردنــا مــا‬\n      ‫يفيــد بتبليغهــم باحلضــور مــن عدمــه لــذا قــررت رفــع اجللســة وتأجيلهــا‬\n      ‫ويف جلســة أخــرى يف يــوم األحــد املوافــق‪ 1433/08/11‬ه ـ حضــرت‬\n      ‫املدعيــة واملعــرف بهــا مــن قبــل مشــرفة التفتيــش باحملكمة وأمــا املدعى‬\n      ‫عليــه فلــم يحضــر وقــد وردتنــا إفــادة قســم احملضريــن باحملكمــة برقــم‬\n      ‫‪ 33934070‬يف ‪1433/05/17‬ه ـ واملتضمــن أن املدعــى عليــه قــد تبلــغ‬\n      ‫لشــخصه لــذا قــررت ســماع دعــوى املدعيــة فادعــت قائلــة يف دعواهــا‬\n‫‪281‬‬\n\f‫إن املدعــى عليهــم أبنائــي وهــم موظفــون وال ينفقــون علــي منــذ مــا‬\n‫يقــارب خمــس ســنوات وأنــا غيــر متزوجــة وال أملــك مــن حطــام الدنيــا‬\n‫إال اليســير أطلــب احلكــم علــى املدعــى عليــه وكذلــك إبنــي ‪ ...‬بدفــع‬\n‫نفقتــي املاضيــة والتعهــد بدفــع نفقتــي املســتقبلية هــذه دعــواي عليــه‬\n‫قــررت إدخــال ‪...‬و‪...‬و‪ ...‬أبنــاء يف الدعــوى وتبليغهــم باحلضــور كاملتبــع‬\n                        ‫وحتــى يحصــل ذلــك جــرى رفــع اجللســة وتأجيلهــا‪.‬‬\n‫احلمــد هلل وحــده وبعــد لــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف ففــي يــوم األربعــاء املوافــق‪ 1433/10/11‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 09 : 00‬ثــم مضــى الوقــت احملــدد لهــا ولــم حتضــر املدعيــة‬\n‫وال مــن ينــوب عنهــا ولــم تقــدم عــذرا يفيــد عــن ســبب تخلفهــا عــن‬\n‫احلضــور لذلــك كلــه واســتنادا علــى تعليمــات نظــام املرافعــات وألن‬\n‫مــن تــرك دعــواه تــرك لــذا فقــد قــررت شــطب القضيــة للمــرة األولــى‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n‫وســلم ‪ .‬حــرر يف ‪ 1433/10/11‬ه ـ ‪ .‬ويف جلســة أخــرى يف يــوم الثالثــاء‬\n‫املوافــق‪ 1433/11/30‬ه ـ وبنــاء علــى االســتدعاء احملــال إلينــا بشــرح‬\n‫فضيلــة رئيــس احملكمة برقــم ‪ 331812964‬يف تاريخ ‪1433/10/15‬هـ‬\n‫واملتضمــن طلــب املدعيــة إعــادة املعاملــة مــن األرشــيف ومواصلــة نظــر‬\n‫القضيــة وأمــا املدعــى عليهــم فلــم يحضــروا وقــد ســبق أن وردتنــا‬\n‫إفــادة قســم احملضريــن برقــم ‪ 33934070‬يف تاريــخ ‪1433/05/22‬ه ـ‬\n‫واملتضمنــة أنــه تبلــغ لشــخصه وإفــادة أخــرى برقــم ‪ 331627704‬يف‬\n‫تاريــخ ‪1433/08/28‬ه ـ واملتضمنــة تعــذر تبليــغ املدعــى عليــه بســبب‬\n‫متتعــه باإلجــازة الصيفيــة ثــم جــرى ســؤال املدعيــة هــل لديــك بينــة علــى‬\n‫دعــواك فقالــت ليــس لــدي بينــة علــى دعــواي هكــذا قــررت عليــه قــررت‬\n\n\n                                                                                    ‫‪282‬‬\n\f      ‫إحالــة املدعيــة إلــى قســم الصلــح إلكمــال الــازم حيــال هــذه الدعــوى‬\n      ‫ويف جلســة أخــرى يف يــوم األربعــاء املوافــق‪ 1434/01/21‬ه ـ وقــد ســبق‬\n      ‫وأن أحيلــت كامــل أوراق املعاملــة إلــى مكتــب الصلــح ولــم تردنــا حتــى‬\n      ‫تاريخــه لــذا فقــد قــررت رفــع اجللســة حتــى ورود اجلــواب مــن القســم‬\n      ‫املذكــور‪ .‬ويف جلســة أخــرى يف يــوم األحــد املوافق‪1434/05/05‬ه ـ‬\n      ‫حضر ت املدعية وأما املدعى عليهم فلم يحضروا وقد سبقت الكتابة‬\n      ‫لقســم اإلصــاح والتحكيــم باحملكمــة بخطابنــا رقــم ‪ 331811956‬يف‬\n      ‫‪1434/1/19‬ه ـ فوردنــا خطابهــم رقم ‪ 331811956‬يف ‪1434/1/26‬هـ‬\n      ‫املتضمــن أنــه جــرى إكمــال الــازم علــى ضــوء قــرار أعضــاء جلنــة الصلح‬\n      ‫املرفــق وباالطــاع عليــه وجــد يتضمــن مــا نصــه بعــد املقدمــة (حضــرت‬\n      ‫املدعيــة أصالــة حتمــل الهويــة الوطنيــة رقــم ولــم يحضــر أبناؤهــا ‪...‬و‪...‬‬\n      ‫أبنــاء‪ ...‬وبنــاء علــى توجيــه فضيلــة القاضــي بالنظــر يف الدعــوى دون‬\n      ‫حضــور املدعــى عليهــم وحيــث أفــادت املدعيــة بأنهــا تســكن يف ســكن‬\n      ‫وأبناؤهــا يســددون إيجــار الســكن مبقــدار اثنــن وعشــرين ألــف ريــال‬\n      ‫وأن ابنهــا يعمــل معلــم والثانــي ضابــط يف اجليــش والثالــث ممــرض عليــه‬\n      ‫تــرى اللجنــة والــرأي لفضيلتكــم أن تكــون النفقــة ثالثــة آالف ريــال‬\n      ‫تــوزع علــى كل ابــن مــن أبنائهــا ويكــون مجمــوع النفقــة ثالثــة آالف‬\n      ‫ريــال ال يشــمل إيجــار الســكن وأن يحضــروا لهــا خادمــة ويــوزع دفــع‬\n      ‫راتــب اخلادمــة علــى األبنــاء جميعــا أ ‪ .‬هــ) ثــم جــرى عــرض ذلــك علــى‬\n      ‫املدعيــة فقالــت إن ابنــي غيــر موظــف وليــس لــه مصــدر دخــل وأطلــب أن‬\n      ‫يؤمنــوا لــي ســائق والبنــت تســلمني ألــف ريــال شــهريا وبقيــة مــا ذكــر‬\n      ‫موافقــة عليــه هكــذا قــررت ثــم جــرى ســؤالها هــل لديــك إضافــة علــى‬\n      ‫مــا ســبق فقالــت ليــس لــي إضافــة علــى مــا ســبق هكــذا قــررت فبنــاء‬\n\n\n‫‪283‬‬\n\f‫علــى مــا تقــدم مــن الدعــوى ولقولــه تعالــى ( وبالوالديــن إحســانا ) قــال‬\n‫ابــن املنــذر‪ ( :‬أجمــع أهــل العلــم أن نفقــة الوالديــن الفقيريــن الذيــن ال‬\n‫كســب لهمــا وال مــال واجبــة يف مــال الولــد) ويقــول صاحــب الــروض‬\n‫املربــع ( جتــب النفقــة كاملــة إذا كان املنفــق عليــه ال ميلــك شــيئا أو‬\n‫تتمتهــا إذا كان ال ميلــك البعــض ألبويــه وإن علــوا ) ويف احلديــث ( أمــك‬\n‫وأبــاك) ويف احلديــث الصحيــح ذكــرت األم ثالثــا وينظــر حاشــية ابــن‬\n‫قاســم علــى الــروض ‪ 127/7‬وألن املدعيــة قــررت بــأن ابنهــا ‪ ...‬غيــر‬\n‫موظــف وليــس لــه مصــدر دخــل وأن ابنتهــا تعطيهــا شــهريا ألــف ريــال‬\n‫وألنهــا قــررت قناعتهــا مبــا جــاء يف قــرار قســم اإلصــاح والتحكيــم‬\n‫باحملكمــة برقــم ‪/23‬ص وتاريــخ ‪1434/1/17‬ه ـ فقــد حكمــت علــى‬\n‫املدعــى عليهمــا حكمــا حضوريــا يف حــق األول وغيابيــا يف حــق الثانــي‬\n‫بــأن يدفعــا للمدعيــة شــهريا نفقــة وقدرهــا ألفــي ريــال مناصفــة بينهمــا‬\n‫ال تشــمل إيجــار الســكن الــذي تســكنه كمــا ألزمتهمــا بــأن يحضــرا‬\n‫لوالدتهمــا املدعيــة خادمــة وســائق ويقومــا بدفــع راتبهمــا مناصفــة‬\n‫بينهمــا واملدعــى عليــه الثانــي الغائــب علــى حجتــه متــى حضــر وبإعــان‬\n‫احلكــم علــى املدعيــة قــررت قناعتهــا باحلكــم وســوف يجــري بعــث‬\n‫نســخة مــن الصــك للمدعــى عليهمــا لتقــدمي مــا لديهمــا مــن اعتــراض وأن‬\n‫لهمــا ثالثــن يومــا مــن تاريــخ تبلغهمــا باحلكــم لتقــدمي اعتراضهمــا فــإن‬\n‫لــم يقدمــا اعتراضهمــا خاللهــا ســقط حقهمــا يف االعتــراض واكتســب‬\n‫احلكــم القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                          ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/05‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n\n\n                                                                                    ‫‪284‬‬\n\f      ‫العامــة بالطائــف برقــم ‪ 33131659‬وتاريــخ ‪1433/02/21‬ه ـ املقيــدة‬\n      ‫باحملكمة برقم ‪ 3333322‬وتاريخ ‪ 1433/01/04‬هـ ففي يوم الثالثاء‬\n      ‫املوافق‪1434/09/01‬هـ افتتحت اجللســة الســاعة التاســعة وقد وردتنا‬\n      ‫الالئحــة االعتراضيــة املقدمــة مــن احملالــة لنــا برقــم ‪ 341708401‬يف‬\n      ‫تاريــخ ‪1434/7/16‬ه ـ وباإلطــاع عليهــا لــم أجــد فيهــا مــا يؤثــر علــى‬\n      ‫احلكــم أو يدعــو للعــدول عنــه وقــررت رفع القضية حملكمة االســتئناف‬\n      ‫لتدقيقهــا كاملتبــع كمــا وردنــا خطــاب رئيــس احملكمــة العامــة‬\n      ‫مبنطقــة تبــوك رقــم ‪ 341216753‬يف تاريــخ ‪ 1434/8/7‬ه ـ املتضمــن‬\n      ‫تســلم املدعــى عليــه صــورة احلكــم بتاريــخ ‪ 1434/7/1‬ه ـ وحيــث لــم‬\n      ‫يقــدم الئحــة اعتراضيــة حتــى تاريخــه فقــد ســقط حقــه يف االعتــراض‬\n      ‫واكتســب احلكــم القطعيــة يف حقــه وللبيــان حــرر واختتمــت اجللســة‬\n      ‫الســاعة التاســعة والربــع و بــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/09/01‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف ففــي يــوم اخلميــس املوافــق ‪1434/12/26‬ه ـ افتتحــت اجللســة‬\n      ‫وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف وعليهــا خطــاب رئيســها‬\n      ‫برقــم ‪ 331811956‬يف تاريخ‪1434/12/1‬ه ـ وبداخــل املعاملــة وجــد‬\n      ‫القرار الصادر من دائرة األحوال الشخصية الثانية برقم‪34362541‬يف‬\n      ‫تاريــخ ‪1434/11/19‬ه ـ واملتضمــن املوافقــة علــى احلكــم بعــد اإلجــراء‬\n      ‫األخيــر وعليــه فقــد أكتســب احلكــم الصفــة القطعيــة وبــاهلل التوفيــق‪،‬‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                   ‫‪1434/12/26‬ه ـ ‪.‬‬\n      ‫احلمــد هلل والصــاة والســام علــى مــن ال نبي بعــده ‪ ،‬وبعد فقد جرى منا‬\n\n\n‫‪285‬‬\n\f‫نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصار وبيوت املال مبحكمة االســتئناف يف منطقة مكة املكرمة‬\n‫االطــاع علــى الصــك الصــادر مــن فضيلــة الشــيخ(‪ ).....‬القاضــي‬\n‫باحملكمــة العامــة بالطائــف برقــم ‪ 34209196‬وتاريخ‪1434/5/7‬ه ـ‬\n‫املتضمــن دعــوى ضــد وإخوانــه يف نفقــة وبدراســة الصــك وصــورة ضبطــه‬\n‫تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                   ‫وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪286‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":280,"source_page_end":286,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"13272991d238ae90fa039db6842c698a2e275e3cd79a29da27c135c1122952bb","normalized_text_hash":"38c4f18ab3b03794be7103f862ea00e50d6fd4549062cce8d4eb6c1a1fc33142","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p280-34209196"},{"id":"4de862a4-7edd-585a-a1f3-b9ced6ec43c9","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة زوجة عن املدة املاضية -تقدير النفقة عن طريق قسم اخلبراء -اعتراض الزوج على مقدار النفقة -دفع الزوج بعدم استحقاق الزوجة للنفقة بسبب مرضها بالسحر -احلكم على الزوج بدفع نفقة الزوجة املاضية.","document_number":"34243280","case_number":"3415320","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/17","year":"1434","subject":"نفقة -نفقة زوجة عن املدة املاضية -تقدير النفقة عن طريق قسم اخلبراء -اعتراض الزوج على مقدار النفقة -دفع الزوج بعدم استحقاق الزوجة للنفقة بسبب مرضها بالسحر -احلكم على الزوج بدفع نفقة الزوجة املاضية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/6/17 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34243280 :‬‬\n                          ‫َر ْق ُم الدعوى‪3415320 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34312771‬تاريخه‪1434/9/6 :‬هـ‬\n\n\n\n       ‫نفقــة‪ -‬نفقــة زوجــة عــن املــدة املاضيــة‪ -‬تقديــر النفقــة عــن طريــق‬\n       ‫قســم اخلبــراء‪ -‬اعتــراض الــزوج علــى مقــدار النفقــة‪ -‬دفــع الــزوج بعــدم‬\n       ‫اســتحقاق الزوجــة للنفقــة بســبب مرضهــا بالســحر‪ -‬احلكــم علــى‬\n                                             ‫الــزوج بدفــع نفقــة الزوجــة املاضيــة‪.‬‬\n\n\n\n\n                                       ‫‪ -1‬قوله تعالى ( لينفق ذو سعه من سعته )‬\n                               ‫‪ -2‬قولة تعالى( ولهن مثل الذي عليهن باملعروف )‬\n       ‫‪ -3‬قول النبي صلى اهلل عليه وســلم ( ولهن عليكم رزقهن وكســوتهن‬\n                                                       ‫باملعروف ) رواه مسلم وغيره‬\n       ‫‪ -4‬حديــث عائشــة رضــي اهلل عنهــا أن هنــد بنــت عتبــه قالــت لرســول‬\n       ‫اهلل صلــى اهلل عليــه وســلم إن أبــا ســفيان رجــل شــحيح وليــس يعطينــي‬\n       ‫مــا يكفينــي وولــدي إال مــا أخــذت منــه وهــو ال يعلــم فقــال صلــى اهلل‬\n       ‫عليــه وســلم خــذي مــا يكفيــك وولــدك باملعروف ) رواه البخاري ومســلم‬\n                                                                             ‫وغيرهمــا‬\n       ‫‪ -5‬مــا رواه البخــاري أن النبــي صلــى اهلل عليــه وســلم قضــى أن اليمــن‬\n                                                                  ‫علــى املدعــى عليــه‬\n       ‫‪ -6‬قــول النبــي صلــى اهلل عليــه وســلم‪ ( :‬البينــة علــى املدعــى واليمــن‬\n       ‫علــى املدعــى عليــه ) رواه الترمــذي وقــال العمــل عنــد أهــل العلــم مــن‬\n\n‫‪287‬‬\n\f‫أصحــاب النبــي صلــى اهلل عليــه وســلم وغيرهــم أن البينــة علــى املدعــى‬\n                                               ‫واليمــن علــى املدعــى عليــه ‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة بــأن املدعــى عليــه عقــد عليهــا ودخــل بهــا الدخــول‬\n‫الشــرعي ومكثــت عنــده خمســة عشــر يومـ ًا ولــم تنجــب منــه ثــم أعادهــا‬\n‫لبيــت أهلهــا‪ -‬بعــد ســنه تقريب ـ ًا مــن الدخــول قــام بتطليقهــا‪ -‬طلبــت‬\n‫املدعيــة إلــزام املدعــى عليــه بدفــع نفقتهــا املاضيــة‪ -‬أقــر املدعــى عليــه‬\n‫بالدعــوى ودفــع بــأن ســبب إعادتــه للمدعيــه ألهلهــا وعــدم اإلنفــاق عليهــا‬\n‫وذلــك ألن املدعيــة تعانــي مــن الســحر وعــن حتولــت إلــى مــس وأنهــا‬\n‫ال تســتحق النفقــة كــون املدعيــة وأهلهــا لــم يعلمــوه بذلــك‪ -‬أنكــرت‬\n‫املدعيــة ذلــك‪ -‬قــرر املدعــى عليــه بــأن ال بينــة لديــة وطلــب ميــن املدعيــة‪-‬‬\n‫حلفــت املدعيــة علــى نفــي مــا ذكــره املدعــى عليــه‪ -‬مت تقديــر النفقــة‬\n‫مــن قبــل قســم اخلبــراء‪ -‬ذكــر املدعــى عليــه بــأن النفقــة املقــدرة كثيــرة‬\n‫كونــه غيــر موظــف‪ -‬ذكــرت املدعيــة أن املدعــى عليــه يعمــل أعمــا ًال‬\n‫حــرة وأنــه مت أخــذ ذلــك يف االعتبــار عنــد تقديــر النفقــة‪ -‬صــدر احلكــم‬\n‫بإلــزام املدعــى عليــه بدفــع نفقــة املدعيــة عــن املــدة املذكــورة حســب‬\n‫قــرار هيئــة النظــر‪ -‬اعتــرض املدعــي عليــه علــى احلكــم‪ -‬صــدق احلكــم‬\n                                                      ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                        ‫‪288‬‬\n\f      ‫احلمد هلل وحده وبعد فلدي أنا ‪ ...‬القاضي يف احملكمة العامة مبحافظة‬\n      ‫جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫مبحافظــة جــدة املســاعد برقــم ‪ 3415320‬وتاريــخ ‪1434/01/10‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 3471454‬وتاريــخ ‪1434/01/10‬ه ـ فـفـ ــي‬\n      ‫يــوم السـبــت املـوافـق ‪1434/06/17‬هـ افـتـتـحـت اجلـلـســة الســاعــة ‪: 45‬‬\n      ‫‪ 03‬وفيهــا حضــرت املدعيــة ‪ ...‬ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ ...‬واملعــرف بهــا مــن قبــل أبيهــا ‪ ...‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ ...‬وادعــت علــى احلاضــر معهــا ‪ ...‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ ...‬قائلــة ‪ :‬إن املدعــى عليــه زوجــي ‪ ،‬عقــد بــي يف‬\n      ‫‪1433/4/22‬ه ـ علــى مهــر قــدره خمســة وثالثــون ألــف ريــال مســتلم‬\n      ‫بالكامــل ‪ ،‬مبوجــب عقــد النــكاح الصــادر مــن احملكمــة اجلزئيــة‬\n      ‫للضمــان واألنكحــة برقــم ‪ 3987‬وتاريــخ ‪1433/4/25‬هــ‪ ،‬ودخــل‬\n      ‫بــي يف ‪1433/6/24‬ه ـ ‪ ،‬ولــم أرزق منــه بــأوالد‪ ،‬ولــم ميكــث املدعــى‬\n      ‫عليــه معــي ســوى خمســة عشــر يوم ـاً‪ ،‬ثــم أعادنــي إلــى بيــت أهلــي دون‬\n      ‫ســبب‪ ،‬ومنــذ ذلــك التاريــخ وأنــا يف بيــت أهلــي ‪ ،‬ولــم ينفــق علــي طيلــة‬\n      ‫تلــك املــدة ‪ ،‬وقــد طلقنــي املدعــى عليــه طلقــة واحــدة هــذا اليــوم الســبت‬\n      ‫املوافــق ‪1434/6/17‬ه ـ مبوجــب الصــك الصــادر مــن هــذه احملكمــة‬\n      ‫برقــم ‪ 34243279‬وتاريــخ ‪1434/6/17‬ه ـ ‪ ،‬أطلــب إلــزام املدعــى عليــه‬\n      ‫بدفــع نفقتــي املاضيــة مــن تاريــخ ‪1433/7/10‬ه ـ وحتــى تاريــخ اليــوم ‪.‬‬\n      ‫هــذه دعــواي‪ ،‬وبعــرض ذلــك علــى املدعــى عليــه قــال ‪ :‬إن مــا ذكرتــه‬\n      ‫املدعيــة مــن العقــد والدخــول وعــدم اإلجنــاب وإعادتــي لهــا بعــد خمســة‬\n\n‫‪289‬‬\n\f‫عشــر يومــا وطالقــي لهــا وعــدم اإلنفــاق فصحيــح ‪ ،‬ولكــن املهــر هــو‬\n‫خمســة وثالثــون ألــف ريــال وطقــم ذهــب وزنــه اثنــن وثالثــن جرامــا‬\n‫وثمنــه ســتة آالف ومائــة ريــال ‪ ،‬وعربيــة ‪ ،‬وعــدم أحقيــة املدعيــة يف‬\n‫النفقــة راجــع إلــى أنهــا تعانــي مــن ســحر مشــروب ‪ ،‬وعــن حتولــت إلــى‬\n‫مــس ‪ ،‬وال تســتحق النفقــة كــون املدعيــة وأهلهــا لــم يعلمونــي بأنهــا‬\n‫تعانــي مــن ذلــك ‪ .‬وبعــرض ذلــك علــى املدعيــة قالــت ‪ :‬مــا ذكــره املدعــى‬\n‫عليــه مــن مــرض ومــس غيــر صحيــح ‪ ،‬وأنــا ال أعانــي مــن شــيء مــن ذلــك‬\n‫‪ .‬وبســؤال املدعــى عليــه البينــة علــى مــا دفــع بــه قــال ‪ :‬أطلــب ميــن املدعيــة‬\n‫علــى أنهــا لــم تخبرنــي بأنهــا مســحورة وأن جدهــا هــو مــن ســحرها وأن‬\n‫ســحرها تناولتــه عــن طريــق الفــم ‪ ،‬وأقبــل بــه ‪ .‬وبعــرض ذلــك علــى‬\n‫املدعيــة اســتعدت لذلــك ‪ ،‬ثــم حلفــت قائلــة ‪ :‬واهلل العظيــم الــذي ال إلــه‬\n‫إال هــو أننــي لــم أخبــر املدعــى عليــه ‪...‬بأننــي مســحورة وأن جــدي هــو‬\n‫مــن ســحرني ‪ ،‬وأن ســحري تناولتــه عــن طريــق الفــم ‪ .‬هكــذا حلفــت ‪.‬‬\n‫وقــد وردتنــا املعاملــة مــن قســم الصلــح بخطــاب رئيســه رقــم ‪3471454‬‬\n‫وتاريــخ ‪1434/6/3‬ه ـ ومرفــق بــه محضــر اللجنــة واملتضمــن (فإنــا نــرى‬\n‫أن يدفــع النفقــة املاضيــة ومقدارهــا ســتة آالف وســتمائة ريــال للمــدة‬\n‫املاضيــة ومقدارهــا أحــد عشــر شــهرا) أه ـ وبعرضــه علــى الطرفــن‬\n‫قــررت املدعيــة موافقتهــا عليــه وقــرر املدعــى عليــه عــدم موافقتــه عليه ‪،‬‬\n‫وقــرر املدعــى عليــه قائــا ‪ :‬إننــي غيــر موظــف وهــذا املبلــغ املقــدر كبيــر‬\n‫جــدا ‪ .‬وبعرضــه علــى املدعيــة قالــت ‪ :‬هــو مقتــدر ‪ ،‬ويعمــل يف التجــارة‬\n‫احلــرة ‪ ،‬ومــا قــدره أهــل اخلبــرة أخــذ يف االعتبــار حــال املدعــى عليــه‬\n‫مــن زعمــه عــدم القــدرة ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫‪ ،‬وبنــاء علــى دفــع املدعــى عليــه عــدم اســتحقاق املدعيــة للنفقــة بحجــة‬\n\n\n                                                                                           ‫‪290‬‬\n\f      ‫املــرض والســحر وانكــرت املدعيــة ذلــك وطلــب املدعــى عليــه ميينهــا‬\n      ‫علــى اإلنــكار وحلفــت ‪ ،‬وبنــاء علــى مــا أقــرره أعضــاء جلنــة الصلــح ‪،‬‬\n      ‫ولقولــه تعالــى (لينفــق ذو ســعة مــن ســعته) ولقولــه تعالــى (ولهــن مثــل‬\n      ‫الــذي عليهــن باملعــروف) ‪ ،‬وحلديــث (ولهــن عليكــم رزقهــن وكســوتهن‬\n      ‫باملعــروف) رواه مســلم وغيــره‪ ،‬وحلديــث عائشــة رضــي اهلل عنهــا ‪ :‬أن‬\n      ‫هنــد بنــت عتبــة قالــت لرســول اهلل صلــى اهلل عليــه وســلم ‪ :‬إن أبــا ســفيان‬\n      ‫رجــل شــحيح ‪ ،‬وليــس يعطينــي مــا يكفينــي وولــدي إال مــا أخــذت منــه‬\n      ‫‪ ،‬وهــو ال يعلــم ‪ ،‬فقــال ‪( :‬خــذي مــا يكفيــك وولــدك باملعــروف) رواه‬\n      ‫البخــاري ومســلم وغيرهمــا ‪ ،‬وحلديــث (أن النبــي صلــى اهلل عليــه وســلم‬\n      ‫قضــى أن اليمــن علــى املدعــى عليــه) رواه البخــاري ‪ ،‬وحلديــث (البينــة‬\n      ‫علــى املدعــي واليمــن علــى املدعــى عليــه) رواه الترمــذي ‪ ،‬قــال أبــو‬\n      ‫عيســى ‪ :‬العمــل عنــد أهــل العلــم مــن أصحــاب النبــي صلــى اهلل عليــه‬\n      ‫وســلم وغيرهــم أن البينــة علــى املدعــي واليمــن علــى املدعــى عليــه ‪،‬‬\n      ‫لذلــك كلــه ‪ ،‬فقــد حكمــت علــى املدعــى عليــه ‪...‬بدفــع مبلــغ قــدره‬\n      ‫ســتة آالف وســتمائة ريــال للمدعيــة ‪ . ...‬وبــه قنعــت املدعيــة وقــرر املدعــى‬\n      ‫عليــه االعتــراض ‪ ،‬وجــرى تســليمه نســخة مــن احلكــم وإفهامــه بــأن‬\n      ‫لــه احلــق يف االعتــراض عليــه خــال ثالثــن يومــا ‪ ،‬وإال ســقط حقــه يف‬\n      ‫االعتــراض ‪ ،‬واكتســب احلكــم القطعيــة ‪ .‬وأقفلــت اجللســة الســاعة‬\n      ‫‪ . 04 : 15‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                       ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/06/17‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة ففــي يــوم األربعــاء املوافق‪1434/10/14‬ه ـ افتتحــت‬\n      ‫اجللسة الساعة ‪ 9 : 15‬وفيها قد عادت املعاملة من محكمة االستئناف‬\n\n\n‫‪291‬‬\n\f‫بخطــاب رئيســها رقــم ‪ 3471454‬وتاريــخ ‪1434/9/10‬ه ـ وبالقــرار رقــم‬\n‫‪ 34312771‬وتاريــخ ‪1434/9/6‬ه ـ ومضمونــه مــا يلي ( وبدراســة الصك‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة ‪ ،‬تقــررت املوافقــة علــى احلكــم ‪.‬‬\n‫وأقفلــت اجللســة الســاعة ‪ 9 : 20‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n            ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/10/14‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة جــده برقــم ‪ 3471454‬وتاريــخ ‪1434/8/25‬ه ـ املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪...‬القاضــي باحملكمــة العامــة‬\n‫مبحافظــة جــده برقــم ‪ 34243280‬وتاريــخ ‪1434/6/17‬ه ـ ‪ ،‬املتضمــن‬\n‫دعــوى املــرأة ‪...‬ضــد ‪...‬يف نفقــه ‪ ،‬وبدراســة الصــك وصــورة ضبطــه‬\n‫والئحتــه االعتراضيــة ‪ ،‬تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪.‬‬\n                 ‫وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪292‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":287,"source_page_end":292,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"70d3a93bba133a36d574ccd4add6218126bc1d82b30dcc2a05f092b5374d8ada","normalized_text_hash":"be7526c8b27c498809122be1a9b97a8cf90c0c417142f755c960da2a48480c85","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p287-34243280"},{"id":"a8d05d4c-6770-51e5-8600-e464a016616e","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -املطالبة بتكاليف الوالدة -حتديد نفقة ماضية ومستقبله للطفل -نفقة احلامل -النفقة بنية الرجوع -دفع املدعى عليه بعدم أحقية املدعية لتكاليف الوالدة لوجود مستشفيات حكومية متاحة -تقدير النفقة عن طريق قسم اخلبراء -النشوز ال يسقط نفقة احلامل -اإللزام بدفع نفقة فترة احلمل ونفقة الطفل املاضية وحتديد نفقة مستقبلية للطفل .","document_number":"34263198","case_number":"32495714","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/9","year":"1434","subject":"نفقة -املطالبة بتكاليف الوالدة -حتديد نفقة ماضية ومستقبله للطفل -نفقة احلامل -النفقة بنية الرجوع -دفع املدعى عليه بعدم أحقية املدعية لتكاليف الوالدة لوجود مستشفيات حكومية متاحة -تقدير النفقة عن طريق قسم اخلبراء -النشوز ال يسقط نفقة احلامل -اإللزام بدفع نفقة فترة احلمل ونفقة الطفل املاضية وحتديد نفقة مستقبلية للطفل .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/7/9 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34263198 :‬‬\n                         ‫َر ْق ُم الدعوى‪32495714 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34320855‬تاريخه‪1434/9/16 :‬هـ‬\n\n\n\n      ‫نفقــة ‪ -‬املطالبــة بتكاليــف الــوالدة ‪ -‬حتديــد نفقــة ماضيــة ومســتقبله‬\n      ‫للطفــل ‪ -‬نفقــة احلامــل ‪ -‬النفقــة بنيــة الرجــوع‪ -‬دفــع املدعــى عليــه‬\n      ‫بعــدم أحقيــة املدعيــة لتكاليــف الــوالدة لوجــود مستشــفيات حكوميــة‬\n      ‫متاحــة‪ -‬تقديــر النفقــة عــن طريــق قســم اخلبــراء‪ -‬النشــوز ال يســقط‬\n      ‫نفقــة احلامــل ‪ -‬اإللــزام بدفــع نفقــة فتــرة احلمــل ونفقــة الطفــل‬\n                                 ‫املاضيــة وحتديــد نفقــة مســتقبلية للطفــل ‪.‬‬\n\n\n\n\n      ‫كـ َّـن أُوالتِ َح ْمــلٍ فَ َأ ْنفِ ُقــوا َع َل ْيهِ ـ َّـن َح َّتــى َي َض ْعـ َـن‬\n                                                                                          ‫‪ -1‬قولــه تعالــى ( َو ِإ ْن ُ‬\n                                                                                                             ‫َح ْم َل ُهـ َّـن )‬\n      ‫‪ -2‬قــال يف الــروض املربــع (‪ )115/7‬والنفقــة للبائــن احلامــل (للحمــل)‬\n      ‫نفســه ال لهــا مــن أجلــه ألنهــا جتــب بوجــوده وتســقط بعدمــه فتجــب‬\n                                                                                                         ‫حلامــل ناشــز‬\n\n\n\n\n      ‫ادعــى وكيــل املدعيــة بــأن املدعــى عليــه أصالــة تزوج موكلتــه ثم طلقها‬\n      ‫وهــي حامــل وقــد وضعــت مولــود ًا ذكــر ًا ‪ -‬طلــب املدعــي وكالــة إلــزام‬\n      ‫املدعــي عليــه بدفــع تكاليــف الــوالدة وحتديــد نفقــه مســتقبله للطفــل ‪-‬‬\n      ‫أقــر املدعــى عليــه وكالــة مبــا جــاء يف الدعــوى وقــرر أنــه ال مانــع لــدى‬\n‫‪293‬‬\n\f‫موكلــه مــن حتديــد نفقــه مســتقبله لطفلــه أمــا تكاليــف الــوالدة فطلــب‬\n‫مهلــه للرجــوع ملوكلــه‪ -‬يف جلســه أخــرى قــرر املدعــى وكالــه أنــه يطلب‬\n‫نفقــه احلمــل ملوكلتــه تســعة أشــهر‪ -‬كمــا قــرر بــأن موكلتــه أنفقــت‬\n‫علــى الطفــل بنيــة الرجــوع علــى املدعــى عليــه‪ -‬صــادق املدعــى عليــه أن‬\n‫املدعيــة خرجــت مــن بيتــه وهــي يف الشــهر األول مــن احلمــل وقــرر أنــه غير‬\n‫مســتعد بدفــع نفقــة احلمــل ألنهــا ناشــز‪ -‬قــرر املدعــى عليــه اســتعداده‬\n‫بدفــع نفقــة ابنــه املاضيــة واملســتقبلية‪ -‬قــرر املدعــى عليــه بــأن املدعيــة‬\n‫الحــق لهــا يف تكاليــف الــوالدة ألن هنــاك مستشــفيات حكوميــة‬\n‫متاحــة‪ -‬وذهابهــا ملستشــفى أهلــي يعــد تبرع ـاً‪ -‬مت تقديــر نفقــة الطفــل‬\n‫املاضيــة واملســتقبلة عــن طريــق قســم اخلبــراء‪ -‬حيــث إمنــا دفــع بــه املدعــى‬\n‫عليــه مــن نشــوز املدعيــة ال عبــرة بــه ألن النفقــة واجبــة للزوجــة احلامــل‬\n‫وان كانــت ناشــزاً‪ -‬كمــا أن مــا طلبتــه املدعيــة مــن تكاليــف الوالدة ال‬\n‫مســوغ لــه لوجــود مستشــفيات حكوميــة متاحــة‪ -‬صــدر احلكــم بإلــزام‬\n‫املدعــى عليــه بدفــع نفقــة فتــرة احلمــل ونفقــة الطفــل املاضيــة وحتديــد‬\n‫نفقــه مســتقبلة للطفــل تســلم لوالدتــه املدعيــة وصــرف النظــر عــن دعــوى‬\n‫املدعيــة فيمــا ســوى ذلــك‪ -‬قــرر الطرفــان عــدم القناعــة‪ -‬صــدق احلكــم‬\n                                                       ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 32495714‬وتاريــخ‬\n‫‪ 1432/11/04‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321378590‬وتاريــخ‬\n\n                                                                                       ‫‪294‬‬\n\f      ‫‪ 1432/11/04‬ه ـ ففــي يــوم الســبت املوافــق‪ 1434/01/17‬ه ـ افتتحت‬\n      ‫اجللســة الســاعة ‪ 09 : 15‬وفيهــا حضــر ‪ ،...‬ســعودي اجلنســية مبوجــب‬\n      ‫الهويــة الوطنيــة رقــم‪... :‬الوكيــل عــن ‪...‬مبوجــب الوكالــة الصــادرة مــن‬\n      ‫كتابــة العــدل الثانيــة بجنــوب جــدة برقــم‪ 35347 :‬يف‪1432/10/13 :‬هـ‬\n      ‫واملخــول لــه فيهــا حــق املرافعــة واملدافعــة واإلنــكار واالســتالم والتســليم‬\n      ‫للصكــوك‪ ،‬وحضــر حلضــوره‪ ،... :‬ســعودي اجلنســية مبوجــب الهويــة‬\n      ‫الوطنيــة رقــم‪... :‬الوكيــل عــن‪... :‬مبوجــب الوكالــة الصــادرة مــن كتابة‬\n      ‫العــدل الثانيــة مبكــة املكرمــة واملخــول لــه فيهــا حــق املرافعــة واملدافعــة‬\n      ‫وســماع الدعــوى والــرد عليهــا‪ ،‬وادعــى األول قائــا‪ :‬إن ‪...‬كان زوجــا‬\n      ‫ملوكلتــي وقــد طلقهــا طلقــة واحــدة بتاريــخ‪1432/9/20 :‬ه ـ وكانــت‬\n      ‫وقتهــا حامــا ووضعــت مولودهــا املســمى (‪ )...‬ولــم يراجعهــا‪ ،‬أطلــب‬\n      ‫إلــزام املدعــى عليــه بتحمــل تكاليــف الــوالدة البالــغ قدرهــا‪ :‬أربعــة آالف‬\n      ‫ريــال‪ ،‬وحتديــد نفقــة مســتقبلية قدرهــا‪ :‬ألــف وخمــس مئــة ريــال البــن‬\n      ‫املدعــى عليــه‪ ،‬هكــذا ادعــى‪ .‬وبعــرض ذلــك علــى املدعــى عليــه وكالــة‬\n      ‫أجــاب قائــا‪ :‬مــا ذكــره املدعــي وكالــة مــن الــزواج والطــاق وتاريخــه‬\n      ‫وصفتــه والولــد (‪ )...‬وأنهــا وضعــت احلمــل بعــد الطــاق فصحيــح‪ ،‬وال مــا‬\n      ‫نــع لــدى موكلــي مــن حتديــد نفقــة مســتقبلية ال تزيــد عــن خمــس مئــة‬\n      ‫ريــال‪ ،‬أمــا تكاليــف الــوالدة فأطلــب مهلــة للرجــوع ملوكلــي‪ ،‬هكــذا‬\n      ‫أجــاب‪ .‬ويف يــوم األحــد املوافــق‪ 1434/07/09‬ه ـ حضــر ‪...‬واملثبــت هويته‬\n      ‫ووكالتــه يف جلســة ســابقة وحضــر حلضــوره ‪...‬ســعودي اجلنســية مبوجــب‬\n      ‫الهويــة الوطنيــة رقــم ‪...‬ثــم قــرر املدعــي وكالــة قائــا‪ :‬إن موكلتــي‬\n      ‫خرجــت مــن منــزل املدعــى عليــه أصالــة وهــي حامــل يف بدايــة الشــهر‬\n      ‫األول وقــد مكــث حملهــا تســعة أشــهر‪ ،‬وأطلــب إلزامــه بســداد نفقتهــا‬\n\n\n‫‪295‬‬\n\f‫أثنــاء حملهــا‪ ،‬وتكاليــف الــوالدة البالــغ قدرهــا‪ :‬أربعــة عشــر ألــف‬\n‫ريــال‪ ،‬وقــد كانــت موكلتــي تنفــق علــى ابــن املدعــى عليــه ‪...‬مــن تاريــخ‪:‬‬\n‫‪1433/5/8‬ه ـ بنيــة الرجــوع‪ ،‬أطلــب إلزامــه بســداد النفقــة الســابقة‬\n‫وحتديــد نفقــة مســتقبلية البنــه‪ )...( :‬اعتبــارا مــن تاريــخ‪1434/7/9 :‬ه ـ‬\n‫هكــذا قــرر‪ .‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا‪ :‬صحيــح أن‬\n‫املدعيــة خرجــت مــن منزلــي وهــي يف الشــهر األول مــن حملهــا وأنــا غيــر‬\n‫مســتعد بتســليم النفقــة ألنهــا خرجــت ناشــزا‪ ،‬وأمــا ابنــي ‪...‬فمنــذ تاريــخ‬\n‫والدتــه ‪1433/5/8‬ه ـ حتــى تاريــخ‪1434/7/8 :‬ه ـ لــم أنفــق عليــه إطالقا‬\n‫ألنهــم قالــوا لــي ال نأخذهــا منــك إال يف احملاكــم لتشــويه ســمعتك‪ ،‬أمــا‬\n‫تكاليــف الــوالدة فليــس لهــا حــق فيهــا إطالقــا ألن هنــاك مستشــفيات‬\n‫حكوميــة متاحــة وأنــا عســكري واملستشــفى العســكري متــاح لهــا‬\n‫وذهابهــا ملستشــفى أهلــي يعــد تبرعــا منهــا وأطلــب رد دعــوى املدعيــة‬\n                                        ‫وإخــاء ســبيلي منهــا‪ ،‬هكــذا أجــاب‪.‬‬\n‫وكنــا قــد كتبنــا لقســم اخلبــراء باحملكمــة لتحديــد النفقــة فوردنــا‬\n‫اجلــواب برقــم‪ 34216389 :‬يف‪1434/07/04 :‬ه ـ وبرفقهــا محضــر‬\n‫ونــص احلاجــة منــه‪( :‬وقــال املدعــي وكالــة أطلــب حتديــد نفقــة البــن‬\n‫موكلتــي املســمى ‪...‬ويبلــغ مــن العمــر مــا يقــارب عشــرة أشــهر واملولــود‬\n‫بتاريــخ‪1433/05/08 :‬ه ـ وبســؤال املدعــى عليــه وكالة قــال ال مانع من‬\n‫حتديــد نفقــة البــن موكلــي بحــدود خمســمائة ريــال حيــث أن موكلــي‬\n‫ال يســتطيع أن يدفــع أكثــر مــن ذلــك وحيــث متــت مخاطبــة عمــل املدعــى‬\n‫عليــه وردتنــا اإلفــادة املرفقــة التــي توضــح بــأن راتــب املدعــى عليــه‬\n‫أربعــة عشــر ألــف وأربــع مئــة واثنــا عشــر ريــال وســتون هللــه‪ ،‬وحيــث‬\n‫األمــر مــا ذكــر فإننــا نــرى والــرأي لكــم بــأن تكــون النفقــة بواقــع‬\n\n\n                                                                                    ‫‪296‬‬\n\f      ‫ألــف ريــال شــهريا اعتبــارا مــن شــهر ‪ 7‬لعــام ‪1434‬ه ـ وتكــون النفقــة‬\n      ‫الســابقة ومدتهــا ‪ 13‬ثالثــة عشــر شــهرا بواقــع ثالثــة عشــر ألــف ريــال‬\n      ‫وتكــون كســوة العيــد ألــف ريــال)‪ .‬ا‪ .‬ه ـ فبنــاء علــى مــا ســلف‪ ،‬وألن‬\n      ‫املدعيــة طالبــت بقيمــة والدتهــا يف املستشــفى وقدرهــا‪ :‬أربعــة عشــر ألــف‬\n      ‫ريــال وامتنــع املدعــى عليــه مــن تســليمها‪ ،‬وطلــب املدعيــة غيــر وجيــه‬\n      ‫ألن الــوالدة ممكنــة يف املستشــفيات احلكوميــة فتكلُّفهــا يف غيــر‬\n      ‫احلكوميــة‪ ،‬ومبــا أن املدعيــة‬\n                                 ‫ّ‬               ‫مح ّلــه ألن لهــا مندوحــة يف املستشــفيات‬\n      ‫طالبــت بالنفقــة فتــرة احلمــل وامتنــع املدعــى عليــه مــن تســليمها ودفــع‬\n      ‫بأنهــا ناشــز ودفعــه هــذا ال وجــه لــه ألنــه يجــب علــى الــزوج اإلنفــاق‬\n            ‫(و ِإنْ ُ‬\n      ‫كـ َّـن‬      ‫علــى الزوجــة احلامــل ولــو كانــت ناشــزا لقــول اهلل ـ تعالــى ـ َ‬\n      ‫والت َح ْمـ ٍـل َف َأ ْنفِ ُقــوا َع َل ْي ِهـ َّـن َح َّتــى َي َض ْعـ َـن َح ْم َل ُهـ َّـن)‪ ،‬قــال يف الــروض‬\n                                                                                                                  ‫ُأ ِ‬\n      ‫املربــع ‪([ 115/7‬والنفقــة) للبائــن احلامــل (للحمــل) نفســه (ال لهــا مــن‬\n      ‫أجلــه) ألنهــا جتــب بوجــوده وتســقط بعدمــه فتجــب حلامــل ناشــز)] وبنــاء‬\n      ‫علــى قــرار قســم اخلبــراء املرصــود أعــاه لذلــك كلــه فقــد قــررت مــا‬\n      ‫يلــي‪ ،‬أوال‪ :‬ألزمــت املدعــى عليــه أن يســلم للمدعيــة نفقتهــا فتــرة حملهــا‬\n      ‫وقدرهــا‪ :‬تســعة آالف ريــال‪ .‬ثانيــا‪ :‬ألزمــت املدعــى عليــه أن يســلم نفقــة‬\n      ‫ابنــه ‪...‬الســابقة مــن تاريــخ‪1433/5/8 :‬ه ـ حتــى تاريــخ‪1434/7/8 :‬ه ـ‬\n      ‫وقدرهــا‪ :‬أربعــة عشــر ألــف ريــال‪ .‬ثالثــا‪ :‬ألزمــت املدعــى عليــه أن يســلم‬\n      ‫نفقــة ابنــه ‪...‬املســتقبلية لوالدتــه املدعيــة وقدرهــا‪ :‬ألــف ريــال اعتبــارا‬\n      ‫مــن تاريــخ‪1434/8/8 :‬ه ـ رابعــا‪ :‬رددت طلــب املدعيــة فيمــا ســوى ذلــك‪،‬‬\n      ‫ـتعدا‬\n         ‫وبذلــك قضيــت‪ .‬وبإعــان احلكــم قــرر الطرفــن عــدم القناعــة واسـ ّ‬\n      ‫اعتراضيــة‪ ،‬فجــرى تســليم كل واحــد منهمــا نســخة مــن‬‫ّ‬          ‫بتقــدمي الئحــة‬\n      ‫احلكــم وأفهمتهمــا بــأن لهمــا احلــق يف تقــدمي اعتراضهمــا خــال ثالثــن‬\n\n\n‫‪297‬‬\n\f‫يوم ـ ًا اعتبــار ًا مــن هــذا اليــوم‪ ،‬وإذا انتهــت املـ ّـدة احملــددة ولــم يقــدم أي‬\n‫القطعيــة‪.‬‬\n    ‫ّ‬        ‫حقــه يف االعتــراض واكتســب احلكــم‬      ‫منهــم بالئحتــه ســقط ّ‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                           ‫وســلم ‪ .‬حــرر يف ‪ 1434/07/09‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬ويف يــوم الثالثــاء املوافــق‪1434/10/13 :‬ه ـ‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا قــرار دائــرة األحــوال‬\n‫الشــخصية الثالثــة رقــم‪ 34320855 :‬يف‪1434/09/16 :‬ه ـ ونص احلاجة‬\n‫منــه‪( :‬وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيتــن تقــررت‬\n‫املوافقــة علــى احلكــم)‪ .‬ا‪ .‬ه ـ وللبيــان جــرى إثباتــه‪ ،‬وأمــرت بإحلــاق ذلــك‬\n‫علــى الصــك والســجل‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                    ‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/10/13 :‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة جــدة برقــم ‪ 32/1378590‬وتاريــخ ‪1434/9/8‬ه ـ‬\n‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪...‬القاضــي باحملكمــة‬\n‫العامــة مبحافظــة جــدة برقــم ‪ 34263198‬وتاريــخ ‪1434/7/9‬ه ـ ‪،‬‬\n‫املتضمــن دعــوى املــرأة ‪...‬ضــد ‪...‬يف نفقــة ‪ ،‬وبدراســة الصــك وصــورة‬\n‫ضبطــه والئحتيــه االعتراضيتــن تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل‬\n      ‫املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                            ‫‪298‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":293,"source_page_end":298,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"24b017ef2df35caa190eff640424877b261e51b32c78e36a0aafd9025bfc751c","normalized_text_hash":"a959c12a39caabeb63378e55e4c4eda88a58a987c0c7ca930132ed3cf6d74548","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p293-34263198"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"450d293b-661c-5985-adbd-091f1278a87b","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -طلب نفقة مستقبلية لأوالد -احلكم على األب بدفع نفقة أوالده حسب تقدير قسم اخلبراء -1قولة تعالى ( لينفق ذو سعه من سعته ومن قدر عليه رزقه فلينفق مما آتاه اهلل ) -2ما رواه البخاري من حديث هند بنت عتبه قالت يا رسول اهلل إن أبا سفيان رجل شحيح وليس يعطيني ما يكفيني وولدي إال ما أخذت منه وهو ال يعلم فقال عليه الصاة والسام خذي ما","document_number":"34185311","case_number":"3412973","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باخلبر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/10","year":"1434","subject":"نفقة -طلب نفقة مستقبلية لأوالد -احلكم على األب بدفع نفقة أوالده حسب تقدير قسم اخلبراء -1قولة تعالى ( لينفق ذو سعه من سعته ومن قدر عليه رزقه فلينفق مما آتاه اهلل ) -2ما رواه البخاري من حديث هند بنت عتبه قالت يا رسول اهلل إن أبا سفيان رجل شحيح وليس يعطيني ما يكفيني وولدي إال ما أخذت منه وهو ال يعلم فقال عليه الصاة والسام خذي ما","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/10 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34185311 :‬‬\n                           ‫َر ْق ُم الدعوى‪3412973 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34293469‬تاريخه‪1434/8/10 :‬هـ‬\n\n\n\n        ‫نفقــة‪ -‬طلــب نفقــة مســتقبلية لــأوالد‪ -‬احلكــم علــى األب بدفــع نفقــة‬\n                                                       ‫أوالده حســب تقديــر قســم اخلبــراء‬\n\n\n\n\n        ‫‪ -1‬قولــة تعالــى ( لينفــق ذو ســعه مــن ســعته ومــن قــدر عليــه رزقــه فلينفــق‬\n                                                                           ‫ممــا آتــاه اهلل )‬\n        ‫‪ -2‬مــا رواه البخــاري مــن حديــث هنــد بنــت عتبــه قالــت يــا رســول اهلل‬\n        ‫إن أبــا ســفيان رجــل شــحيح وليــس يعطينــي مــا يكفينــي وولــدي إال‬\n        ‫مــا أخــذت منــه وهــو ال يعلــم فقــال عليــه الصــاة والســام خــذي مــا‬\n                                                          ‫يكفيــك وولــدك باملعــروف)‬\n        ‫‪ -3‬أجمــع العلمــاء علــى وجــوب نفقــة األب علــى أوالده إذا كانــوا بالغــن‬\n        ‫قــال ابــن املنــذر ( أجمــع كل مــن نحفــظ عنــه مــن أهــل العلــم أن علــى‬\n                                     ‫املــرء نفقــة أوالده األطفــال الذيــن ال مــال لهــم )‬\n\n\n\n\n        ‫ادعــت املدعيــة املعــرف بهــا مــن قبــل أخيهــا بــأن املدعــى عليــه تزوجهــا‬\n        ‫ودخــل بهــا الدخــول الشــرعي وأجنبــت منــه خمســة أوالد أربعــة أبنــاء‬\n        ‫وبنتـ ًا وذكــرت أســماءهم وأعمارهــم‪ ،‬وقــد طلقهــا الطلقــة الثانية وترك‬\n        ‫األوالد معهــا طلبــت املدعيــة إلــزام املدعــى عليــه بالنفقــة املســتقبلية علــى‬\n‫‪259‬‬\n\f‫األوالد صــادق املدعــى عليــه علــى مــا جــاء يف الدعــوى وقــرر أنــه ال مانــع‬\n‫لديــه مــن اإلنفــاق علــى األوالد بعــد حتديــد مقدارهــا مــن أهــل اخلبــرة‪-‬‬\n‫مت حتديــد النفقــة مــن قســم اخلبــراء‪ -‬لقولــه تعالــى (لينفــق ذو ســعة مــن‬\n‫ســعته ومــن قــدر عليــه رزقــه فلينفــق ممــا آتــاه اهلل) ولقولــه صلــى اهلل‬\n‫عليــة وســلم لهنــد بنــت عتبــه ( خــذي مــا يكفيــك وولــدك باملعــروف‬\n‫) وملــا نقلــه ابــن املنــذر مــن اإلجمــاع علــى نفقــة األطفــال الذيــن ال مــال‬\n‫لهــم علــى والدهــم لــذا صــدر احلكــم علــى األب املدعــى عليــه بدفــع‬\n‫نفقــة أوالده املذكوريــن حســبما جــاء يف قــرار قســم اخلبــراء‪ -‬قنعــت‬\n‫املدعيــة باحلكــم ولــم يقنــع املدعــى عليــه‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                     ‫االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n‫‪ ...‬القاضــي يف احملكمــة العامــة باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة باخلبــر املكلــف برقــم ‪3412973‬‬\n‫وتاريــخ ‪1434/1/7‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3460473‬وتاريــخ‬\n‫‪1434/1/7‬ه ـ ففــي يــوم اإلثنــن املوافــق ‪1434/2/18‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 8:30‬وفيهــا حضــرت املدعيــة أصالــة ‪...‬ســعودية‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وحضــر حلضورهــا معرف ـ ًا بهــا‬\n‫أخوهــا ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬كمــا حضــر‬\n‫املدعــى عليــه أصالــة ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪...‬فادعــت املدعيــة قائلــة يف دعواهــا‪ :‬لقــد تزوجــت باملدعــى عليــه قبــل‬\n‫قرابــة ثالثــة عشــرة ســنة يف عــام ‪1420‬ه ـ ودخــل بــي الدخــول الشــرعي‬\n\n                                                                                        ‫‪260‬‬\n\f      ‫وأجنبــت منــه ‪...‬املولــود يف ‪1425/12/21‬ه ـ وعمــره ثمــان ســنوات و‪...‬‬\n      ‫املولــود يف ‪1429/10/29‬ه ـ وعمــره خمــس ســنوات و‪ ...‬املولــودة يف‬\n      ‫‪1429/11/26‬ه ـ وعمرهــا أربــع ســنوت و‪ ...‬املولــود يف ‪1431/7/27‬ه ـ‬\n      ‫وعمــره ســنتان و‪ ...‬املولــود يف ‪1433/3/2‬ه ـ وقــد طلقنــي الطلقــة الثانيــة‬\n      ‫يف ‪1433/12/26‬ه ـ واألوالد معــي يف البيــت لــذا أطلــب إلــزام املدعــى‬\n      ‫عليــه بالنفقــة املســتقبلية لــأوالد هــذه دعــواي وبعــرض دعــوى املدعيــة‬\n      ‫علــى املدعــى عليــه أجــاب قائـاً‪ :‬مــا ذكرتــه املدعيــة يف دعواهــا صحيح‬\n      ‫فلقــد تزوجــت باملدعيــة بالتاريــخ املذكــور ودخلت بها الدخول الشــرعي‬\n      ‫وأجنبــت منــي ‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪......‬بالتواريــخ املذكــورة وصحيــح بأننــي‬\n      ‫طلقتهــا الطلقــة الثانيــة يف ‪1433/12/26‬ه ـ وال مانــع لــدي مــن اإلنفــاق‬\n      ‫علــى األوالد بعــد حتديــد مقــدار النفقــة مــن أهــل اخلبــرة هكــذا أجــاب‬\n      ‫لــذا رفعــت اجللســة الســاعة ‪ 9.00‬للكتابــة إلــى هيئــة النظــر لتقديــر‬\n      ‫النفقــة املســتقبلية لــأوالد ويف جلســة أخــرى حضــرت املدعيــة أصالــة‬\n      ‫‪...‬برفقــة أخيهــا املعــرف بهــا ‪...‬كمــا حضــر املدعــى عليــه ‪...‬هــذا وقــد‬\n      ‫جــرت الكتابــة إلــى هيئــة النظــر باحملكمــة باخلطــاب رقــم ‪34533461‬‬\n      ‫يف ‪1434/3/24‬ه ـ بخصــوص االجتمــاع بالطرفــن وتقديــر نفقــة األوالد‬\n      ‫فوردنــا جوابهــم باخلطــاب رقــم ‪ 34533461‬يف ‪1434/3/24‬ه ـ مرفق ًا به‬\n      ‫قــرار رقــم ‪ 371‬يف ‪1434/3/34‬ه ـ ونصــه بعــد املقدمــة (عليــه نفيدكــم‬\n      ‫أنــه بعــد االطــاع علــى الراتــب واجللــوس مــع الطرفــن ودراســة حــال األب‬\n      ‫فإننــا نــرى أن تكــون النفقــة الشــهرية ألبنائــه علــى النحــو التالــي نفقــة‬\n      ‫‪550 ...‬ريــال نفقــه ‪450 ...‬ريــال نفقــة ‪500 ...‬ريــال نفقــة ‪400 ...‬ريــال نفقــة‬\n      ‫‪500 ...‬ريــال هــذا مــا نــراه) عضــو هيئــة النظــر ‪ ...‬توقيعــه عضــو هيئــة‬\n                                    ‫النظــر ‪...‬توقيعــه عضــو هيئــة النظــر ‪ ...‬توقيعــه‬\n\n\n‫‪261‬‬\n\f‫ـاء علــى مــا تقــدم مــن‬\n                         ‫وبعــرض القــرار علــى الطرفــن لــم يقنعــا بــه فبنـ ً‬\n‫ـاء علــى قــرار هيئــة النظــر ذي الرقــم ‪ 371‬املــؤرخ‬    ‫الدعــوى واإلجابــة وبنـ ً‬\n‫يف ‪1434/3/23‬ه ـ ولقولــه تعالــى (لينفــق ذو ســعة مــن ســعته ومــن قــدر‬\n‫عليــه رزقــه فلينفــق ممــا آتــاه اهلل) وملــا رواه البخــاري مــن حديــث هنــد‬\n‫بنــت عتبــه (قالــت يــا رســول اهلل إن أبــا ســفيان رجــل شــحيح وليــس‬\n‫يعطينــي مــا يكفينــي وولــدي إال مــا أخــذت منــه وهــو ال يعلــم فقــال عليــه‬\n‫الصــاة والســام خــذي مــا يكفيــك وولــدك باملعــروف) وقــد أجمــع‬\n‫العلمــاء علــى وجــوب نفقــة األب علــى أوالده إذا كانــوا بالغــن قــال ابــن‬\n‫املنــذر (أجمــع كل مــن نحفــظ عنــه العلــم أن علــى املــرء نفقــة أوالده‬\n‫األطفــال الذيــن ال مــال لهــم) لذلــك كلــه فقــد حكمــت بإلــزام املدعــى‬\n‫عليــه بدفــع مبلــغ وقــدره خمســمائة وخمســن ريــال نفقــة ‪...‬وأربعمائــة‬\n‫وخمســن ريــال نفقــة ‪...‬وخمســمائة ريــال نفقــة ‪...‬وأربعمائــة ريــال نفقــة‬\n‫‪...‬وخمســمائة ريــال نفقــة ‪...‬بتاريــخ اخلامــس والعشــرين مــن كل شــهر‬\n‫قمــري وتســلم لوالدتهــم مــا دامــوا يف حضانتهــا وبعــرض احلكــم علــى‬\n‫الطرفــن قــررت املدعيــة القناعــة بــه ولــم يقنــع املدعــى عليــه وقــرر تقــدمي‬\n‫الئحتــه االعتراضيــة فافهــم باملراجعــة بعــد ثالثــة أيــام الســتالم نســخة‬\n‫مــن احلكــم وتقــدمي الئحتــه االعتراضيــة خــال ثالثــن يــوم مــن تاريــخ‬\n‫تســجيل الصــك وأنــه إن لــم يتقــدم بشــيء خــال املــدة املشــار إليهــا فــإن‬\n‫حقــه يف االعتــراض يســقط ويكتســب احلكــم القطعيــة ففهــم ذلــك‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n                                                            ‫حــرر يف ‪1434/4/8‬ه ـ‬\n‫احلمد هلل وحده وبعد ففي يوم اخلميس املوافق ‪1434/8/25‬هـ افتتحت‬\n‫اجللســة الســاعة ‪ 9:45‬هــذا وقــد عــادت املعاملــة من محكمة االســتئناف‬\n\n\n                                                                                        ‫‪262‬‬\n\f      ‫باملنطقــة الشــرقية باخلطــاب رقــم ‪ 341660752‬يف ‪1434/8/15‬ه ـ‬\n      ‫مرفق ـ ًا بهــا قــرار املصادقــة مــن دائــرة األحــوال الشــخصية األولــى‬\n      ‫برقــم ‪ 34293469‬يف ‪1434/8/10‬ه ـ ونصــه بعــد املقدمــة (وبدراســة‬\n      ‫الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا‬\n      ‫املصادقــة علــى احلكــم) قاضــي االســتئناف د‪ ... .‬ختمــه وتوقيعــه قاضــي‬\n      ‫االســتئناف ‪...‬ختمــه وتوقيعــه رئيــس الدائــرة ‪...‬ختمــه وتوقيعــه وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                                   ‫يف ‪1434/8/25‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة دائ ــرة األحــوال‬\n      ‫الشــخصية األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية‬\n      ‫علــى املعاملــة املقيــدة باحملكمــة برقــم ‪/34/1660752‬ش‪1‬‬\n      ‫وتاريخ‪1434/7/10‬ه ـ الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫مبحافظــة اخلبــر املســاعد برقــم ‪ 34/60473‬وتاريــخ ‪1434/7/2‬ه ـ‬\n      ‫املرفــق بهــا الصــك الصــادر مــن فضيل ــة القاضــي بهــا الشــيخ ‪.../‬املســجل‬\n      ‫برقــم ‪ 34185311‬وتاريخ‪1434/4/10‬ه ـ اخلــاص بدعوى‪.../‬ضــد‪.../‬‬\n      ‫يف قضيــة نفقــة‪ .‬وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n      ‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم مــع تنبيــه فضيلــة القاضــي‬\n      ‫إلــى التصريــح يف احلكــم بــأن هــذا مشــمول بالنفــاذ املعجــل حســب مــا‬\n      ‫نصــت عليــه التعليمــات ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                          ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/8‬ه ـ‬\n\n\n\n\n‫‪263‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":259,"source_page_end":263,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aad80365242a2c27b562a7156b7c3734c1f6fd7c74ddf3afb03e624a0d731f02","normalized_text_hash":"18030c0c9fd8fe5c447eb4f275223cf1329d3f6bc00a37fee5f257a8f9afe61c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p259-34185311"},{"id":"9d391827-9668-50cd-b16b-3a844bb29b13","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -مطالبة مطلقة بنفقة عدتها -مطالبة أم بنفقة ابنتها املاضية واملستقبلية -مطالبة بزيادة نفقة ماضية لعدم كفايتها -املطالبة مبتعة الطاق -حلف اليمن على نية الرجوع بالنفقة -احلكم بتسليم نفقة ماضية للزوجة -حكم بتسليم نفقة ماضية و مستقبلية لالبنة .","document_number":"34194787","case_number":"33226980","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/22","year":"1434","subject":"نفقة -مطالبة مطلقة بنفقة عدتها -مطالبة أم بنفقة ابنتها املاضية واملستقبلية -مطالبة بزيادة نفقة ماضية لعدم كفايتها -املطالبة مبتعة الطاق -حلف اليمن على نية الرجوع بالنفقة -احلكم بتسليم نفقة ماضية للزوجة -حكم بتسليم نفقة ماضية و مستقبلية لالبنة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/22 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34194787 :‬‬\n                    ‫َر ْق ُم الدعوى‪33226980 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34240512‬تاريخه‪1434/6/13 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬مطالبــة مطلقــة بنفقــة عدتهــا ‪ -‬مطالبــة أم بنفقــة ابنتهــا‬\n‫املاضيــة واملســتقبلية ‪ -‬مطالبــة بزيــادة نفقــة ماضيــة لعــدم كفايتهــا‬\n‫‪ -‬املطالبــة مبتعــة الطــاق ‪ -‬حلــف اليمــن علــى نيــة الرجــوع بالنفقــة‬\n‫‪ -‬احلكــم بتســليم نفقــة ماضيــة للزوجــة ‪ -‬حكــم بتســليم نفقــة ماضيــة‬\n                                                    ‫و مســتقبلية لالبنــة ‪.‬‬\n\n\n\n\n‫‪ -1‬قــال شــيخ اإلســام ابــن تيميــة رحمــه اهلل « إذا كان االبــن يف‬\n‫حضانــة امــه فأنفقــت عليــه تنــوي بذلــك الرجــوع علــى األب فلهــا أن‬\n      ‫ترجــع علــى األب يف أظهــر قولــي العلمــاء» الفتــاوى ‪. 134/29‬‬\n‫‪ -2‬جــاء يف املدونــة قــال مالــك ‪ :‬إمنــا خفــف عنــدي يف املتعــة ولــم يجبــر‬\n‫عليهــا املطلــق يف القضــاء يف رأيــي ألنــى أســمع اهلل يقــول «حقــا علــى‬\n                  ‫املتقــن وحقــا علــى احملســنني» « فلذلــك خفــف ولــم ُي ْقـ َ‬\n‫ـض بهــا» املدونــة‬\n                                                             ‫الكبــرى ‪. 332/5‬‬\n‫‪ -3‬وجــاء يف املغنــى (‪« )142-137/10‬اســتحباب املتعــة للمطلقــة‬\n                                 ‫املدخــول بهــا ســواء ســمى لهــا املهــر أم ال»‬\n\n\n\n\n                                                                                     ‫‪264‬‬\n\f      ‫ادعــى املدعــى وكالــة ضــد املدعــى عليــه وكالــة أن املدعيــة أصالــة‬\n      ‫كانــت زوجــة للمدعــى عليــه أصالــة ورزق منهــا ببنــت واحــدة يف حضانــة‬\n      ‫والدتهــا وقــد قــام املدعــى عليــه بتطليــق املدعيــة يف ‪1433/3/21‬ه ـ‬\n      ‫وطالــب املدعــى وكالــة بنفقــة املدعيــة خــال فتــرة عدتهــا ونفقــة‬\n      ‫شــهرية للبنــت وإلــزام املدعــى عليــه بتســليم املدعيــة متعــة الطــاق‪- .‬‬\n      ‫أجــاب املدعــي عليــه وكالــة باملصادقــة علــى الدعــوى ودفــع بــأن موكله‬\n      ‫قــد ســلم املدعيــة نفقــة عدتهــا ألــف وســتمائة ريــال وكان ملتزمــا بنفقــة‬\n      ‫البنــت خمســمائة ريــال شــهري ًا وأمــا متعــة الطــاق فــا يوافــق عليهــا‪،‬‬\n      ‫أقــر املدعــي وكالــة مبــا وصــل موكلتــه مــن نفقــة عدتهــا ونفقــة البنــت‬\n      ‫ولكنــه طالــب بتقديرهــا وحســم الفــرق‪ ،‬مت تقديــر نفقــة املدعيــة وقــت‬\n      ‫عدتهــا بألــف وســتمائة وســتني ريــا ًال ونفقــة البنــت شــهري ًا ســبعمائة‬\n      ‫ريــال عــن طريــق هيئــة النظــر ليكــون الفــرق مبلغــا قــدرة ثالثــة اآلف‬\n      ‫ومائتــا ريــال‪ ،‬قــرر املدعــى عليــه عــدم القناعــة بالقــرار فيمــا يخــص‬\n      ‫نفقــة البنــت ووافــق علــى نفقــة املدعيــة‪ ،‬وقــرر املدعــي وكالــة القناعــة‬\n      ‫بالقــرار‪ ،‬حضــرت املدعيــة أصالــة وقــررت أنهــا كانــت تنفــق علــى‬\n      ‫البنــت بنيــة الرجــوع علــى املدعــى عليــه وطلــب املدعــى عليــه ميينهــا علــى‬\n      ‫ذلــك وحلفــت‪ ،‬قــرر ناظــر القضيــة لألســباب املرصــودة يف نــص القضيــة‬\n      ‫بإلــزام املدعــى عليــه بدفــع ســتة وســتني ريــا ًال للمدعيــة وهــو ميثــل املبلــغ‬\n      ‫املتبقــي مــن نفقتهــا املقــررة وإلزامــه بتســليم املدعيــة مبلغــا قــدره ثالثــة‬\n      ‫اآلف ومائتــا ريــال وهــو مــا ميثــل املبلــغ املتبقــي مــن نفقــة البنــت املاضيــة‬\n      ‫وإلزامــه بدفــع نفقــة مســتقبلية للبنــت مبلغا قدره ســبعمائة ريال شــهرياً‪،‬‬\n\n‫‪265‬‬\n\f‫ورد دعــوى املدعيــة مبطالبتهــا مبتعــة الطــاق‪ ،‬قــررت املدعيــة القناعــة‬\n‫وقــرر املدعــى عليــه عــدم القناعــة‪ .‬صــدر قــرار محكمــة االســتئناف‬\n                                        ‫بالريــاض باملوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة‬\n‫العامــة مبحافظــة اخلــرج وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة باخلــرج ‪ /‬املكلــف برقــم ‪33226980‬‬\n‫وتاريــخ ‪ 1433/03/30‬ه ـ املقيــدة باحملكمــة برقــم ‪33604946‬‬\n‫وتاريــخ ‪ 1433/03/30‬ه ـ ويف يــوم األحــد املوافــق‪ 1434/01/11‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 11 : 00‬وفيهــا حضــر ‪ .......‬ســعودي اجلنســية‬\n‫ا عــن املدعيــة ‪.......‬‬\n                       ‫مبوجــب الســجل املدنــي رقــم ‪ .......‬بصفتــه وكي ـ ً‬\n‫ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .......‬مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة عــدل محافظــة اخلــرج برقــم ‪ 33286745‬وتاريــخ‬\n‫‪1433/6/8‬ه ـ املخــول لــه حــق املطالبــة واملداعــاة واملخاصمــة وســماع‬\n‫الدعــاوي واإلقــرار واإلنــكار والصلــح والتنــازل واإلســتالم والتســليم‪..‬‬\n‫إلــخ وادعــى علــى احلاضــر معــه ســعودي اجلنســية مبوجــب الســجل‬\n‫ا عــن ســعودي اجلنســية مبوجــب الســجل‬       ‫املدنــي رقــم بصفتــه وكي ـ ً‬\n‫املدنــي مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الدلــم برقــم‬\n‫‪ 3481‬وتاريــخ ‪1433/5/26‬ه ـ املجلــد (‪ )3/2716‬املخــول لــه فيهــا حــق‬\n‫املطالبــة واملرافعــة واملدافعــة واملخاصمــة واإلقــرار واإلنــكار والصلــح‬\n‫ا يف دعــواه ‪ :‬بــأن مــوكل املدعــى عليــه‬   ‫واإلســتالم والتســليم‪..‬إلخ قائ ـ ً‬\n‫كان زوج ـ ًا ملوكلتــي مبوجــب عقــد نــكاح صحيــح وقــد أجنبــت لــه‬\n                                                                                    ‫‪266‬‬\n\f      ‫موكلتــي بنتـ ًا عمرهــا اآلن ســنة وثالثــة أشــهر تقريبـ ًا اســمها‪ ...‬وقــد قــام‬\n      ‫مــوكل املدعــى عليــه بتطليــق موكلتــي يف ‪1433/3/21‬ه ـ مبوجــب‬\n      ‫الصــك الصــادر مــن محكمــة ‪ ...‬برقــم ‪ 3/33‬يف ‪1433/3/26‬ه ـ‬\n      ‫علمـ ًا بــأن ابنــة موكلتــي يف حضانتهــا لــذا فإننــي أطلــب إلــزام مــوكل‬\n      ‫املدعــى عليــه بدفــع نفقــة شــهرية البنتــه كمــا أطلــب إلزامــه بدفــع نفقــة‬\n      ‫موكلتــي خــال فتــرة عدتهــا كمــا أطلــب إلزامــه بدفــع متعــة الطــاق‬\n      ‫هــذه دعــواي وبســؤال املدعــى عليــه وكالــة أجــاب بقولــه ‪ :‬مــا ذكــره‬\n      ‫املدعــي وكالــة مــن أن موكلتــه كانــت زوجــة ملوكلــي مبوجــب عقــد‬\n      ‫نــكاح صحيــح وأنهــا أجنبــت لــه بنت ـ ًا اســمها وعمرهــا ســنة وثالثــة‬\n      ‫أشــهر تقريب ـ ًا فصحيــح وأمــا نفقــة موكلتــه يف فتــرة عدتهــا فقــد قــام‬\n      ‫موكلــي بتحويــل ألــف وســتمائة ريــال ملوكلــة املدعــي وأمــا نفقــة البنــت‬\n      ‫فموكلــي منــذ ســبعة أشــهر وهــو يقــوم بتحويــل خمســمائة ريــال شــهري ًا‬\n      ‫حلســاب موكلــة املدعــي وأمــا متعــة الطــاق فلــن يدفعهــا موكلــي‬\n      ‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــي وكالــة قــال ســأراجع‬\n      ‫موكلتــي وأفيدكــم يف اجللســة القادمــة ويف جلســة أخــرى جــرى ســؤال‬\n      ‫املدعــي وكالــة عمــا ذكــره املدعــى عليــه وكالــة يف اجللســة املاضيــة‬\n      ‫ا ‪ :‬مــا ذكــره املدعــى عليــه مــن أنــه قــام بتحويــل ألــف‬    ‫فأجــاب قائ ـ ً‬\n      ‫وســتمائة ريــال نفقــة ملوكلتــي فصحيــح كمــا أن مــوكل املدعــى عليــه‬\n      ‫قــام بتحويــل أربعــة آالف وســبعمائة ريــال نفقــة البنتــه يف الفتــرة املاضيــة‬\n      ‫لــذا فإننــي أطلــب تقديــر النفقــة ملوكلتــي والبنــة موكلتــي وحســم‬\n      ‫املبلــغ الــذي وصــل ملوكلتــي منــه كمــا أطلــب متعــة الطــاق هكــذا‬\n      ‫قــرر وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال ال مانــع مــن حتديــد‬\n      ‫نفقــة مســتقبلية البنــة موكلــي وأمــا متعــة الطــاق فموكلــي لــن يدفعهــا‬\n\n\n‫‪267‬‬\n\f‫هكــذا قــرر وكنــت قــد كتبــت لهيئــة النظــر لتقديــر النفقــة املاضيــة‬\n‫واملســتقبلية للمدعيــة والبنــة املدعــى عليــه فوردنــا جــواب هيئــة النظــر‬\n‫رقــم ‪ 33/798397‬يف ‪1433/6/25‬ه ـ وجوابهــم رقــم ‪33/286823‬‬\n‫يف ‪1433/8/12‬ه ـ واملتضمــن تقديــر نفقــة املدعيــة بخمســمائة ريــال‬\n‫شــهري ًا للفتــرة مــن ‪1433/3/21‬ه ـ إلــى ‪1433/6/30‬ه ـ وهــي فتــرة عــدة‬\n‫الطــاق ومجمــوع النفقــة يف هــذه املــدة ألــف وســتمائة وســتة وســتون‬\n‫ريــا ًال كمــا مت تقديــر نفقــة البنــت بســبعمائة ريــال شــهري ًا ‪ .‬وبعــرض‬\n‫ذلــك علــى املدعــي وكالــة قنــع بتقديــر هيئــة النظــر كمــا جــرى عــرض‬\n‫ا ‪ :‬أمــا‬‫تقديــر هيئــة النظــر علــى املدعــى عليــه وكالــة فأجــاب قائ ـ ً‬\n‫تقديــر نفقــة املدعيــة فأنــا قانــع بــه وأمــا تقديــر النفقــة للبنــت فأنــا غيــر‬\n‫قانــع بــه وهــو كثيــر وراتــب موكلــي وإلتزاماتــه املاديــة كثيــرة وهيئــة‬\n‫النظــر لــم تقـ ّـدر ذلــك بنــاء علــى االلتزامــات التــي علــى موكلــي وقــد‬\n‫قـ ّـدرت ذلــك بنــاء علــى الراتــب فقــط علمـ ًا بــأن موكلــي قــد تــزوج وعليــه‬\n‫قســط شــهري قــدره ألــف وثالثمائــة وثالثــة وســتون ريــا ًال كمــا أنــه قــد‬\n‫اســتأجر ســكن ًا بعشــرين ألــف ريــال ســنوي ًا كمــا يوجــد عليــه مديونيــة‬\n‫واحــد وأربعــون ألف ـ ًا وخمســمائة ريــال كمــا أن بنــك التســليف يأخــذ‬\n‫منــه قســط ًا قــدره ســبعمائة وخمســن ريــا ًال هكــذا قــرر وبنــاء علــى‬\n‫ذلــك فقــد قــررت إعــادة الكتابــة لهيئــة النظــر لتقديــر نفقــة البنــت بعــد‬\n‫اإلطــاع علــى مــا يذكــره املدعــى عليــه وكالــة ورفعــت اجللســة لذلــك‬\n‫ويف جلســة أخــرى حضــرت املدعيــة أصالــة ســعودية اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم واملعـ ّـرف بهــا مــن قبــل املدعــي وكالــة كمــا حضــر‬\n‫يف هــذه اجللســة املدعــى عليــه ويف هــذه اجللســة جــرى ســؤال املدعيــة هــل‬\n‫كانــت تنــوي الرجــوع علــى املدعــى عليــه أصالــة يف نفقــة الطفلة املاضية‬\n\n\n                                                                                           ‫‪268‬‬\n\f      ‫فأجابــت قائلــة ‪ :‬نعــم كنــت أنــوي الرجــوع علــى املدعــى عليــه يف النفقــة‬\n      ‫هكــذا أجابــت وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال ‪ :‬أطلــب‬\n      ‫ميــن املدعيــة علــى أنهــا كانــت تنــوي الرجــوع علــى موكلــي يف النفقــة‬\n      ‫املاضيــة للطفلــة هكــذا قــرر وبعــرض ذلــك علــى املدعيــة اســتعدت‬\n      ‫بــأداء اليمــن‪ ،‬فجــرى حتذيرهــا مــن مغبــة اليمــن الكاذبــة ‪ ،‬فحلفــت‬\n      ‫قائلــة ‪( :‬واهلل العظيــم إننــي كنــت أنفــق علــى ابنتــي ‪ ...‬ويف نيتــي الرجــوع‬\n      ‫بالنفقــة علــى والدهــا املدعــى عليــه أصالــة واهلل العظيــم ) هكذا حلفت‬\n      ‫ثــم جــرى ســؤال املدعيــة عــن النفقــة املاضيــة التــي قــام بتحويلهــا املدعــى‬\n      ‫عليــه البنتــه (‪ ).....‬فأجابــت قائلــة بأنــه قــام بتحويــل خمســة آالف ومائتــي‬\n      ‫ريــال فقــط الغيــر وأنــا أطلــب الباقــي وقــدره ثالثــة آالف ومائتــي ريــال‬\n      ‫باإلضافــة للنفقــة املســتقبلية الشــهرية للطفلــة هكــذا أجابــت وبعــرض‬\n      ‫ذلــك علــى املدعــى عليــه قــال صحيــح بــأن موكلــي قــام بتحويــل خمســة‬\n      ‫آالف ومائتــي ريــال البنتــه ‪ ...‬ولكــن املتبقــي مــن النفقــة املاضيــة ثمامنائــة‬\n      ‫ريــال فقــط باعتبــار أن النفقــة خمســمائة ريــال شــهري ًا وليســت ســبعمائة‬\n      ‫ريــال شــهري ًا هكــذا قــرر ثــم جــرى اإلطــاع علــى جــواب هيئــة اخلبــراء‬\n      ‫يف احملكمــة رقــم ‪ 34/808920‬وتاريــخ ‪1434/4/7‬ه ـ واملتضمــن‬\n      ‫ـدم‬\n      ‫تقديــر نفقــة الطفلــة مببلــغ ســبعمائة ريــال شــهري ًا فبنــاء علــى مــا تقـ ّ‬\n      ‫ذكــره مــن الدعــوى واإلجابــة وبنــاء علــى مــا ورد يف خطابــات أعضــاء‬\n      ‫هيئــة اخلبــراء املشــار إليهــا آنفـ ًا مــن تقديــر نفقــة املدعيــة أصالــة املاضيــة‬\n      ‫مببلــغ ألــف وســتمائة وســتة وســتون ريــا ًال ومبــا أن املدعــي وكالــة‬\n      ‫واملدعــى عليــه وكالــة قــد اقتنعــا بتقديــر أعضــاء هيئــة اخلبــراء فيمــا‬\n      ‫يتعلــق بالنفقــة املاضيــة للمدعيــة أصالــة ومبــا أن املدعــي وكالــة قــد‬\n      ‫أقــر بتحويــل املدعــى عليــه ملبلــغ ألــف وســتمائة ريــال نفقــة ملوكلتــه وبنــاء‬\n\n\n‫‪269‬‬\n\f‫علــى مــا ورد يف قــرار هيئــة اخلبــراء رقــم ‪ 34/808920‬واملتضمــن تقديــر‬\n‫نفقــة الطفلــة (‪ ).....‬مببلــغ ســبعمائة ريــال شــهري ًا وبنــاء علــى مــا قــرره‬\n‫أهــل العلــم مــن أن الطفــل إذا كان يف حضانــة أمــه فأنفقــت عليــه تنــوي‬\n‫بذلــك الرجــوع علــى األب فلهــا الرجــوع ‪ ،‬قــال شــيخ اإلســام ‪( :‬إذا كان‬\n‫االبــن يف حضانــة أمــه ‪ ،‬فأنفقــت عليــه تنــوي بذلــك الرجــوع علــى األب‬\n‫‪ ،‬فلهــا أن ترجــع علــى األب يف أظهــر قولــي العلمــاء ‪ )..‬الفتــاوى ‪134/29‬‬\n‫‪ ،‬ومبــا أن املدعيــة قــد حلفــت اليمــن املطلوبــة علــى أنهــا كانــت تنفــق‬\n‫علــى الطفلــة بنيــة الرجــوع علــى أبيهــا ‪ ،‬ومبــا أن املدعيــة قــد أقــرت بــأن‬\n‫املدعــى عليــه أصالــة قــد دفــع خمســة آالف ومائتــي ريــال نفقــة البنتــه يف‬\n‫الفتــرة املاضيــة ‪ ،‬ومبــا أن متعــة الطــاق مســتحبة وليســت واجبــة كمــا‬\n‫ذكــر ذلــك أهــل العلــم ‪ ،‬جــاء يف املدونــة ‪ ( :‬قــال مالــك‪ :‬إمنــا خفــف‬\n‫عنــدي يف املتعــة ولــم يجبــر عليهــا املطلــق يف القضــاء يف رأيــي ألنــي‬\n‫أســمع اهلل يقــول ( حقـ ًا علــى املتقــن ) و(حقـ ًا علــى احملســنني ) فلذلــك‬\n‫خففــت‪ ،‬ولــم يقــض بهــا )‪ .‬املدونــة الكبــرى ‪ ، 332/5‬وجــاء يف املغنــي‬\n‫‪( 142-137/10‬اســتحباب املتعــة للمطلقــة املدخــول بهــا ســواء سـ ّـمي‬\n‫لهــا املهــر أم ال ) ولكــون املدعــى عليــه وكالــة قــد رفــض أن يدفــع‬\n‫موكلــه متعــة الطــاق لــكل مــا ســبق فقــد قــررت مــا يلــي ‪ :‬أوال ً ‪ :‬إلــزام‬\n‫مــوكل املدعــى عليــه بدفــع ســتة وســتني ريــا ًال للمدعيــة وهــو مي ّثــل املبلــغ‬\n‫املتبقــي مــن النفقــة املقــررة لهــا مــن قبــل أعضــاء هيئــة اخلبــراء ‪ .‬ثاني ـ ًا ‪:‬‬\n‫إلــزام مــوكل املدعــى عليــه بدفــع ثالثــة آالف ومائتــي ريــال للمدعيــة‬\n‫وهــو مــا مي ّثــل امللــغ املتبقــي مــن النفقــة املاضيــة للطفلــة (‪ . ).....‬ثالث ـ ًا ‪:‬‬\n‫إلــزام مــوكل املدعــى عليــه بدفــع نفقــة مســتقبلية البنتــه ‪ ...‬وقدرهــا‬\n‫ســبعمائة ريــال شــهري ًا ‪ .‬رابع ـ ًا ‪ :‬رد دعــوى املدعيــة فيمــا يتعلــق بطلبهــا‬\n\n\n                                                                                               ‫‪270‬‬\n\f      ‫متعــة الطــاق وأخليــت ســبيل املدعــى عليــه أصالــة جتــاه هــذه املطالبــة ‪.‬‬\n      ‫ومبــا ســبق حكمــت وبعــرض احلكــم علــى الطرفــن قنعــت املدعيــة ولــم‬\n      ‫يقنــع املدعــى عليــه وكالــة وطلــب االســتئناف فأجيــب لطلبــه وجــرى‬\n      ‫تســليمه نســخة مــن احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن يومــا‬\n      ‫مــن تاريــخ اليــوم وبعدهــا يســقط حقــه يف االســتئناف ويكتســب احلكم‬\n      ‫القطعيــة ففهــم ذلــك ختمــت يف الســاعة العاشــرة وعليــه جــرى التوقيــع‬\n                ‫وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/4/22‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n      ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n      ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫باخلــرج املكلــف برقــم ‪ 33604946‬وتاريــخ ‪1434/5/21‬ه ـ املرفــق بهــا‬\n      ‫الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ ).....( /‬املســجل‬\n      ‫برقــم ‪ 34194787‬وتاريــخ ‪1434/4/22‬ه ـ اخلــاص بدعــوى‪ ).....(/‬ضــد‬\n      ‫‪ ).....(/‬يف قضيــة نفقــة أوالد وقــد تضمــن الصــك حكــم فضيلتــه مبــا‬\n      ‫هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n      ‫االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى احلكــم‪،‬‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪271‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":264,"source_page_end":271,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c9e294b29ef751aa6654ea7056bd351577e3a6807de9b4949b0d0f0652a6bbef","normalized_text_hash":"d4725a0440d61576dca54f5960c56d9f79043674a8f192ed90f5c937012eb077","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p264-34194787"},{"id":"dd000c7c-956a-5004-a002-48c50acfa2d8","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة (زوجة -أوالد -حمل) -املطالبة بالنفقة املاضية واملستقبلية -تطبيق املادة 50من نظام املرافعات الشرعية املتعلقة بفسخ الوكالة أثناء الترافع دون موافقه المحكمة وقبل إباغ الطرف اآلخر -حلف الزوجة اليمن بعدم إنفاق الزوج -احلكم على املدعى عليه بدفع النفقة املاضية واملستقبلية -نفقة احلمل جتب للمطلقه البائن .","document_number":"34199029","case_number":"3386021","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف يف الساعة الواحدة من هذا اليوم األربعاء املوافق 1433/8/14ه عقدت اجللسة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/28","year":"1434","subject":"نفقة -نفقة (زوجة -أوالد -حمل) -املطالبة بالنفقة املاضية واملستقبلية -تطبيق املادة 50من نظام املرافعات الشرعية املتعلقة بفسخ الوكالة أثناء الترافع دون موافقه المحكمة وقبل إباغ الطرف اآلخر -حلف الزوجة اليمن بعدم إنفاق الزوج -احلكم على املدعى عليه بدفع النفقة املاضية واملستقبلية -نفقة احلمل جتب للمطلقه البائن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/28 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34199029 :‬‬\n                     ‫َر ْق ُم الدعوى‪3386021 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34248489‬تاريخه‪1434/6/21 :‬هـ‬\n\n\n\n  ‫نفقــة ‪ -‬نفقــة (زوجــة ‪ -‬أوالد ‪ -‬حمــل) ‪ -‬املطالبــة بالنفقــة املاضيــة‬\n  ‫واملســتقبلية‪ -‬تطبيــق املــادة ‪ 50‬مــن نظــام املرافعــات الشــرعية املتعلقــة‬\n  ‫بفســخ الوكالــة أثنــاء الترافــع دون موافقــه احملكمــة وقبــل إبــاغ‬\n  ‫الطــرف اآلخــر‪ -‬حلــف الزوجــة اليمــن بعــدم إنفــاق الــزوج ‪ -‬احلكــم‬\n  ‫علــى املدعــى عليــه بدفــع النفقــة املاضيــة واملســتقبلية ‪ -‬نفقــة احلمــل‬\n                                                    ‫جتــب للمطلقــه البائــن ‪.‬‬\n\n\n\n\n ‫‪ -1‬قولــه تعالــى ( وإن كــن أوالت حمــل فأنفقــوا عليهــن حتــى يضعــن‬\n                                                              ‫حملهــن)‪.‬‬\n                              ‫‪ -2‬قوله تعالى ( لينفق ذو سعه من سعته )‪.‬‬\n         ‫‪ -3‬قوله تعالى ( وعلى املولود له رزقهن وكسوتهن باملعروف)‪.‬‬\n        ‫‪-4‬الالئحة األولى من املادة (‪ )50‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n  ‫ادعــى وكيــل املدعيــة بــأن املدعــى عليــه أصالــة كان زوجــا ملوكلتــه‬\n  ‫ومت فســخ نكاحهــا منــه وأجنبــت منــه ثالثــة أبنــاء األول عمــره خمســة‬\n  ‫أعــوام والثانــي عمــره ثالثــة أعــوام والثالــث عمــره ثالثــة أشــهر‪ -‬طلــب‬\n  ‫املدعــي وكالــة إلــزام املدعــى عليــه أصالــة بدفــع نفقــة موكلتــه‬\n                                                                                    ‫‪272‬‬\n\f      ‫املاضيــة حتــى تاريــخ فســخ النــكاح ‪ -‬ونفقــة األوالد املاضيــة ‪ -‬وأجــرة‬\n      ‫احلمــل‪ -‬ونفقــة األبنــاء الثالثــة املســتقبلية‪ -‬قــرر املدعــى عليــه وكالــة‬\n      ‫ا عنــه‪ -‬بنــاء علــى‬  ‫بأنــه فســخ وكالتــه عــن موكلــه ولــم يعــد وكي ـ ً‬\n      ‫املــادة ‪ 50‬مــن نظــام املرافعــات الشــرعية جــرى ســؤال املدعــي وكالــة‬\n      ‫هــل املدعــى عليــه أصالــة أبلغــه أو أبلــغ موكلتــه بعــزل الوكيــل وقبــول‬\n      ‫انعزالــه وتعيــن أحــد بــدال عنــه وأنــه سيباشــر الدعــوى بنفســه فقــال‬\n      ‫لــم يحصــل شــي مــن ذلــك‪ -‬ألن هــذا االعتــزال مــن الوكيــل مت دون‬\n      ‫موافقــة احملكمــة وقبــل إبــاغ املدعــى فقــد قــرر القاضــي الســير يف‬\n      ‫إجــراءات الدعــوى‪ -‬ورد جــواب مكتــب الصلــح املتضمــن تعــذر الصلــح‬\n      ‫بــن الطرفيــن وتقديــر النفقــة املاضيــة للمدعيــة وأبنائهــا املذكوريــن‬\n      ‫وحتديــد نفقــة مســتقبلية وكذلــك أجــرة احلمــل‪ -‬يف جلســة أخــرى‬\n      ‫حضــرت املدعيــة برفقــة والدهــا ولــم يحضــر املدعــى عليــه وال وكيــل‬\n      ‫عنــه‪ -‬حلفــت املدعيــة اليمــن بعــد تخويفهــا بــاهلل عــز وجــل علــى أن‬\n      ‫املدعــى عليــه لــم ينفــق عليهــا وال علــى أبنائهــا املــدة املاضيــة‪ -‬ورد‬\n      ‫اجلــواب مــرة أخــرى مــن قســم اإلصــاح والتحكيــم املتضمــن أن أجــرة‬\n      ‫احلمــل داخلــة يف نفقــة الزوجــة وليســت مســتقلة‪ -‬بنــاء علــى مــا تقــدم‬\n      ‫مــن الدعــوى وألن مــا قــرره املدعــى عليــه وكالــة غيــر مقبــول بنــاء علــى‬\n      ‫الالئحــة األولــى مــن املــادة ‪ 50‬مــن نظــام املرافعــات الشــرعية ولقولــة‬\n      ‫تعالــى (وإن كــن أوالت حمــل فأنفقــوا عليهــن حتــى يضعــن حملهــن)‬\n      ‫وقولــه تعالــى (لينفــق ذو ســعة مــن ســعته) وقولــه تعالــى (وعلــى املولــود لــه‬\n      ‫رزقهــن وكســوتهن باملعــروف) لــذا صــدر احلكــم بإلــزام املدعــى عليــه‬\n      ‫بدفــع نفقــة املدعيــة وأوالده املاضيــة واملســتقبلة لــأوالد وصــرف النظــر‬\n      ‫عــن طلــب املدعيــة نفقــة حملهــا لدخولهــا يف تقديــر النفقــة املاضيــة وألن‬\n\n\n‫‪273‬‬\n\f‫نفقــة احلامــل جتــب للمطلقــه البائــن ‪ -‬قنعــت املدعيــة باحلكــم‪ -‬قــرر‬\n‫القاضــي تزويــد املدعــى عليــه بنســخة مــن احلكــم لتقــدمي اعتراضــه‪-‬‬\n                            ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n‫‪ ...‬القاضــي باحملكمــة العامــة بالطائــف يف الســاعة الواحــدة مــن هــذا‬\n‫اليــوم األربعــاء املوافــق ‪1433/8/14‬ه ـ عقــدت اجللســة للنظــر يف دعــوى‬\n‫‪ ...‬ضــد ‪ ...‬بطلــب نفقــة املقيــدة برقــم ‪ 33226351‬يف ‪1433/2/3‬ه ـ‬\n‫واحملالــة لنــا مــن فضيلــة الرئيــس برقــم ‪ 3386021‬يف ‪1433/2/3‬ه ـ‬\n‫ويف هــذه اجللســة حضــر ‪ ...‬مصــري اجلنســية حســب رخصــة اإلقامــة‬\n‫ا عــن ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬      ‫رقــم ‪ ...‬بصفتــه وكيـ ً‬\n‫العــدل الثانيــة بالطائــف برقــم‪ 3142‬يف ‪1433/1/15‬ه ـ والتــي تخولــه‬\n‫إقامــة الدعــوى ضــد املدعــى عليــه واملطالبــة بالطــاق واحلضانــة والنفقــة‬\n‫واملرافعــة واملدافعــة وحضــور اجللســات واإلقــرار والصلــح والتنــازل‬\n‫وادعــى علــى احلاضــر معــه ‪...‬مصــري اجلنســية حســب رخصــة اإلقامــة‬\n‫رقــم ‪...‬بصفتــه وكيــا عــن ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫العــدل الثانيــة بالطائــف برقــم ‪ 57505‬يف ‪1432/11/19‬ه ـ والتــي‬\n‫تخولــه إقامــة وســماع عمــوم الدعــاوي واملطالبــات واملدافعــة واملرافعــة‬\n‫واإلقــرار واإلنــكار والصلــح والتنــازل واالســتالم والتســليم قائــا يف‬\n‫دعــواه إن املدعــى عليــه أصالــة ‪...‬كان زوج ـ ًا ملوكلتــي مبوجــب عقــد‬\n‫نــكاح صحيــح حســب وثيقــة عقــد النــكاح رقــم‪ ...‬يف ‪1427/6/8‬ه ـ‬\n‫الصــادر مــن هــذه احملكمــة وذلــك علــى مهــر قــدره أربعــة عشــر ألــف‬\n\n                                                                                     ‫‪274‬‬\n\f      ‫ريــال أربعــة آالف منهــا مســلمة مقدم ـ ًا والباقــي مؤخــر وقــد دخــل بهــا‬\n      ‫ومت فســخ نكاحهــا منــه اليــوم بعــد أن أجنبــت منــه علــى فــراش الزوجيــة‬\n      ‫ثالثــة أوالد ‪...‬وعمــره خمســة أعــوام و‪...‬وعمــره ثالثــة أعــوام ونصــف‬\n      ‫و‪...‬وعمــره ثالثــة أشــهر ومنــذ ‪1432/5/1‬ه ـ لــم ينفــق علــى موكلتــي‬\n      ‫ا ب‪...‬ووضعتــه يف‬     ‫وال علــى ولديهــا ‪...‬و‪...‬وكانــت يف هــذا التاريــخ حام ـ ً‬\n      ‫‪1433/1/30‬ه ـ لــذا أطلــب ســؤال املدعــى عليــه وكالــة وإلزامــه بدفــع‬\n      ‫نفقــة موكلتــي مــن تاريــخ ‪1432/5/1‬ه ـ وحتــى تاريــخ اليــوم وكذلــك‬\n      ‫نفقــة ولديهــا ‪...‬و‪ ...‬هــذه املــدة وأجــرة حملهــا ب‪...‬مــن ‪1432/5/1‬ه ـ‬\n      ‫وحتــى وضعــه يف ‪1433/1/30‬ه ـ ونفقتــه مــن ‪1433/2/1‬ه ـ وحتــى‬\n      ‫اآلن ونفقــة أوالدهــا الثالثــة املســتقبلية هــذه دعــواي وبعرضهــا علــى‬\n      ‫املدعــى عليــه وكالــة قــال بأننــي فســخت وكالتــي عــن موكلــي ‪...‬‬\n      ‫فلســت وكيــا عنــه هكــذا قــرر وبنــاء علــى املــادة (‪ )50‬مــن نظــام‬\n      ‫املرافعــات ســألت املدعــي وكالــة هــل املدعــى عليــه أصالــة أبلغــك أو‬\n      ‫أبلــغ موكلتــك بعــزل الوكيــل أو قبــول انعزالــه وتعيــن أحــد بــد ًال عنــه‬\n      ‫أو أنــه سيباشــر الدعــوى بنفســه فقــال لــم يحصــل شــيء مــن ذلــك وألن‬\n      ‫هــذا األعتــزال مــن الوكيــل مت بــدون موافقــة احملكمــة وقبــل إبــاغ‬\n      ‫املدعــي فقــد قــررت الســير يف إجــراءات الدعــوى وفقـ ًا للمــادة املذكورة‬\n      ‫والئحتهــا األولــى والنتهــاء وقــت اجللســة رفعــت ثــم عقــدت اجللســة وفيهــا‬\n      ‫حضــر املدعــي وكالــة ‪...‬ولــم يحضــر املدعــى عليــه وال مــن ينــوب عنــه‬\n      ‫ولــم يــرد إلينــا مايفيــد إعتــذاره عــن حضــور هــذه اجللســة وقــد ســبقت‬\n      ‫الكتابــة ملكتــب الصلــح حملاولــة الصلــح أو تقديــر النفقــة فعــادت‬\n      ‫ومعهــا قــرار املكتــب رقــم ‪/260‬ص يف ‪1433/6/18‬ه ـ واملتضمــن‬\n      ‫( ففــي هــذا اليــوم الســبت ‪1433/5/29‬ه ـ حضــرت املدعيــة ‪...‬حتمــل‬\n\n\n‫‪275‬‬\n\f‫رخصــة إقامــة رقــم ‪...‬وحضــر حلضورهــا املدعــى عليــه ‪...‬يحمــل رخصــة‬\n‫إقامــة رقــم ‪...‬ومبحاولــة الصلــح بــن الطرفــن وتقريــب وجهــات النظــر‬\n‫بــن الطرفــن تعــذر الصلــح حيــث اســتعد الــزوج بدفــع نفقــة وقدرهــا‬\n‫ســتمائة ريــال وقــد أفــاد أمــام اللجنــة أنــه يعمــل يف شــركة ‪...‬مشــرف‬\n‫علــى املقاصــف باملــدارس براتــب ثمامنائــة ريــال وادعــت املدعيــة أنــه يعمل‬\n‫يف محــل ‪ ...‬بأســواق ‪...‬حيــث مكثــت املعاملــة لدينــا إلــى هــذا اليــوم‬\n‫األربعــاء ‪1433/6/18‬ه ـ لالستفســار عــن عمــل املدعــى عليــه ولكــن‬\n‫دون جــدوى ‪ .‬عليــه تــرى اللجنــة أن تكــون النفقــة املاضيــة للمدعيــة‬\n‫أربعمائــة ريــال وأمــا النفقــة املاضيــة واملســتقبليه لألبنــاء مائتــن ريــال‬\n‫لــكل ابــن عــن كل شــهر أمــا أجــرة احلمــل ســتمائة ريــال وإذا ثبــت انــه‬\n‫يتقاضــى راتــب ينظــر يف النفقــة مــرة أخــرى) أ‪.‬ه ـ وبعرضــه علــى املدعــي‬\n‫وكالــة قــرر موافقتــه عليــه ثــم عقــدت اجللســة وفيهــا حضــرت املدعيــة‬\n‫أصالــة ‪...‬مصريــة اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪...‬املعــرف بهــا‬\n‫مــن قبــل والدهــا ووكيلهــا احلاضــر ‪...‬ولــم يحضــر املدعــى عليــه وال مــن‬\n‫ينــوب عنــه وقالــت املدعيــة بــأن املدعــى عليــه لــم ينفــق علــي مــن شــهر‬\n‫جمــادى الثانيــة عــام ‪1432‬ه ـ حتــى مت فســخ نكاحــي يف شــهر شــعبان‬\n‫عــام ‪1433‬ه ـ مــدة أربعــة عشــر شــهرا وإجمالــي نفقتــي لهــذه املدة حســب‬\n‫تقديــر مكتــب الصلــح خمســة آالف وســتمائة ريــال كمــا أنــه لــم ينفــق‬\n‫علــى ولــدي منــه ‪...‬و‪...‬مــدة خمســة عشــر شــهرا مــن شــهر جمــادى الثانيــة‬\n‫عــام ‪1432‬ه ـ حتــى اآلن وقــد قــدرت نفقة كل واحــد منهما مبائتي ريال‬\n‫وإجمالــي نفقتهمــا لهــذه املــدة ســتة آالف كمــا أنــه لــم يدفــع لــي أجــرة‬\n‫حملــي بــ‪...‬مــدة ثمانيــة أشــهر مــن شــهر جمــادى الثانيــة عــام ‪1432‬هـ وقد‬\n‫قــدرت بســتمائة ريــال شــهريا وإجمالــي ذلــك أربعــة آالف وثمامنائــة ريــال‬\n\n\n                                                                                     ‫‪276‬‬\n\f      ‫وال نفقتــه بعــد وضعــه مــدة ســبعة أشــهر مــن تاريــخ وضعــه حتــى اآلن وقــد‬\n      ‫قــدرت مبائتــي ريــال وإجمالــي نفقتــه لهــذه املــدة ألــف وأربعمائــة ريــال‬\n      ‫كمــا أطالــب بإلزامــه بدفــع نفقــة أوالده الثالثــة املســتقبله وإجمالــي‬\n      ‫نفقتهــم الشــهرية حســب التقديــر ســتمائة ريــال فســألتها هــل كانــت يف‬\n      ‫فتــرة حملهــا التــي تطالــب بأجرتهــا يف ذمــة املدعــى عليــه وهــل طالبــت‬\n      ‫بنفقتهــا خــال هــذه الفتــرة فقالــت نعــم كنــت يف ذمتــه وطالبــت بنفقتــي‬\n      ‫لهــذه املــدة فأفهمتهــا بــأن عليهــا اليمــن علــى أن املدعــى عليــه لــم ينفــق‬\n      ‫عليهــا وال علــى أبنائهــا منــه مــن شــهر جمــادى الثانيــة عــام ‪1432‬ه ـ‬\n      ‫وحتــى اآلن فاســتعدت بذلــك فأذنــت لهــا بعــد وعضهــا فحلفــت قائلــة‬\n      ‫واهلل العظيــم أن املدعــى عليــه ‪...‬لــم ينفــق علــي وال علــى أبنائــي منــه ‪...‬و‪...‬‬\n      ‫و‪...‬مــن شــهر جمــادى الثانيــة عــام ‪1432‬ه ـ وحتــى اآلن ســوى أربعمائــة‬\n      ‫ريــال هكــذا حلفــت ونظــرا ألن قــرار مكتــب الصلــح املــدون ســابقا لــم‬\n      ‫يوضــح فيــه هــل أجــرة احلمــل احملــددة شــهرية أم أنهــا لكامــل املــدة وهــل‬\n      ‫تدخــل فيهــا نفقــة الزوجــة أم هــي مســتقلة عــن ذلــك وللتحقــق مــن ذلــك‬\n      ‫رفعــت اجللســة ثــم عقــدت اجللســة وفيهــا حضــر املدعــي وكالــة ‪...‬ولــم‬\n      ‫يحضــر املدعــى عليــه ‪...‬ولــم يــرد مــا يفيــد تبلغــه مبوعــد هــذه اجللســة وقــد‬\n      ‫ورد إلينــا خطــاب رئيــس قســم اإلصــاح والتحكيــم رقــم ‪33226351‬‬\n      ‫يف ‪1433/9/23‬ه ـ ويتضمــن ‪( :‬أجــرة احلمــل احملــددة كل شــهر وليســت‬\n      ‫كامــل املــدة وأنهــا داخلــة يف نفقــة الزوجــة وليســت مســتقلة)أهـ وبســؤال‬\n      ‫املدعــي وكالــة هــل لديــه إضافــة قــال ليــس لــدي إضافــة فبنــاء علــى‬\n      ‫ماتقــدم مــن الدعــوى ونظــر ًا إلــى أن مــا قــرره املدعــى عليــه وكالــة غيــر‬\n      ‫مقبــول ملــا ورد يف املــادة (‪ )50‬والئحتهــا األولــى مــن نظــام املرافعــات وملــا‬\n      ‫ورد يف قــرار مكتــب الصلــح املتضمــن تقديــر النفقــة وملوافقــة املدعــي‬\n\n\n‫‪277‬‬\n\f‫وكالــة عليــه وحللــف املدعيــة أصالــة علــى أن املدعــى عليــه لــم ينفــق‬\n‫عليهــا وال علــى أوالدهــا وألن نفقــة احلامــل جتــب للمطلقــة البائــن ملفهــوم‬\n‫ول ِت َح ْمـ ٍـل َف َأ ْنفِ ُقــوا َع َل ْي ِهـ َّـن َح َّتــى َي َض ْعـ َـن‬      ‫كـ َّـن ُأ َ‬‫قولــه ســبحانه { َو ِإنْ ُ‬\n‫َح ْم َل ُهـ َّـن } واملدعيــة أقــرت بــأن فتــرة حملهــا التــي تطلــب بنفقتهــا كانــت‬\n‫يف ذمــة املدعــى عليــه لهــذا ولقولــه ســبحانه { ل ُِي ْنفِ ـ ْـق ُذو َسـ َـع ٍة مِ ــنْ َسـ َـع ِتهِ}‬\n‫ـروف ِ} فقــد‬ ‫هن ِبامل َْعـ ِ‬     ‫ك ْسـ َـو ُت َّ‬    ‫املولــو ِد َل ـ ُه ِر ْزقُ هـ َّـن َو ِ‬\n                                                                                         ‫{وع َلــى ْ‬   ‫وقولــه عزوجــل َ‬\n‫قــررت مايلــي ‪ :‬أوالً‪ :‬إلــزام املدعــى عليــه ‪...‬بدفــع خمســة آالف وســتمائة‬\n‫ريــال نفقــة املدعيــة مــدة أربعــة عشــر شــهر ًا مــن شــهر جمــادى الثانيــة‬\n‫عــام ‪1432‬هــ‪ .‬ثاني ـ ًا ‪ :‬إلــزام املدعــى عليــه ‪...‬بدفــع ثالثــة آالف وســتمائة‬\n‫ريــال نفقــة ولديــه مــن املدعيــة ‪...‬و‪ ...‬مــن تاريــخ ‪1432/5/1‬ه ـ حتــى‬\n‫‪1433/1/30‬ه ـ ‪ .‬ثالث ـ ًا ‪ :‬إلــزام املدعــى عليــه ‪...‬بدفــع تســعة آالف ريــال‬\n‫نفقــة أوالده مــن املدعيــة ‪...‬و‪ ...‬و‪ ...‬مــن تاريــخ ‪1433/2/1‬ه ـ وحتــى‬\n‫‪1434/4/30‬ه ـ رابعـاً‪ :‬إلــزام املدعــى عليــه ‪...‬بدفــع ســتمائة ريــال شــهري ًا‬\n‫ابتــداء مــن تاريــخ ‪1434/5/25‬ه ـ نفقــة أوالده مــن املدعيــة‪ .‬خامس ـ ًا‬\n‫‪ :‬صــرف النظــر عــن طلــب املدعيــة أصالــة نفقــة حملهــا ملــا ذكــر يف‬\n‫أســباب احلكــم وبذلــك كلــه حكمــت وبعرضــه علــى املدعــي وكالــة‬\n‫قنــع بــه وســيتم إبــاغ املدعــى عليــه بنســخة منــه لتقــدمي مــا لديــه خــال‬\n‫ثالثــن يوم ـ ًا مــن تاريــخ اســتالمه لهــا وإذا مضــت املــدة بعــد االســتالم‬\n‫ولــم يتقــدم مبــا لديــه فيســقط حقــه يف االعتــراض ويكتســب احلكــم‬\n‫الصفــة القطعيــة وبــاهلل التوفيــق حــرر يف ‪1434/4/24‬ه ـ وصلــى اهلل‬\n                                ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مبكــة املكرمــة بخطــاب فضيلــة رئيســها رقــم ‪ 33226351‬يف‬\n\n\n                                                                                                                            ‫‪278‬‬\n\f      ‫‪1434/6/28‬ه ـ احملــال لنــا بشــرح فضيلــة الرئيــس رقــم ‪33226351‬‬\n      ‫يف ‪1434/7/4‬ه ـ ومعهــا قــرار الدائــرة الثانيــة لألحــوال الشــخصية رقــم‬\n      ‫‪ 34248489‬يف ‪1434/6/21‬ه ـ وقــد ظهــر القــرار مبــا نصــه (تظهيــرات‬\n      ‫الدائــرة الثانيــة لألحــوال واألوقــاف والوصايــا والقصــار وبيــوت املــال‬\n      ‫مبحكمــة االســتئناف مبكــة املكرمــة احلمــدهلل وحــده وبعــد فقــد‬\n      ‫اطلعنــا علــى هــذا الصــك رقــم ‪ 34199029‬وتاريــخ ‪1434/4/28‬ه ـ‬\n      ‫الصــادر مــن فضيلــة الشــيخ ‪...‬وأصدرنــا القــرار رقــم ‪ 34248489‬وتاريــخ‬\n      ‫‪1434/6/21‬ه ـ املتضمــن املوافقــة علــى احلكــم عضــو ‪...‬توقيعــه وختمــه‬\n      ‫عضــو د‪... .‬توقيعــه وختمــه رئيــس الدائــرة ‪...‬توقيعــه وختمــه) أ‪.‬ه ـ لــذا‬\n      ‫جــرى إحلاقــه وبــاهلل التوفيــق حــرر يف ‪1434/7/8‬ه ـ وصلــى اهلل وســلم‬\n                                ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n      ‫احلمــد هلل والصــاة والســام علــى مــن ال نبي بعــده ‪ ،‬وبعد فقد جرى منا‬\n      ‫نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا‬\n      ‫والقصــار وبيــوت املــال مبحكمــة االســتئناف يف منطقــة مكــة‬\n      ‫املكرمــة االطــاع علــى الصــك الصــادر مــن فضيلــة الشــيخ‪... /‬القاضــي‬\n      ‫باحملكمــة العامــة بالطائــف برقــم ‪ 34199029‬وتاريــخ‪ 1434/4/28‬ه ـ‬\n      ‫املتضمــن دعــوى‪ ... /‬ضــد‪... /‬يف نفقــة وبدراســة الصــك وصــورة ضبطــه‬\n      ‫تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                         ‫وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪279‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":272,"source_page_end":279,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"72000e4ad83e40870693fc9272cee22c6d9a6faef412c6a71b28bfd35c0dc4f7","normalized_text_hash":"2963d5bb2e8968130130d55e92355fc61cd0fba82ec30684c6fe7106ff319770","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p272-34199029"},{"id":"52f116b8-d3e6-5f5c-a692-1427f38af51b","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقه -نفقة األم املاضية و املستقبلية -تقدير النفقة عن طريق قسم اخلبراء -إلزام األوالد بالنفقة -إلزامهم بإحضار خادمة وسائق لوالدتهم.","document_number":"34209196","case_number":"3313659","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/7","year":"1434","subject":"نفقه -نفقة األم املاضية و املستقبلية -تقدير النفقة عن طريق قسم اخلبراء -إلزام األوالد بالنفقة -إلزامهم بإحضار خادمة وسائق لوالدتهم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/5/7 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34209196 :‬‬\n                    ‫َر ْق ُم الدعوى‪3313659 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 34362541‬تاريخه‪1434/11/19 :‬هـ‬\n\n\n\n‫نفقــه ‪ -‬نفقــة األم املاضيــة و املســتقبلية ‪ -‬تقديــر النفقــة عــن طريــق‬\n‫قســم اخلبــراء ‪ -‬إلــزام األوالد بالنفقــة ‪ -‬إلزامهــم بإحضــار خادمــة‬\n                                                     ‫وســائق لوالدتهــم‪.‬‬\n\n\n\n\n                                        ‫‪ -1‬قوله تعالى « وبالوالدين إحساناً»‬\n                              ‫‪ -2‬قوله صلى اهلل عليه وسلم « أمك وأباك»‬\n‫‪ -3‬قــال بــن املنــذر (اجمــع أهــل العلــم إن نفقــة الوالديــن الفقيريــن الذيــن‬\n                             ‫ال كســب لهمــا وال مــال واجبــة يف مــال الولــد)‬\n‫‪ -4‬قــال صاحــب الــروض املربــع ( جتــب النفقــة كاملــة إذا كان املنفــق‬\n‫عليــه ال ميلــك شــيئا أو تتمتهــا إذا كان ال ميلــك البعــض ألبويــه وإن علــوا)‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة (األم) ضــد ابنيهــا موظفــن بطلــب إلزامهمــا بنفقتهــا‬\n‫حيــث أنهــا غيــر متزوجــة ومحتاجــة وقــررت انهمــا ال ينفقــان عليهــا منــذ‬\n‫خمــس ســنوات وطالبــت بالنفقــة املاضيــة وتقديــر نفقــه مســتقبلية ‪ -‬لــم‬\n‫يحضــر املدعــى عليهمــا وتبلــغ احدهمــا ولــم يتبلــغ اآلخــر وقــرر ناظــر‬\n‫القضيــة الســير يف القضيــة ومت إحالــة األوراق ملكتــب الصلــح‪ ،‬مت‬\n\n                                                                                       ‫‪280‬‬\n\f      ‫تقديــر نفقــه لــأم بثالثــة آالف ريــال علــى كل ولــد مــن أوالدهــا الثالثــة‬\n      ‫وتأمــن خادمــة‪ ،‬قــررت األم أن احــد أبنائهــا غيــر موظــف وطالبــت‬\n      ‫إلــزام املدعــى عليهمــا فقــط وإلزامهمــا أيضـ ًا بتأمــن ســائق‪ ،‬قــرر ناظــر‬\n      ‫القضيــة لألســباب املرصــودة إلــزام املدعــى عليهمــا بدفــع نفقــة شــهرية‬\n      ‫لــأم قدرهــا ألف ـ ًا ريــال مناصفــة ال تشــمل إيجــار الســكن وإلزامهمــا‬\n      ‫بإحضــار ســائق وخادمــة لوالدتهمــا واحلكــم يف حــق املدعــى عليــه‬\n      ‫املتبلــغ حضوريـ ًا واألخــر غيابيـاً‪ ،‬مت بعــث نســخه مــن احلكــم للمدعــى‬\n      ‫عليهمــا حســب املتبــع‪ ،‬صــدر قــرار محكمــة االســتئناف مبنطقــة مكــة‬\n                                                ‫املكرمــة باملوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالطائــف برقــم ‪ 33131659‬وتاريــخ ‪ 1433/02/21‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 3333322‬وتاريــخ ‪ 1433/01/04‬ه ـ يف يــوم األحــد‬\n      ‫املوافــق‪ 1433/06/22‬ه ـ وفيهــا حضــرت ســعودية اجلنســية مبوجــب‬\n      ‫ســجلها املدنــي رقــم وأمــا املدعــى عليهــم فلــم يحضــروا ولــم يردنــا مــا‬\n      ‫يفيــد بتبليغهــم باحلضــور مــن عدمــه لــذا قــررت رفــع اجللســة وتأجيلهــا‬\n      ‫ويف جلســة أخــرى يف يــوم األحــد املوافــق‪ 1433/08/11‬ه ـ حضــرت‬\n      ‫املدعيــة واملعــرف بهــا مــن قبــل مشــرفة التفتيــش باحملكمة وأمــا املدعى‬\n      ‫عليــه فلــم يحضــر وقــد وردتنــا إفــادة قســم احملضريــن باحملكمــة برقــم‬\n      ‫‪ 33934070‬يف ‪1433/05/17‬ه ـ واملتضمــن أن املدعــى عليــه قــد تبلــغ‬\n      ‫لشــخصه لــذا قــررت ســماع دعــوى املدعيــة فادعــت قائلــة يف دعواهــا‬\n‫‪281‬‬\n\f‫إن املدعــى عليهــم أبنائــي وهــم موظفــون وال ينفقــون علــي منــذ مــا‬\n‫يقــارب خمــس ســنوات وأنــا غيــر متزوجــة وال أملــك مــن حطــام الدنيــا‬\n‫إال اليســير أطلــب احلكــم علــى املدعــى عليــه وكذلــك إبنــي ‪ ...‬بدفــع‬\n‫نفقتــي املاضيــة والتعهــد بدفــع نفقتــي املســتقبلية هــذه دعــواي عليــه‬\n‫قــررت إدخــال ‪...‬و‪...‬و‪ ...‬أبنــاء يف الدعــوى وتبليغهــم باحلضــور كاملتبــع‬\n                        ‫وحتــى يحصــل ذلــك جــرى رفــع اجللســة وتأجيلهــا‪.‬‬\n‫احلمــد هلل وحــده وبعــد لــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف ففــي يــوم األربعــاء املوافــق‪ 1433/10/11‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 09 : 00‬ثــم مضــى الوقــت احملــدد لهــا ولــم حتضــر املدعيــة‬\n‫وال مــن ينــوب عنهــا ولــم تقــدم عــذرا يفيــد عــن ســبب تخلفهــا عــن‬\n‫احلضــور لذلــك كلــه واســتنادا علــى تعليمــات نظــام املرافعــات وألن‬\n‫مــن تــرك دعــواه تــرك لــذا فقــد قــررت شــطب القضيــة للمــرة األولــى‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n‫وســلم ‪ .‬حــرر يف ‪ 1433/10/11‬ه ـ ‪ .‬ويف جلســة أخــرى يف يــوم الثالثــاء‬\n‫املوافــق‪ 1433/11/30‬ه ـ وبنــاء علــى االســتدعاء احملــال إلينــا بشــرح‬\n‫فضيلــة رئيــس احملكمة برقــم ‪ 331812964‬يف تاريخ ‪1433/10/15‬هـ‬\n‫واملتضمــن طلــب املدعيــة إعــادة املعاملــة مــن األرشــيف ومواصلــة نظــر‬\n‫القضيــة وأمــا املدعــى عليهــم فلــم يحضــروا وقــد ســبق أن وردتنــا‬\n‫إفــادة قســم احملضريــن برقــم ‪ 33934070‬يف تاريــخ ‪1433/05/22‬ه ـ‬\n‫واملتضمنــة أنــه تبلــغ لشــخصه وإفــادة أخــرى برقــم ‪ 331627704‬يف‬\n‫تاريــخ ‪1433/08/28‬ه ـ واملتضمنــة تعــذر تبليــغ املدعــى عليــه بســبب‬\n‫متتعــه باإلجــازة الصيفيــة ثــم جــرى ســؤال املدعيــة هــل لديــك بينــة علــى‬\n‫دعــواك فقالــت ليــس لــدي بينــة علــى دعــواي هكــذا قــررت عليــه قــررت‬\n\n\n                                                                                    ‫‪282‬‬\n\f      ‫إحالــة املدعيــة إلــى قســم الصلــح إلكمــال الــازم حيــال هــذه الدعــوى‬\n      ‫ويف جلســة أخــرى يف يــوم األربعــاء املوافــق‪ 1434/01/21‬ه ـ وقــد ســبق‬\n      ‫وأن أحيلــت كامــل أوراق املعاملــة إلــى مكتــب الصلــح ولــم تردنــا حتــى‬\n      ‫تاريخــه لــذا فقــد قــررت رفــع اجللســة حتــى ورود اجلــواب مــن القســم‬\n      ‫املذكــور‪ .‬ويف جلســة أخــرى يف يــوم األحــد املوافق‪1434/05/05‬ه ـ‬\n      ‫حضر ت املدعية وأما املدعى عليهم فلم يحضروا وقد سبقت الكتابة‬\n      ‫لقســم اإلصــاح والتحكيــم باحملكمــة بخطابنــا رقــم ‪ 331811956‬يف‬\n      ‫‪1434/1/19‬ه ـ فوردنــا خطابهــم رقم ‪ 331811956‬يف ‪1434/1/26‬هـ‬\n      ‫املتضمــن أنــه جــرى إكمــال الــازم علــى ضــوء قــرار أعضــاء جلنــة الصلح‬\n      ‫املرفــق وباالطــاع عليــه وجــد يتضمــن مــا نصــه بعــد املقدمــة (حضــرت‬\n      ‫املدعيــة أصالــة حتمــل الهويــة الوطنيــة رقــم ولــم يحضــر أبناؤهــا ‪...‬و‪...‬‬\n      ‫أبنــاء‪ ...‬وبنــاء علــى توجيــه فضيلــة القاضــي بالنظــر يف الدعــوى دون‬\n      ‫حضــور املدعــى عليهــم وحيــث أفــادت املدعيــة بأنهــا تســكن يف ســكن‬\n      ‫وأبناؤهــا يســددون إيجــار الســكن مبقــدار اثنــن وعشــرين ألــف ريــال‬\n      ‫وأن ابنهــا يعمــل معلــم والثانــي ضابــط يف اجليــش والثالــث ممــرض عليــه‬\n      ‫تــرى اللجنــة والــرأي لفضيلتكــم أن تكــون النفقــة ثالثــة آالف ريــال‬\n      ‫تــوزع علــى كل ابــن مــن أبنائهــا ويكــون مجمــوع النفقــة ثالثــة آالف‬\n      ‫ريــال ال يشــمل إيجــار الســكن وأن يحضــروا لهــا خادمــة ويــوزع دفــع‬\n      ‫راتــب اخلادمــة علــى األبنــاء جميعــا أ ‪ .‬هــ) ثــم جــرى عــرض ذلــك علــى‬\n      ‫املدعيــة فقالــت إن ابنــي غيــر موظــف وليــس لــه مصــدر دخــل وأطلــب أن‬\n      ‫يؤمنــوا لــي ســائق والبنــت تســلمني ألــف ريــال شــهريا وبقيــة مــا ذكــر‬\n      ‫موافقــة عليــه هكــذا قــررت ثــم جــرى ســؤالها هــل لديــك إضافــة علــى‬\n      ‫مــا ســبق فقالــت ليــس لــي إضافــة علــى مــا ســبق هكــذا قــررت فبنــاء‬\n\n\n‫‪283‬‬\n\f‫علــى مــا تقــدم مــن الدعــوى ولقولــه تعالــى ( وبالوالديــن إحســانا ) قــال‬\n‫ابــن املنــذر‪ ( :‬أجمــع أهــل العلــم أن نفقــة الوالديــن الفقيريــن الذيــن ال‬\n‫كســب لهمــا وال مــال واجبــة يف مــال الولــد) ويقــول صاحــب الــروض‬\n‫املربــع ( جتــب النفقــة كاملــة إذا كان املنفــق عليــه ال ميلــك شــيئا أو‬\n‫تتمتهــا إذا كان ال ميلــك البعــض ألبويــه وإن علــوا ) ويف احلديــث ( أمــك‬\n‫وأبــاك) ويف احلديــث الصحيــح ذكــرت األم ثالثــا وينظــر حاشــية ابــن‬\n‫قاســم علــى الــروض ‪ 127/7‬وألن املدعيــة قــررت بــأن ابنهــا ‪ ...‬غيــر‬\n‫موظــف وليــس لــه مصــدر دخــل وأن ابنتهــا تعطيهــا شــهريا ألــف ريــال‬\n‫وألنهــا قــررت قناعتهــا مبــا جــاء يف قــرار قســم اإلصــاح والتحكيــم‬\n‫باحملكمــة برقــم ‪/23‬ص وتاريــخ ‪1434/1/17‬ه ـ فقــد حكمــت علــى‬\n‫املدعــى عليهمــا حكمــا حضوريــا يف حــق األول وغيابيــا يف حــق الثانــي‬\n‫بــأن يدفعــا للمدعيــة شــهريا نفقــة وقدرهــا ألفــي ريــال مناصفــة بينهمــا‬\n‫ال تشــمل إيجــار الســكن الــذي تســكنه كمــا ألزمتهمــا بــأن يحضــرا‬\n‫لوالدتهمــا املدعيــة خادمــة وســائق ويقومــا بدفــع راتبهمــا مناصفــة‬\n‫بينهمــا واملدعــى عليــه الثانــي الغائــب علــى حجتــه متــى حضــر وبإعــان‬\n‫احلكــم علــى املدعيــة قــررت قناعتهــا باحلكــم وســوف يجــري بعــث‬\n‫نســخة مــن الصــك للمدعــى عليهمــا لتقــدمي مــا لديهمــا مــن اعتــراض وأن‬\n‫لهمــا ثالثــن يومــا مــن تاريــخ تبلغهمــا باحلكــم لتقــدمي اعتراضهمــا فــإن‬\n‫لــم يقدمــا اعتراضهمــا خاللهــا ســقط حقهمــا يف االعتــراض واكتســب‬\n‫احلكــم القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                          ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/05‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n\n\n                                                                                    ‫‪284‬‬\n\f      ‫العامــة بالطائــف برقــم ‪ 33131659‬وتاريــخ ‪1433/02/21‬ه ـ املقيــدة‬\n      ‫باحملكمة برقم ‪ 3333322‬وتاريخ ‪ 1433/01/04‬هـ ففي يوم الثالثاء‬\n      ‫املوافق‪1434/09/01‬هـ افتتحت اجللســة الســاعة التاســعة وقد وردتنا‬\n      ‫الالئحــة االعتراضيــة املقدمــة مــن احملالــة لنــا برقــم ‪ 341708401‬يف‬\n      ‫تاريــخ ‪1434/7/16‬ه ـ وباإلطــاع عليهــا لــم أجــد فيهــا مــا يؤثــر علــى‬\n      ‫احلكــم أو يدعــو للعــدول عنــه وقــررت رفع القضية حملكمة االســتئناف‬\n      ‫لتدقيقهــا كاملتبــع كمــا وردنــا خطــاب رئيــس احملكمــة العامــة‬\n      ‫مبنطقــة تبــوك رقــم ‪ 341216753‬يف تاريــخ ‪ 1434/8/7‬ه ـ املتضمــن‬\n      ‫تســلم املدعــى عليــه صــورة احلكــم بتاريــخ ‪ 1434/7/1‬ه ـ وحيــث لــم‬\n      ‫يقــدم الئحــة اعتراضيــة حتــى تاريخــه فقــد ســقط حقــه يف االعتــراض‬\n      ‫واكتســب احلكــم القطعيــة يف حقــه وللبيــان حــرر واختتمــت اجللســة‬\n      ‫الســاعة التاســعة والربــع و بــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/09/01‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف ففــي يــوم اخلميــس املوافــق ‪1434/12/26‬ه ـ افتتحــت اجللســة‬\n      ‫وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف وعليهــا خطــاب رئيســها‬\n      ‫برقــم ‪ 331811956‬يف تاريخ‪1434/12/1‬ه ـ وبداخــل املعاملــة وجــد‬\n      ‫القرار الصادر من دائرة األحوال الشخصية الثانية برقم‪34362541‬يف‬\n      ‫تاريــخ ‪1434/11/19‬ه ـ واملتضمــن املوافقــة علــى احلكــم بعــد اإلجــراء‬\n      ‫األخيــر وعليــه فقــد أكتســب احلكــم الصفــة القطعيــة وبــاهلل التوفيــق‪،‬‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                   ‫‪1434/12/26‬ه ـ ‪.‬‬\n      ‫احلمــد هلل والصــاة والســام علــى مــن ال نبي بعــده ‪ ،‬وبعد فقد جرى منا‬\n\n\n‫‪285‬‬\n\f‫نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصار وبيوت املال مبحكمة االســتئناف يف منطقة مكة املكرمة‬\n‫االطــاع علــى الصــك الصــادر مــن فضيلــة الشــيخ(‪ ).....‬القاضــي‬\n‫باحملكمــة العامــة بالطائــف برقــم ‪ 34209196‬وتاريخ‪1434/5/7‬ه ـ‬\n‫املتضمــن دعــوى ضــد وإخوانــه يف نفقــة وبدراســة الصــك وصــورة ضبطــه‬\n‫تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                   ‫وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪286‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":280,"source_page_end":286,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"13272991d238ae90fa039db6842c698a2e275e3cd79a29da27c135c1122952bb","normalized_text_hash":"38c4f18ab3b03794be7103f862ea00e50d6fd4549062cce8d4eb6c1a1fc33142","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p280-34209196"},{"id":"4de862a4-7edd-585a-a1f3-b9ced6ec43c9","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة زوجة عن املدة املاضية -تقدير النفقة عن طريق قسم اخلبراء -اعتراض الزوج على مقدار النفقة -دفع الزوج بعدم استحقاق الزوجة للنفقة بسبب مرضها بالسحر -احلكم على الزوج بدفع نفقة الزوجة املاضية.","document_number":"34243280","case_number":"3415320","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/17","year":"1434","subject":"نفقة -نفقة زوجة عن املدة املاضية -تقدير النفقة عن طريق قسم اخلبراء -اعتراض الزوج على مقدار النفقة -دفع الزوج بعدم استحقاق الزوجة للنفقة بسبب مرضها بالسحر -احلكم على الزوج بدفع نفقة الزوجة املاضية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/6/17 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34243280 :‬‬\n                          ‫َر ْق ُم الدعوى‪3415320 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                  ‫‪ 34312771‬تاريخه‪1434/9/6 :‬هـ‬\n\n\n\n       ‫نفقــة‪ -‬نفقــة زوجــة عــن املــدة املاضيــة‪ -‬تقديــر النفقــة عــن طريــق‬\n       ‫قســم اخلبــراء‪ -‬اعتــراض الــزوج علــى مقــدار النفقــة‪ -‬دفــع الــزوج بعــدم‬\n       ‫اســتحقاق الزوجــة للنفقــة بســبب مرضهــا بالســحر‪ -‬احلكــم علــى‬\n                                             ‫الــزوج بدفــع نفقــة الزوجــة املاضيــة‪.‬‬\n\n\n\n\n                                       ‫‪ -1‬قوله تعالى ( لينفق ذو سعه من سعته )‬\n                               ‫‪ -2‬قولة تعالى( ولهن مثل الذي عليهن باملعروف )‬\n       ‫‪ -3‬قول النبي صلى اهلل عليه وســلم ( ولهن عليكم رزقهن وكســوتهن‬\n                                                       ‫باملعروف ) رواه مسلم وغيره‬\n       ‫‪ -4‬حديــث عائشــة رضــي اهلل عنهــا أن هنــد بنــت عتبــه قالــت لرســول‬\n       ‫اهلل صلــى اهلل عليــه وســلم إن أبــا ســفيان رجــل شــحيح وليــس يعطينــي‬\n       ‫مــا يكفينــي وولــدي إال مــا أخــذت منــه وهــو ال يعلــم فقــال صلــى اهلل‬\n       ‫عليــه وســلم خــذي مــا يكفيــك وولــدك باملعروف ) رواه البخاري ومســلم‬\n                                                                             ‫وغيرهمــا‬\n       ‫‪ -5‬مــا رواه البخــاري أن النبــي صلــى اهلل عليــه وســلم قضــى أن اليمــن‬\n                                                                  ‫علــى املدعــى عليــه‬\n       ‫‪ -6‬قــول النبــي صلــى اهلل عليــه وســلم‪ ( :‬البينــة علــى املدعــى واليمــن‬\n       ‫علــى املدعــى عليــه ) رواه الترمــذي وقــال العمــل عنــد أهــل العلــم مــن‬\n\n‫‪287‬‬\n\f‫أصحــاب النبــي صلــى اهلل عليــه وســلم وغيرهــم أن البينــة علــى املدعــى‬\n                                               ‫واليمــن علــى املدعــى عليــه ‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة بــأن املدعــى عليــه عقــد عليهــا ودخــل بهــا الدخــول‬\n‫الشــرعي ومكثــت عنــده خمســة عشــر يومـ ًا ولــم تنجــب منــه ثــم أعادهــا‬\n‫لبيــت أهلهــا‪ -‬بعــد ســنه تقريب ـ ًا مــن الدخــول قــام بتطليقهــا‪ -‬طلبــت‬\n‫املدعيــة إلــزام املدعــى عليــه بدفــع نفقتهــا املاضيــة‪ -‬أقــر املدعــى عليــه‬\n‫بالدعــوى ودفــع بــأن ســبب إعادتــه للمدعيــه ألهلهــا وعــدم اإلنفــاق عليهــا‬\n‫وذلــك ألن املدعيــة تعانــي مــن الســحر وعــن حتولــت إلــى مــس وأنهــا‬\n‫ال تســتحق النفقــة كــون املدعيــة وأهلهــا لــم يعلمــوه بذلــك‪ -‬أنكــرت‬\n‫املدعيــة ذلــك‪ -‬قــرر املدعــى عليــه بــأن ال بينــة لديــة وطلــب ميــن املدعيــة‪-‬‬\n‫حلفــت املدعيــة علــى نفــي مــا ذكــره املدعــى عليــه‪ -‬مت تقديــر النفقــة‬\n‫مــن قبــل قســم اخلبــراء‪ -‬ذكــر املدعــى عليــه بــأن النفقــة املقــدرة كثيــرة‬\n‫كونــه غيــر موظــف‪ -‬ذكــرت املدعيــة أن املدعــى عليــه يعمــل أعمــا ًال‬\n‫حــرة وأنــه مت أخــذ ذلــك يف االعتبــار عنــد تقديــر النفقــة‪ -‬صــدر احلكــم‬\n‫بإلــزام املدعــى عليــه بدفــع نفقــة املدعيــة عــن املــدة املذكــورة حســب‬\n‫قــرار هيئــة النظــر‪ -‬اعتــرض املدعــي عليــه علــى احلكــم‪ -‬صــدق احلكــم‬\n                                                      ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                        ‫‪288‬‬\n\f      ‫احلمد هلل وحده وبعد فلدي أنا ‪ ...‬القاضي يف احملكمة العامة مبحافظة‬\n      ‫جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫مبحافظــة جــدة املســاعد برقــم ‪ 3415320‬وتاريــخ ‪1434/01/10‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 3471454‬وتاريــخ ‪1434/01/10‬ه ـ فـفـ ــي‬\n      ‫يــوم السـبــت املـوافـق ‪1434/06/17‬هـ افـتـتـحـت اجلـلـســة الســاعــة ‪: 45‬‬\n      ‫‪ 03‬وفيهــا حضــرت املدعيــة ‪ ...‬ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪ ...‬واملعــرف بهــا مــن قبــل أبيهــا ‪ ...‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ ...‬وادعــت علــى احلاضــر معهــا ‪ ...‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ ...‬قائلــة ‪ :‬إن املدعــى عليــه زوجــي ‪ ،‬عقــد بــي يف‬\n      ‫‪1433/4/22‬ه ـ علــى مهــر قــدره خمســة وثالثــون ألــف ريــال مســتلم‬\n      ‫بالكامــل ‪ ،‬مبوجــب عقــد النــكاح الصــادر مــن احملكمــة اجلزئيــة‬\n      ‫للضمــان واألنكحــة برقــم ‪ 3987‬وتاريــخ ‪1433/4/25‬هــ‪ ،‬ودخــل‬\n      ‫بــي يف ‪1433/6/24‬ه ـ ‪ ،‬ولــم أرزق منــه بــأوالد‪ ،‬ولــم ميكــث املدعــى‬\n      ‫عليــه معــي ســوى خمســة عشــر يوم ـاً‪ ،‬ثــم أعادنــي إلــى بيــت أهلــي دون‬\n      ‫ســبب‪ ،‬ومنــذ ذلــك التاريــخ وأنــا يف بيــت أهلــي ‪ ،‬ولــم ينفــق علــي طيلــة‬\n      ‫تلــك املــدة ‪ ،‬وقــد طلقنــي املدعــى عليــه طلقــة واحــدة هــذا اليــوم الســبت‬\n      ‫املوافــق ‪1434/6/17‬ه ـ مبوجــب الصــك الصــادر مــن هــذه احملكمــة‬\n      ‫برقــم ‪ 34243279‬وتاريــخ ‪1434/6/17‬ه ـ ‪ ،‬أطلــب إلــزام املدعــى عليــه‬\n      ‫بدفــع نفقتــي املاضيــة مــن تاريــخ ‪1433/7/10‬ه ـ وحتــى تاريــخ اليــوم ‪.‬‬\n      ‫هــذه دعــواي‪ ،‬وبعــرض ذلــك علــى املدعــى عليــه قــال ‪ :‬إن مــا ذكرتــه‬\n      ‫املدعيــة مــن العقــد والدخــول وعــدم اإلجنــاب وإعادتــي لهــا بعــد خمســة‬\n\n‫‪289‬‬\n\f‫عشــر يومــا وطالقــي لهــا وعــدم اإلنفــاق فصحيــح ‪ ،‬ولكــن املهــر هــو‬\n‫خمســة وثالثــون ألــف ريــال وطقــم ذهــب وزنــه اثنــن وثالثــن جرامــا‬\n‫وثمنــه ســتة آالف ومائــة ريــال ‪ ،‬وعربيــة ‪ ،‬وعــدم أحقيــة املدعيــة يف‬\n‫النفقــة راجــع إلــى أنهــا تعانــي مــن ســحر مشــروب ‪ ،‬وعــن حتولــت إلــى‬\n‫مــس ‪ ،‬وال تســتحق النفقــة كــون املدعيــة وأهلهــا لــم يعلمونــي بأنهــا‬\n‫تعانــي مــن ذلــك ‪ .‬وبعــرض ذلــك علــى املدعيــة قالــت ‪ :‬مــا ذكــره املدعــى‬\n‫عليــه مــن مــرض ومــس غيــر صحيــح ‪ ،‬وأنــا ال أعانــي مــن شــيء مــن ذلــك‬\n‫‪ .‬وبســؤال املدعــى عليــه البينــة علــى مــا دفــع بــه قــال ‪ :‬أطلــب ميــن املدعيــة‬\n‫علــى أنهــا لــم تخبرنــي بأنهــا مســحورة وأن جدهــا هــو مــن ســحرها وأن‬\n‫ســحرها تناولتــه عــن طريــق الفــم ‪ ،‬وأقبــل بــه ‪ .‬وبعــرض ذلــك علــى‬\n‫املدعيــة اســتعدت لذلــك ‪ ،‬ثــم حلفــت قائلــة ‪ :‬واهلل العظيــم الــذي ال إلــه‬\n‫إال هــو أننــي لــم أخبــر املدعــى عليــه ‪...‬بأننــي مســحورة وأن جــدي هــو‬\n‫مــن ســحرني ‪ ،‬وأن ســحري تناولتــه عــن طريــق الفــم ‪ .‬هكــذا حلفــت ‪.‬‬\n‫وقــد وردتنــا املعاملــة مــن قســم الصلــح بخطــاب رئيســه رقــم ‪3471454‬‬\n‫وتاريــخ ‪1434/6/3‬ه ـ ومرفــق بــه محضــر اللجنــة واملتضمــن (فإنــا نــرى‬\n‫أن يدفــع النفقــة املاضيــة ومقدارهــا ســتة آالف وســتمائة ريــال للمــدة‬\n‫املاضيــة ومقدارهــا أحــد عشــر شــهرا) أه ـ وبعرضــه علــى الطرفــن‬\n‫قــررت املدعيــة موافقتهــا عليــه وقــرر املدعــى عليــه عــدم موافقتــه عليه ‪،‬‬\n‫وقــرر املدعــى عليــه قائــا ‪ :‬إننــي غيــر موظــف وهــذا املبلــغ املقــدر كبيــر‬\n‫جــدا ‪ .‬وبعرضــه علــى املدعيــة قالــت ‪ :‬هــو مقتــدر ‪ ،‬ويعمــل يف التجــارة‬\n‫احلــرة ‪ ،‬ومــا قــدره أهــل اخلبــرة أخــذ يف االعتبــار حــال املدعــى عليــه‬\n‫مــن زعمــه عــدم القــدرة ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫‪ ،‬وبنــاء علــى دفــع املدعــى عليــه عــدم اســتحقاق املدعيــة للنفقــة بحجــة‬\n\n\n                                                                                           ‫‪290‬‬\n\f      ‫املــرض والســحر وانكــرت املدعيــة ذلــك وطلــب املدعــى عليــه ميينهــا‬\n      ‫علــى اإلنــكار وحلفــت ‪ ،‬وبنــاء علــى مــا أقــرره أعضــاء جلنــة الصلــح ‪،‬‬\n      ‫ولقولــه تعالــى (لينفــق ذو ســعة مــن ســعته) ولقولــه تعالــى (ولهــن مثــل‬\n      ‫الــذي عليهــن باملعــروف) ‪ ،‬وحلديــث (ولهــن عليكــم رزقهــن وكســوتهن‬\n      ‫باملعــروف) رواه مســلم وغيــره‪ ،‬وحلديــث عائشــة رضــي اهلل عنهــا ‪ :‬أن‬\n      ‫هنــد بنــت عتبــة قالــت لرســول اهلل صلــى اهلل عليــه وســلم ‪ :‬إن أبــا ســفيان‬\n      ‫رجــل شــحيح ‪ ،‬وليــس يعطينــي مــا يكفينــي وولــدي إال مــا أخــذت منــه‬\n      ‫‪ ،‬وهــو ال يعلــم ‪ ،‬فقــال ‪( :‬خــذي مــا يكفيــك وولــدك باملعــروف) رواه‬\n      ‫البخــاري ومســلم وغيرهمــا ‪ ،‬وحلديــث (أن النبــي صلــى اهلل عليــه وســلم‬\n      ‫قضــى أن اليمــن علــى املدعــى عليــه) رواه البخــاري ‪ ،‬وحلديــث (البينــة‬\n      ‫علــى املدعــي واليمــن علــى املدعــى عليــه) رواه الترمــذي ‪ ،‬قــال أبــو‬\n      ‫عيســى ‪ :‬العمــل عنــد أهــل العلــم مــن أصحــاب النبــي صلــى اهلل عليــه‬\n      ‫وســلم وغيرهــم أن البينــة علــى املدعــي واليمــن علــى املدعــى عليــه ‪،‬‬\n      ‫لذلــك كلــه ‪ ،‬فقــد حكمــت علــى املدعــى عليــه ‪...‬بدفــع مبلــغ قــدره‬\n      ‫ســتة آالف وســتمائة ريــال للمدعيــة ‪ . ...‬وبــه قنعــت املدعيــة وقــرر املدعــى‬\n      ‫عليــه االعتــراض ‪ ،‬وجــرى تســليمه نســخة مــن احلكــم وإفهامــه بــأن‬\n      ‫لــه احلــق يف االعتــراض عليــه خــال ثالثــن يومــا ‪ ،‬وإال ســقط حقــه يف‬\n      ‫االعتــراض ‪ ،‬واكتســب احلكــم القطعيــة ‪ .‬وأقفلــت اجللســة الســاعة‬\n      ‫‪ . 04 : 15‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                       ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/06/17‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة ففــي يــوم األربعــاء املوافق‪1434/10/14‬ه ـ افتتحــت‬\n      ‫اجللسة الساعة ‪ 9 : 15‬وفيها قد عادت املعاملة من محكمة االستئناف‬\n\n\n‫‪291‬‬\n\f‫بخطــاب رئيســها رقــم ‪ 3471454‬وتاريــخ ‪1434/9/10‬ه ـ وبالقــرار رقــم‬\n‫‪ 34312771‬وتاريــخ ‪1434/9/6‬ه ـ ومضمونــه مــا يلي ( وبدراســة الصك‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة ‪ ،‬تقــررت املوافقــة علــى احلكــم ‪.‬‬\n‫وأقفلــت اجللســة الســاعة ‪ 9 : 20‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n            ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/10/14‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة جــده برقــم ‪ 3471454‬وتاريــخ ‪1434/8/25‬ه ـ املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪...‬القاضــي باحملكمــة العامــة‬\n‫مبحافظــة جــده برقــم ‪ 34243280‬وتاريــخ ‪1434/6/17‬ه ـ ‪ ،‬املتضمــن‬\n‫دعــوى املــرأة ‪...‬ضــد ‪...‬يف نفقــه ‪ ،‬وبدراســة الصــك وصــورة ضبطــه‬\n‫والئحتــه االعتراضيــة ‪ ،‬تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪.‬‬\n                 ‫وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪292‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":287,"source_page_end":292,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"70d3a93bba133a36d574ccd4add6218126bc1d82b30dcc2a05f092b5374d8ada","normalized_text_hash":"be7526c8b27c498809122be1a9b97a8cf90c0c417142f755c960da2a48480c85","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p287-34243280"},{"id":"a8d05d4c-6770-51e5-8600-e464a016616e","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -املطالبة بتكاليف الوالدة -حتديد نفقة ماضية ومستقبله للطفل -نفقة احلامل -النفقة بنية الرجوع -دفع املدعى عليه بعدم أحقية املدعية لتكاليف الوالدة لوجود مستشفيات حكومية متاحة -تقدير النفقة عن طريق قسم اخلبراء -النشوز ال يسقط نفقة احلامل -اإللزام بدفع نفقة فترة احلمل ونفقة الطفل املاضية وحتديد نفقة مستقبلية للطفل .","document_number":"34263198","case_number":"32495714","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/9","year":"1434","subject":"نفقة -املطالبة بتكاليف الوالدة -حتديد نفقة ماضية ومستقبله للطفل -نفقة احلامل -النفقة بنية الرجوع -دفع املدعى عليه بعدم أحقية املدعية لتكاليف الوالدة لوجود مستشفيات حكومية متاحة -تقدير النفقة عن طريق قسم اخلبراء -النشوز ال يسقط نفقة احلامل -اإللزام بدفع نفقة فترة احلمل ونفقة الطفل املاضية وحتديد نفقة مستقبلية للطفل .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/7/9 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34263198 :‬‬\n                         ‫َر ْق ُم الدعوى‪32495714 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34320855‬تاريخه‪1434/9/16 :‬هـ‬\n\n\n\n      ‫نفقــة ‪ -‬املطالبــة بتكاليــف الــوالدة ‪ -‬حتديــد نفقــة ماضيــة ومســتقبله‬\n      ‫للطفــل ‪ -‬نفقــة احلامــل ‪ -‬النفقــة بنيــة الرجــوع‪ -‬دفــع املدعــى عليــه‬\n      ‫بعــدم أحقيــة املدعيــة لتكاليــف الــوالدة لوجــود مستشــفيات حكوميــة‬\n      ‫متاحــة‪ -‬تقديــر النفقــة عــن طريــق قســم اخلبــراء‪ -‬النشــوز ال يســقط‬\n      ‫نفقــة احلامــل ‪ -‬اإللــزام بدفــع نفقــة فتــرة احلمــل ونفقــة الطفــل‬\n                                 ‫املاضيــة وحتديــد نفقــة مســتقبلية للطفــل ‪.‬‬\n\n\n\n\n      ‫كـ َّـن أُوالتِ َح ْمــلٍ فَ َأ ْنفِ ُقــوا َع َل ْيهِ ـ َّـن َح َّتــى َي َض ْعـ َـن‬\n                                                                                          ‫‪ -1‬قولــه تعالــى ( َو ِإ ْن ُ‬\n                                                                                                             ‫َح ْم َل ُهـ َّـن )‬\n      ‫‪ -2‬قــال يف الــروض املربــع (‪ )115/7‬والنفقــة للبائــن احلامــل (للحمــل)‬\n      ‫نفســه ال لهــا مــن أجلــه ألنهــا جتــب بوجــوده وتســقط بعدمــه فتجــب‬\n                                                                                                         ‫حلامــل ناشــز‬\n\n\n\n\n      ‫ادعــى وكيــل املدعيــة بــأن املدعــى عليــه أصالــة تزوج موكلتــه ثم طلقها‬\n      ‫وهــي حامــل وقــد وضعــت مولــود ًا ذكــر ًا ‪ -‬طلــب املدعــي وكالــة إلــزام‬\n      ‫املدعــي عليــه بدفــع تكاليــف الــوالدة وحتديــد نفقــه مســتقبله للطفــل ‪-‬‬\n      ‫أقــر املدعــى عليــه وكالــة مبــا جــاء يف الدعــوى وقــرر أنــه ال مانــع لــدى‬\n‫‪293‬‬\n\f‫موكلــه مــن حتديــد نفقــه مســتقبله لطفلــه أمــا تكاليــف الــوالدة فطلــب‬\n‫مهلــه للرجــوع ملوكلــه‪ -‬يف جلســه أخــرى قــرر املدعــى وكالــه أنــه يطلب‬\n‫نفقــه احلمــل ملوكلتــه تســعة أشــهر‪ -‬كمــا قــرر بــأن موكلتــه أنفقــت‬\n‫علــى الطفــل بنيــة الرجــوع علــى املدعــى عليــه‪ -‬صــادق املدعــى عليــه أن‬\n‫املدعيــة خرجــت مــن بيتــه وهــي يف الشــهر األول مــن احلمــل وقــرر أنــه غير‬\n‫مســتعد بدفــع نفقــة احلمــل ألنهــا ناشــز‪ -‬قــرر املدعــى عليــه اســتعداده‬\n‫بدفــع نفقــة ابنــه املاضيــة واملســتقبلية‪ -‬قــرر املدعــى عليــه بــأن املدعيــة‬\n‫الحــق لهــا يف تكاليــف الــوالدة ألن هنــاك مستشــفيات حكوميــة‬\n‫متاحــة‪ -‬وذهابهــا ملستشــفى أهلــي يعــد تبرع ـاً‪ -‬مت تقديــر نفقــة الطفــل‬\n‫املاضيــة واملســتقبلة عــن طريــق قســم اخلبــراء‪ -‬حيــث إمنــا دفــع بــه املدعــى‬\n‫عليــه مــن نشــوز املدعيــة ال عبــرة بــه ألن النفقــة واجبــة للزوجــة احلامــل‬\n‫وان كانــت ناشــزاً‪ -‬كمــا أن مــا طلبتــه املدعيــة مــن تكاليــف الوالدة ال‬\n‫مســوغ لــه لوجــود مستشــفيات حكوميــة متاحــة‪ -‬صــدر احلكــم بإلــزام‬\n‫املدعــى عليــه بدفــع نفقــة فتــرة احلمــل ونفقــة الطفــل املاضيــة وحتديــد‬\n‫نفقــه مســتقبلة للطفــل تســلم لوالدتــه املدعيــة وصــرف النظــر عــن دعــوى‬\n‫املدعيــة فيمــا ســوى ذلــك‪ -‬قــرر الطرفــان عــدم القناعــة‪ -‬صــدق احلكــم‬\n                                                       ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 32495714‬وتاريــخ‬\n‫‪ 1432/11/04‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321378590‬وتاريــخ‬\n\n                                                                                       ‫‪294‬‬\n\f      ‫‪ 1432/11/04‬ه ـ ففــي يــوم الســبت املوافــق‪ 1434/01/17‬ه ـ افتتحت‬\n      ‫اجللســة الســاعة ‪ 09 : 15‬وفيهــا حضــر ‪ ،...‬ســعودي اجلنســية مبوجــب‬\n      ‫الهويــة الوطنيــة رقــم‪... :‬الوكيــل عــن ‪...‬مبوجــب الوكالــة الصــادرة مــن‬\n      ‫كتابــة العــدل الثانيــة بجنــوب جــدة برقــم‪ 35347 :‬يف‪1432/10/13 :‬هـ‬\n      ‫واملخــول لــه فيهــا حــق املرافعــة واملدافعــة واإلنــكار واالســتالم والتســليم‬\n      ‫للصكــوك‪ ،‬وحضــر حلضــوره‪ ،... :‬ســعودي اجلنســية مبوجــب الهويــة‬\n      ‫الوطنيــة رقــم‪... :‬الوكيــل عــن‪... :‬مبوجــب الوكالــة الصــادرة مــن كتابة‬\n      ‫العــدل الثانيــة مبكــة املكرمــة واملخــول لــه فيهــا حــق املرافعــة واملدافعــة‬\n      ‫وســماع الدعــوى والــرد عليهــا‪ ،‬وادعــى األول قائــا‪ :‬إن ‪...‬كان زوجــا‬\n      ‫ملوكلتــي وقــد طلقهــا طلقــة واحــدة بتاريــخ‪1432/9/20 :‬ه ـ وكانــت‬\n      ‫وقتهــا حامــا ووضعــت مولودهــا املســمى (‪ )...‬ولــم يراجعهــا‪ ،‬أطلــب‬\n      ‫إلــزام املدعــى عليــه بتحمــل تكاليــف الــوالدة البالــغ قدرهــا‪ :‬أربعــة آالف‬\n      ‫ريــال‪ ،‬وحتديــد نفقــة مســتقبلية قدرهــا‪ :‬ألــف وخمــس مئــة ريــال البــن‬\n      ‫املدعــى عليــه‪ ،‬هكــذا ادعــى‪ .‬وبعــرض ذلــك علــى املدعــى عليــه وكالــة‬\n      ‫أجــاب قائــا‪ :‬مــا ذكــره املدعــي وكالــة مــن الــزواج والطــاق وتاريخــه‬\n      ‫وصفتــه والولــد (‪ )...‬وأنهــا وضعــت احلمــل بعــد الطــاق فصحيــح‪ ،‬وال مــا‬\n      ‫نــع لــدى موكلــي مــن حتديــد نفقــة مســتقبلية ال تزيــد عــن خمــس مئــة‬\n      ‫ريــال‪ ،‬أمــا تكاليــف الــوالدة فأطلــب مهلــة للرجــوع ملوكلــي‪ ،‬هكــذا‬\n      ‫أجــاب‪ .‬ويف يــوم األحــد املوافــق‪ 1434/07/09‬ه ـ حضــر ‪...‬واملثبــت هويته‬\n      ‫ووكالتــه يف جلســة ســابقة وحضــر حلضــوره ‪...‬ســعودي اجلنســية مبوجــب‬\n      ‫الهويــة الوطنيــة رقــم ‪...‬ثــم قــرر املدعــي وكالــة قائــا‪ :‬إن موكلتــي‬\n      ‫خرجــت مــن منــزل املدعــى عليــه أصالــة وهــي حامــل يف بدايــة الشــهر‬\n      ‫األول وقــد مكــث حملهــا تســعة أشــهر‪ ،‬وأطلــب إلزامــه بســداد نفقتهــا‬\n\n\n‫‪295‬‬\n\f‫أثنــاء حملهــا‪ ،‬وتكاليــف الــوالدة البالــغ قدرهــا‪ :‬أربعــة عشــر ألــف‬\n‫ريــال‪ ،‬وقــد كانــت موكلتــي تنفــق علــى ابــن املدعــى عليــه ‪...‬مــن تاريــخ‪:‬‬\n‫‪1433/5/8‬ه ـ بنيــة الرجــوع‪ ،‬أطلــب إلزامــه بســداد النفقــة الســابقة‬\n‫وحتديــد نفقــة مســتقبلية البنــه‪ )...( :‬اعتبــارا مــن تاريــخ‪1434/7/9 :‬ه ـ‬\n‫هكــذا قــرر‪ .‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا‪ :‬صحيــح أن‬\n‫املدعيــة خرجــت مــن منزلــي وهــي يف الشــهر األول مــن حملهــا وأنــا غيــر‬\n‫مســتعد بتســليم النفقــة ألنهــا خرجــت ناشــزا‪ ،‬وأمــا ابنــي ‪...‬فمنــذ تاريــخ‬\n‫والدتــه ‪1433/5/8‬ه ـ حتــى تاريــخ‪1434/7/8 :‬ه ـ لــم أنفــق عليــه إطالقا‬\n‫ألنهــم قالــوا لــي ال نأخذهــا منــك إال يف احملاكــم لتشــويه ســمعتك‪ ،‬أمــا‬\n‫تكاليــف الــوالدة فليــس لهــا حــق فيهــا إطالقــا ألن هنــاك مستشــفيات‬\n‫حكوميــة متاحــة وأنــا عســكري واملستشــفى العســكري متــاح لهــا‬\n‫وذهابهــا ملستشــفى أهلــي يعــد تبرعــا منهــا وأطلــب رد دعــوى املدعيــة‬\n                                        ‫وإخــاء ســبيلي منهــا‪ ،‬هكــذا أجــاب‪.‬‬\n‫وكنــا قــد كتبنــا لقســم اخلبــراء باحملكمــة لتحديــد النفقــة فوردنــا‬\n‫اجلــواب برقــم‪ 34216389 :‬يف‪1434/07/04 :‬ه ـ وبرفقهــا محضــر‬\n‫ونــص احلاجــة منــه‪( :‬وقــال املدعــي وكالــة أطلــب حتديــد نفقــة البــن‬\n‫موكلتــي املســمى ‪...‬ويبلــغ مــن العمــر مــا يقــارب عشــرة أشــهر واملولــود‬\n‫بتاريــخ‪1433/05/08 :‬ه ـ وبســؤال املدعــى عليــه وكالة قــال ال مانع من‬\n‫حتديــد نفقــة البــن موكلــي بحــدود خمســمائة ريــال حيــث أن موكلــي‬\n‫ال يســتطيع أن يدفــع أكثــر مــن ذلــك وحيــث متــت مخاطبــة عمــل املدعــى‬\n‫عليــه وردتنــا اإلفــادة املرفقــة التــي توضــح بــأن راتــب املدعــى عليــه‬\n‫أربعــة عشــر ألــف وأربــع مئــة واثنــا عشــر ريــال وســتون هللــه‪ ،‬وحيــث‬\n‫األمــر مــا ذكــر فإننــا نــرى والــرأي لكــم بــأن تكــون النفقــة بواقــع‬\n\n\n                                                                                    ‫‪296‬‬\n\f      ‫ألــف ريــال شــهريا اعتبــارا مــن شــهر ‪ 7‬لعــام ‪1434‬ه ـ وتكــون النفقــة‬\n      ‫الســابقة ومدتهــا ‪ 13‬ثالثــة عشــر شــهرا بواقــع ثالثــة عشــر ألــف ريــال‬\n      ‫وتكــون كســوة العيــد ألــف ريــال)‪ .‬ا‪ .‬ه ـ فبنــاء علــى مــا ســلف‪ ،‬وألن‬\n      ‫املدعيــة طالبــت بقيمــة والدتهــا يف املستشــفى وقدرهــا‪ :‬أربعــة عشــر ألــف‬\n      ‫ريــال وامتنــع املدعــى عليــه مــن تســليمها‪ ،‬وطلــب املدعيــة غيــر وجيــه‬\n      ‫ألن الــوالدة ممكنــة يف املستشــفيات احلكوميــة فتكلُّفهــا يف غيــر‬\n      ‫احلكوميــة‪ ،‬ومبــا أن املدعيــة‬\n                                 ‫ّ‬               ‫مح ّلــه ألن لهــا مندوحــة يف املستشــفيات‬\n      ‫طالبــت بالنفقــة فتــرة احلمــل وامتنــع املدعــى عليــه مــن تســليمها ودفــع‬\n      ‫بأنهــا ناشــز ودفعــه هــذا ال وجــه لــه ألنــه يجــب علــى الــزوج اإلنفــاق‬\n            ‫(و ِإنْ ُ‬\n      ‫كـ َّـن‬      ‫علــى الزوجــة احلامــل ولــو كانــت ناشــزا لقــول اهلل ـ تعالــى ـ َ‬\n      ‫والت َح ْمـ ٍـل َف َأ ْنفِ ُقــوا َع َل ْي ِهـ َّـن َح َّتــى َي َض ْعـ َـن َح ْم َل ُهـ َّـن)‪ ،‬قــال يف الــروض‬\n                                                                                                                  ‫ُأ ِ‬\n      ‫املربــع ‪([ 115/7‬والنفقــة) للبائــن احلامــل (للحمــل) نفســه (ال لهــا مــن‬\n      ‫أجلــه) ألنهــا جتــب بوجــوده وتســقط بعدمــه فتجــب حلامــل ناشــز)] وبنــاء‬\n      ‫علــى قــرار قســم اخلبــراء املرصــود أعــاه لذلــك كلــه فقــد قــررت مــا‬\n      ‫يلــي‪ ،‬أوال‪ :‬ألزمــت املدعــى عليــه أن يســلم للمدعيــة نفقتهــا فتــرة حملهــا‬\n      ‫وقدرهــا‪ :‬تســعة آالف ريــال‪ .‬ثانيــا‪ :‬ألزمــت املدعــى عليــه أن يســلم نفقــة‬\n      ‫ابنــه ‪...‬الســابقة مــن تاريــخ‪1433/5/8 :‬ه ـ حتــى تاريــخ‪1434/7/8 :‬ه ـ‬\n      ‫وقدرهــا‪ :‬أربعــة عشــر ألــف ريــال‪ .‬ثالثــا‪ :‬ألزمــت املدعــى عليــه أن يســلم‬\n      ‫نفقــة ابنــه ‪...‬املســتقبلية لوالدتــه املدعيــة وقدرهــا‪ :‬ألــف ريــال اعتبــارا‬\n      ‫مــن تاريــخ‪1434/8/8 :‬ه ـ رابعــا‪ :‬رددت طلــب املدعيــة فيمــا ســوى ذلــك‪،‬‬\n      ‫ـتعدا‬\n         ‫وبذلــك قضيــت‪ .‬وبإعــان احلكــم قــرر الطرفــن عــدم القناعــة واسـ ّ‬\n      ‫اعتراضيــة‪ ،‬فجــرى تســليم كل واحــد منهمــا نســخة مــن‬‫ّ‬          ‫بتقــدمي الئحــة‬\n      ‫احلكــم وأفهمتهمــا بــأن لهمــا احلــق يف تقــدمي اعتراضهمــا خــال ثالثــن‬\n\n\n‫‪297‬‬\n\f‫يوم ـ ًا اعتبــار ًا مــن هــذا اليــوم‪ ،‬وإذا انتهــت املـ ّـدة احملــددة ولــم يقــدم أي‬\n‫القطعيــة‪.‬‬\n    ‫ّ‬        ‫حقــه يف االعتــراض واكتســب احلكــم‬      ‫منهــم بالئحتــه ســقط ّ‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                           ‫وســلم ‪ .‬حــرر يف ‪ 1434/07/09‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬ويف يــوم الثالثــاء املوافــق‪1434/10/13 :‬ه ـ‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا قــرار دائــرة األحــوال‬\n‫الشــخصية الثالثــة رقــم‪ 34320855 :‬يف‪1434/09/16 :‬ه ـ ونص احلاجة‬\n‫منــه‪( :‬وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيتــن تقــررت‬\n‫املوافقــة علــى احلكــم)‪ .‬ا‪ .‬ه ـ وللبيــان جــرى إثباتــه‪ ،‬وأمــرت بإحلــاق ذلــك‬\n‫علــى الصــك والســجل‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                    ‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/10/13 :‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n‫والوصايــا والقصــار وبيــوت املــال مبحكمة االســتئناف يف منطقة مكة‬\n‫املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة جــدة برقــم ‪ 32/1378590‬وتاريــخ ‪1434/9/8‬ه ـ‬\n‫املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪...‬القاضــي باحملكمــة‬\n‫العامــة مبحافظــة جــدة برقــم ‪ 34263198‬وتاريــخ ‪1434/7/9‬ه ـ ‪،‬‬\n‫املتضمــن دعــوى املــرأة ‪...‬ضــد ‪...‬يف نفقــة ‪ ،‬وبدراســة الصــك وصــورة‬\n‫ضبطــه والئحتيــه االعتراضيتــن تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل‬\n      ‫املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                            ‫‪298‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":293,"source_page_end":298,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"24b017ef2df35caa190eff640424877b261e51b32c78e36a0aafd9025bfc751c","normalized_text_hash":"a959c12a39caabeb63378e55e4c4eda88a58a987c0c7ca930132ed3cf6d74548","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p293-34263198"}]$archive_payload$::jsonb) AS x LIMIT 25
